window.__X_NEWS__ = {"date": "2026-10-22", "updated_at": "2026-10-23 07:57 Asia/Shanghai", "updated_at_iso": "2026-10-22T23:57:28.000Z", "count": 92, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2113035835780001819", "domain": "科技", "title_en": "Demis Hassabis Shortens AGI Timeline to Two or Three Years", "title_zh": "哈萨比斯将 AGI 时间表缩短至两到三年", "hook_en": "Demis Hassabis just pulled his AGI prediction closer, now seeing it in just two to three years. It's a shift that's got people talking about how fast AI might match human smarts.", "hook_zh": "谷歌 DeepMind 联合创始人德米斯·哈萨比斯把通用人工智能到来时间再次提前，称大约只需两到三年。", "summary_en": "In a Wall Street Journal profile on October 21, Google DeepMind co-founder Demis Hassabis updated his artificial general intelligence timeline from three to five years down to two or three, saying it's moving 'nearer and nearer.' He defines AGI as a system matching the full cognitive range of the human brain and proposed a test: recreating Einstein's 1905 relativity papers from pre-1901 knowledge. Hassabis, now Alphabet's chief scientist and focused on AI drug discovery at Isomorphic Labs, stressed safely stewarding AGI for humanity's benefit, comparing its impact to '10 times the industrial revolution at 10 times the speed.' Reactions ranged from excitement over even shorter timelines to skepticism about past overhyped predictions like self-driving cars.", "summary_zh": "在 10 月 21 日《华尔街日报》人物特写中，哈萨比斯把原先三到五年的 AGI 预估收紧为两到三年，并称它「越来越近」。他把 AGI 定义为能覆盖人脑全部认知范围的系统，并提出测试：仅凭 1901 年前的知识复现爱因斯坦 1905 年相对论论文。现任 Alphabet 首席科学家、主导 Isomorphic Labs AI 药物发现的他强调，需为人类福祉安全引导 AGI，并将其影响比作「十倍工业革命、十倍速度」。外界有人兴奋于更短时间表，也有人对自动驾驶等过往高估保持怀疑。", "body_en": "Demis Hassabis Shortens AGI Timeline to Two or Three Years.\n\nDemis Hassabis just pulled his AGI prediction closer, now seeing it in just two to three years. It's a shift that's got people talking about how fast AI might match human smarts.\n\nIn a Wall Street Journal profile on October 21, Google DeepMind co-founder Demis Hassabis updated his artificial general intelligence timeline from three to five years down to two or three, saying it's moving 'nearer and nearer.' He defines AGI as a system matching the full cognitive range of the human brain and proposed a test: recreating Einstein's 1905 relativity papers from pre-1901 knowledge. Hassabis, now Alphabet's chief scientist and focused on AI drug discovery at Isomorphic Labs, stressed safely stewarding AGI for humanity's benefit, comparing its impact to '10 times the industrial revolution at 10 times the speed.' Reactions ranged from excitement over even shorter timelines to skepticism about past overhyped predictions like self-driving cars.", "body_zh": "哈萨比斯将 AGI 时间表缩短至两到三年。\n\n谷歌 DeepMind 联合创始人德米斯·哈萨比斯把通用人工智能到来时间再次提前，称大约只需两到三年。\n\n在 10 月 21 日《华尔街日报》人物特写中，哈萨比斯把原先三到五年的 AGI 预估收紧为两到三年，并称它「越来越近」。他把 AGI 定义为能覆盖人脑全部认知范围的系统，并提出测试：仅凭 1901 年前的知识复现爱因斯坦 1905 年相对论论文。\n\n现任 Alphabet 首席科学家、主导 Isomorphic Labs AI 药物发现的他强调，需为人类福祉安全引导 AGI，并将其影响比作「十倍工业革命、十倍速度」。外界有人兴奋于更短时间表，也有人对自动驾驶等过往高估保持怀疑。", "url": "https://x.com/i/trending/2113035835780001819", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T22:40:44.000Z"}, {"id": "2112905930044317939", "domain": "科技", "title_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Nobel laureate David Baker sees a new era: designing proteins from scratch, not just discovering nature's own. This tool makes it faster and more reliable than ever.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "NVIDIA and the University of Washington's Institute for Protein Design released RFD4-Proteina, an open model that generates proteins and biomolecules up to 13 times faster than prior tools like RFdiffusion3. Born from a year-long collaboration between Baker Lab and NVIDIA’s GenAIR team, it unifies amino acids, sugars, DNA, and RNA in one space, enabling designs for drug binders and enzymes—including one that helps synthesize the HIV drug lenacapavir. Fully open-source on GitHub and Hugging Face, with free GPU access for two weeks, it promises to boost fields from drug discovery to industrial enzymes and protein design competitions.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T19:42:52.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国国土安全部令联邦机构清除 DeepSeek AI 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。 DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nThe U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.\n\nUnder a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services.\n\nThe order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "body_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。\n\n根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。\n\n该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI收购Orchestra Bio以加快药物开发", "hook_en": "OpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.", "hook_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。", "summary_en": "On October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk. Founder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "summary_zh": "2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。 创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nOpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.\n\nOn October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk.\n\nFounder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "body_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。\n\n2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。\n\n创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T12:34:03.000Z"}, {"id": "2112891431501390231", "domain": "科技", "title_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents", "title_zh": "NVIDIA推出OpenShell以保护企业AI代理", "hook_en": "At GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.", "hook_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。", "summary_en": "The OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0. Over 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "summary_zh": "OpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。 Anthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "body_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents.\n\nAt GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.\n\nThe OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0.\n\nOver 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "body_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。\n\nOpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。\n\nAnthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "url": "https://x.com/i/trending/2112891431501390231", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:02:53.000Z"}, {"id": "2112946155130904714", "domain": "科技", "title_en": "Coherence Neuro Raises $45M for Adaptive Brain Cancer Implant", "title_zh": "Coherence Neuro为适应性脑癌植入物筹集了4500万美元$", "hook_en": "Coherence Neuro's founders see cancer as an engineering puzzle they can solve with a smart brain implant that watches tumors and fights back in real time.", "hook_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”", "summary_en": "The San Francisco startup, led by CEO Ben Woodington and CTO Elise Jenkins, secured $45 million in Series A funding co-led by Founders Fund and OpenAI Startup Fund. Their SOMA device is an implantable brain-computer interface that monitors electrical signals from brain tumors like glioblastoma and delivers targeted stimulation to adapt treatment instantly. Early safety tests happened during tumor surgeries at Royal Melbourne Hospital in Australia, and the funds will push forward long-term clinical trials for a wireless, MRI-safe system with a wearable power source and app.", "summary_zh": "这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。 它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "body_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'\n\nThe San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable.\n\nIt builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "body_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”\n\n这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。\n\n它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "url": "https://x.com/i/trending/2112946155130904714", "category": "News", "topics": ["Business & Finance", "Entrepreneurship", "Technology", "Biotech"], "updated_at": "2026-10-22T04:28:31.000Z"}, {"id": "2113353723061617000", "domain": "科技", "title_en": "Dwarkesh Patel Tours Intel's Advanced Oregon Fab and Talks Chip Future", "title_zh": "Dwarkesh Patel 参观英特尔俄勒冈先进晶圆厂并讨论芯片未来", "hook_en": "Dwarkesh Patel got an up-close look at Intel's cutting-edge Oregon fab, chatting with experts about the marathon engineering behind tomorrow's AI chips.", "hook_zh": "Dwarkesh Patel 近距离参观英特尔俄勒冈顶尖晶圆厂，与专家畅谈支撑下一代 AI 芯片的漫长工程之路。", "summary_en": "Patel spent two days touring Intel's most advanced fabrication facility in Oregon, joined by process leader Chris Auth and CTO Pushkar Ranade for deep dives into gate-all-around transistors, PowerVia backside power on the 18A node, and High-NA EUV lithography. They explained how Intel's backside power approach eases frontside constraints, enabling single-exposure printing that rivals like TSMC might handle differently due to their architectures and timelines. The talk highlighted AI demand outpacing supply, with tool lead times at 18 months and Intel partnering with Elon Musk's Terafab for a 2028 AI chip facility, while packaging like hybrid bonding offers quicker gains amid physical limits on fabs and power.", "summary_zh": "Patel 用两天时间参观英特尔俄勒冈最先进的制造设施，与工艺负责人 Chris Auth、CTO Pushkar Ranade 深入讨论环绕栅极晶体管、18A 节点的 PowerVia 背面供电以及 High-NA EUV 光刻。他们解释英特尔背面供电可缓解正面布线约束，实现单次曝光，而台积电等对手因架构与时间表不同可能另辟蹊径。对话强调 AI 需求已超过供应，设备交期约 18 个月；英特尔还与马斯克的 Terafab 合作规划 2028 年 AI 芯片厂，同时混合键合等先进封装可在晶圆厂与电力物理上限下更快见效。", "body_en": "Dwarkesh Patel Tours Intel's Advanced Oregon Fab and Talks Chip Future.\n\nDwarkesh Patel got an up-close look at Intel's cutting-edge Oregon fab, chatting with experts about the marathon engineering behind tomorrow's AI chips.\n\nPatel spent two days touring Intel's most advanced fabrication facility in Oregon, joined by process leader Chris Auth and CTO Pushkar Ranade for deep dives into gate-all-around transistors, PowerVia backside power on the 18A node, and High-NA EUV lithography.\n\nThey explained how Intel's backside power approach eases frontside constraints, enabling single-exposure printing that rivals like TSMC might handle differently due to their architectures and timelines. The talk highlighted AI demand outpacing supply, with tool lead times at 18 months and Intel partnering with Elon Musk's Terafab for a 2028 AI chip facility, while packaging like hybrid bonding offers quicker gains amid physical limits on fabs and power.", "body_zh": "Dwarkesh Patel 参观英特尔俄勒冈先进晶圆厂并讨论芯片未来。\n\nDwarkesh Patel 近距离参观英特尔俄勒冈顶尖晶圆厂，与专家畅谈支撑下一代 AI 芯片的漫长工程之路。\n\nPatel 用两天时间参观英特尔俄勒冈最先进的制造设施，与工艺负责人 Chris Auth、CTO Pushkar Ranade 深入讨论环绕栅极晶体管、18A 节点的 PowerVia 背面供电以及 High-NA EUV 光刻。\n\n他们解释英特尔背面供电可缓解正面布线约束，实现单次曝光，而台积电等对手因架构与时间表不同可能另辟蹊径。对话强调 AI 需求已超过供应，设备交期约 18 个月；英特尔还与马斯克的 Terafab 合作规划 2028 年 AI 芯片厂，同时混合键合等先进封装可在晶圆厂与电力物理上限下更快见效。", "url": "https://x.com/i/trending/2113353723061617000", "category": "News", "topics": ["Podcasts"], "updated_at": "2026-10-22T19:46:01.000Z"}, {"id": "2113325561112105410", "domain": "科技", "title_en": "Commerce Awards $389 Million for Fusion and AI Power Semiconductors", "title_zh": "美国商务部为核聚变与 AI 功率半导体拨款最高 3.89 亿美元", "hook_en": "Fusion startups like Helion are getting a major funding boost to build semiconductors that handle massive power surges for clean energy breakthroughs.", "hook_zh": "Helion 等核聚变初创公司获得大额资助，用于研制能承受巨大功率冲击的半导体，推动清洁能源突破。", "summary_en": "The U.S. Department of Commerce issued letters of intent for up to $389 million in CHIPS Act funding to develop advanced power semiconductors for nuclear fusion, AI data centers, and the semiconductor supply chain. Helion secured up to $175 million for high-voltage chips to support its pulsed fusion systems in Washington and Vermont, creating over 100 jobs alongside $50 million in private investment. Commonwealth Fusion Systems received up to $85 million for plasma heating and radiation-hardened components, while Vertical Semiconductor and Sibelco got funds for AI-efficient chips and high-purity quartz. These steps aim to onshore critical tech, tackle fusion bottlenecks, and meet rising electricity demands.", "summary_zh": "美国商务部发出意向函，拟通过《芯片与科学法案》提供最高约 3.89 亿美元，用于研发面向核聚变、AI 数据中心与半导体供应链的先进功率半导体。Helion 最高可获 1.75 亿美元，为华盛顿州与佛蒙特州脉冲聚变系统研制高压芯片，并带动超 100 个就业岗位及约 5000 万美元私人投资。Commonwealth Fusion Systems 最高约 8500 万美元用于等离子体加热与抗辐射部件；Vertical Semiconductor 与 Sibelco 则获资助研发更省电的 AI 芯片与高纯石英。此举旨在关键技术回流、疏解聚变瓶颈，并应对不断攀升的电力需求。", "body_en": "Commerce Awards $389 Million for Fusion and AI Power Semiconductors.\n\nFusion startups like Helion are getting a major funding boost to build semiconductors that handle massive power surges for clean energy breakthroughs.\n\nThe U.S. Department of Commerce issued letters of intent for up to $389 million in CHIPS Act funding to develop advanced power semiconductors for nuclear fusion, AI data centers, and the semiconductor supply chain.\n\nHelion secured up to $175 million for high-voltage chips to support its pulsed fusion systems in Washington and Vermont, creating over 100 jobs alongside $50 million in private investment. Commonwealth Fusion Systems received up to $85 million for plasma heating and radiation-hardened components, while Vertical Semiconductor and Sibelco got funds for AI-efficient chips and high-purity quartz. These steps aim to onshore critical tech, tackle fusion bottlenecks, and meet rising electricity demands.", "body_zh": "美国商务部为核聚变与 AI 功率半导体拨款最高 3.89 亿美元。\n\nHelion 等核聚变初创公司获得大额资助，用于研制能承受巨大功率冲击的半导体，推动清洁能源突破。\n\n美国商务部发出意向函，拟通过《芯片与科学法案》提供最高约 3.89 亿美元，用于研发面向核聚变、AI 数据中心与半导体供应链的先进功率半导体。Helion 最高可获 1.75 亿美元，为华盛顿州与佛蒙特州脉冲聚变系统研制高压芯片，并带动超 100 个就业岗位及约 5000 万美元私人投资。\n\nCommonwealth Fusion Systems 最高约 8500 万美元用于等离子体加热与抗辐射部件；Vertical Semiconductor 与 Sibelco 则获资助研发更省电的 AI 芯片与高纯石英。此举旨在关键技术回流、疏解聚变瓶颈，并应对不断攀升的电力需求。", "url": "https://x.com/i/trending/2113325561112105410", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-22T17:53:09.000Z"}, {"id": "2113050908607275108", "domain": "科技", "title_en": "AI Agents Race Ahead with Proactive Helpers from Major Players", "title_zh": "主动型 AI 助手竞速：各大厂推出个人智能体", "hook_en": "Imagine an AI that checks your apps, sends daily briefs, and handles tasks even when you're away— that's the new wave of personal agents drawing users in.", "hook_zh": "想象一个会检查你的应用、发送每日简报、即使你不在也能办事的 AI——这类主动个人智能体正吸引用户。", "summary_en": "Anthropic launched a research preview of Claude Duet, a standalone app for iOS, Android, and web that monitors connected apps, flags items needing attention, and works on its own cloud computer with user approval for sensitive actions. It targets professionals and small business owners, joining Meta’s Muse and OpenAI’s Dots in offering always-on help that browses, uses tools, and persists across sessions. Users note these agents build loyalty through deep user knowledge and high engagement, while Google’s absence stands out despite its strong integrations with Gmail, Drive, and other services. The shift highlights a move from raw model intelligence to becoming someone's daily default AI.", "summary_zh": "Anthropic 发布 Claude Duet 研究预览版，覆盖 iOS、Android 与网页，可监控已连接应用、标记待办事项，并在自有云电脑上运行，敏感操作需用户批准。面向专业人士与小企业主，它与 Meta 的 Muse、OpenAI 的 Dots 一样提供常开式帮助：可浏览、调用工具、跨会话持续。用户称这些智能体凭深度用户画像与高互动建立黏性；谷歌虽与 Gmail、Drive 等整合强劲却显得缺席。行业正从比拼原始模型智力，转向争夺成为用户的默认日常 AI。", "body_en": "AI Agents Race Ahead with Proactive Helpers from Major Players.\n\nImagine an AI that checks your apps, sends daily briefs, and handles tasks even when you're away— that's the new wave of personal agents drawing users in.\n\nAnthropic launched a research preview of Claude Duet, a standalone app for iOS, Android, and web that monitors connected apps, flags items needing attention, and works on its own cloud computer with user approval for sensitive actions. It targets professionals and small business owners, joining Meta’s Muse and OpenAI’s Dots in offering always-on help that browses, uses tools, and persists across sessions.\n\nUsers note these agents build loyalty through deep user knowledge and high engagement, while Google’s absence stands out despite its strong integrations with Gmail, Drive, and other services. The shift highlights a move from raw model intelligence to becoming someone's daily default AI.", "body_zh": "主动型 AI 助手竞速：各大厂推出个人智能体。\n\n想象一个会检查你的应用、发送每日简报、即使你不在也能办事的 AI——这类主动个人智能体正吸引用户。\n\nAnthropic 发布 Claude Duet 研究预览版，覆盖 iOS、Android 与网页，可监控已连接应用、标记待办事项，并在自有云电脑上运行，敏感操作需用户批准。面向专业人士与小企业主，它与 Meta 的 Muse、OpenAI 的 Dots 一样提供常开式帮助：可浏览、调用工具、跨会话持续。\n\n用户称这些智能体凭深度用户画像与高互动建立黏性；谷歌虽与 Gmail、Drive 等整合强劲却显得缺席。行业正从比拼原始模型智力，转向争夺成为用户的默认日常 AI。", "url": "https://x.com/i/trending/2113050908607275108", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T23:40:29.000Z"}, {"id": "2112575527206969617", "domain": "科技", "title_en": "Gemini 4 Argon Processes 25 Trillion Tokens in First 72 Hours", "title_zh": "谷歌的Gemini 4 Argon在前72小时内处理了25万亿个代币", "hook_en": "Google's new AI model hit the ground running, handling a massive 25 trillion tokens right after going wide. Logan Kilpatrick called the early demand 'incredible' as users dove into its smarts.", "hook_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。", "summary_en": "Gemini 4 Argon launched broadly on October 13 after a limited cybersecurity debut on September 30, boasting a 1-million-token context window for coding, enterprise, and defense tasks. It shone in tests like detecting twice as many vulnerabilities as rivals and creating animated 3D periodic tables synced to song. A follow-up checkpoint, Gemini 4 Carbon, is in early testing, showing stronger 3D skills but some speed tradeoffs. While leading benchmarks, users note occasional crashes and delays amid Google's fast iteration pace.", "summary_zh": "Argon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。 Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "body_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.\n\nLaunched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window.\n\nIt leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "body_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。\n\nArgon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。\n\n它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "url": "https://x.com/i/trending/2112575527206969617", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-22T14:39:11.000Z"}, {"id": "2113322636885303671", "domain": "科技", "title_en": "SpaceXSI Launches Grok for Startups and Global Partner Network", "title_zh": "SpaceXSI 推出面向初创的 Grok 与全球合作伙伴网络", "hook_en": "SpaceXSI just made its powerful Grok AI tools easier for startups and big companies to grab. Founders now get credits and matches to build without the usual hurdles.", "hook_zh": "SpaceXSI 让初创与大企业更容易使用强大的 Grok AI 工具：创始人可获额度与匹配补贴，降低上手门槛。", "summary_en": "On October 22, SpaceXSI rolled out Grok for Startups, offering a shared credit balance across Grok, Grok Build, Grok Bot, and the Grok API—enough for six to twelve months of real use, with 20% available right away and dollar-for-dollar matches for up to six months. Early users are automating sales follow-ups, recruiting, reports, and even turning feature requests into code via cloud agents. At the same time, the new SpaceX Super Intelligence Partner Network connects over 130 companies like NVIDIA, Bain & Company, and Databricks, with a key deal alongside Tech Mahindra to modernize software in banking, healthcare, and more while keeping security tight.", "summary_zh": "10 月 22 日，SpaceXSI 推出 Grok for Startups，在 Grok、Grok Build、Grok Bot 与 Grok API 间共享额度，足以支撑约六至十二个月真实使用；其中 20% 可立即动用，并提供最长六个月等额匹配。早期用户已在自动化销售跟进、招聘、报告，甚至用云端智能体把功能需求变成代码。与此同时，SpaceX Super Intelligence Partner Network 汇聚 NVIDIA、贝恩、Databricks 等 130 多家公司，并与 Tech Mahindra 达成关键合作，在银行、医疗等领域推进软件现代化并严守安全。", "body_en": "SpaceXSI Launches Grok for Startups and Global Partner Network.\n\nSpaceXSI just made its powerful Grok AI tools easier for startups and big companies to grab. Founders now get credits and matches to build without the usual hurdles.\n\nOn October 22, SpaceXSI rolled out Grok for Startups, offering a shared credit balance across Grok, Grok Build, Grok Bot, and the Grok API—enough for six to twelve months of real use, with 20% available right away and dollar-for-dollar matches for up to six months.\n\nEarly users are automating sales follow-ups, recruiting, reports, and even turning feature requests into code via cloud agents. At the same time, the new SpaceX Super Intelligence Partner Network connects over 130 companies like NVIDIA, Bain & Company, and Databricks, with a key deal alongside Tech Mahindra to modernize software in banking, healthcare, and more while keeping security tight.", "body_zh": "SpaceXSI 推出面向初创的 Grok 与全球合作伙伴网络。\n\nSpaceXSI 让初创与大企业更容易使用强大的 Grok AI 工具：创始人可获额度与匹配补贴，降低上手门槛。\n\n10 月 22 日，SpaceXSI 推出 Grok for Startups，在 Grok、Grok Build、Grok Bot 与 Grok API 间共享额度，足以支撑约六至十二个月真实使用；其中 20% 可立即动用，并提供最长六个月等额匹配。\n\n早期用户已在自动化销售跟进、招聘、报告，甚至用云端智能体把功能需求变成代码。与此同时，SpaceX Super Intelligence Partner Network 汇聚 NVIDIA、贝恩、Databricks 等 130 多家公司，并与 Tech Mahindra 达成关键合作，在银行、医疗等领域推进软件现代化并严守安全。", "url": "https://x.com/i/trending/2113322636885303671", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-22T23:44:24.000Z"}, {"id": "2112910732203278366", "domain": "科技", "title_en": "Soluna and Applied Digital Partner on 50 MW Wind-Powered AI Data Center in Texas", "title_zh": "Soluna 与 Applied Digital 合作建设德州 50 兆瓦风电 AI 数据中心", "hook_en": "In the heart of Texas wind country, two companies are teaming up to power AI's future with clean energy from the source.", "hook_zh": "在德州风电腹地，两家公司联手用源头清洁能源为 AI 供能。", "summary_en": "Soluna Holdings and Applied Digital announced a joint venture Wednesday to build a 50 MW AI data center at Project Dorothy 3 in Briscoe County, next to the 150 MW Briscoe Wind Farm. The facility will draw power from wind generation and the ERCOT grid, with Applied Digital providing capital for a 51% stake and Soluna contributing land and assets for 49%. Soluna CEO John Belizaire highlighted how this tackles AI's biggest hurdle—energy access—by matching demand directly with renewable supply. The deal, set to close by year's end pending approvals, marks a step toward sustainable computing as industry watchers note the smart pairing of expertise.", "summary_zh": "Soluna Holdings 与 Applied Digital 周三宣布成立合资，在布里斯科县 Dorothy 3 项目旁建设 50 兆瓦 AI 数据中心，毗邻 150 兆瓦 Briscoe 风电场。设施将取电于风力发电与 ERCOT 电网；Applied Digital 出资持股 51%，Soluna 以土地与资产持股 49%。Soluna CEO John Belizaire 称此举直击 AI 最大瓶颈——能源可及性，把需求与可再生供给直接匹配。交易待审批，力争年底前完成，行业认为双方专长互补，是可持续算力的一步。", "body_en": "Soluna and Applied Digital Partner on 50 MW Wind-Powered AI Data Center in Texas.\n\nIn the heart of Texas wind country, two companies are teaming up to power AI's future with clean energy from the source.\n\nSoluna Holdings and Applied Digital announced a joint venture Wednesday to build a 50 MW AI data center at Project Dorothy 3 in Briscoe County, next to the 150 MW Briscoe Wind Farm. The facility will draw power from wind generation and the ERCOT grid, with Applied Digital providing capital for a 51% stake and Soluna contributing land and assets for 49%.\n\nSoluna CEO John Belizaire highlighted how this tackles AI's biggest hurdle—energy access—by matching demand directly with renewable supply. The deal, set to close by year's end pending approvals, marks a step toward sustainable computing as industry watchers note the smart pairing of expertise.", "body_zh": "Soluna 与 Applied Digital 合作建设德州 50 兆瓦风电 AI 数据中心。\n\n在德州风电腹地，两家公司联手用源头清洁能源为 AI 供能。\n\nSoluna Holdings 与 Applied Digital 周三宣布成立合资，在布里斯科县 Dorothy 3 项目旁建设 50 兆瓦 AI 数据中心，毗邻 150 兆瓦 Briscoe 风电场。设施将取电于风力发电与 ERCOT 电网；Applied Digital 出资持股 51%，Soluna 以土地与资产持股 49%。\n\nSoluna CEO John Belizaire 称此举直击 AI 最大瓶颈——能源可及性，把需求与可再生供给直接匹配。交易待审批，力争年底前完成，行业认为双方专长互补，是可持续算力的一步。", "url": "https://x.com/i/trending/2112910732203278366", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-21T14:21:59.000Z"}, {"id": "2112598856852488607", "domain": "科技", "title_en": "Perplexity Launches Fully Local AI Agent for Mac Users", "title_zh": "Perplexity 为 Mac 用户推出完全本地 AI 智能体", "hook_en": "Imagine handling tasks across your Mac apps and files without sending a single bit of data to the cloud. Perplexity just made that possible with its Computer agent running entirely on-device.", "hook_zh": "在 Mac 应用与文件间办事却不把任何数据送上云端——Perplexity 的 Computer 智能体现可完全本地运行。", "summary_en": "Perplexity updated its Mac app so Pro, Max, and Enterprise subscribers can use the Computer agent fully locally, powered by models like PPLX Pro or Qwen 3.6. It works with native apps such as Notes, Mail, and Numbers, processes files on-device for privacy, and skips paid credits or internet for these tasks—though it recommends Apple silicon Macs with 36 GB+ unified memory. Meanwhile, users are excited to find Apple's free on-device LLM built into the macOS terminal, accessible via command line for offline code generation and more. These steps show a push toward local AI for better privacy, cost savings, and reliable everyday use.", "summary_zh": "Perplexity 更新 Mac 应用，Pro、Max 与企业版用户可用由 PPLX Pro 或 Qwen 3.6 等驱动的 Computer 智能体完全本地运行。它可对接备忘录、邮件、Numbers 等原生应用，在设备上处理文件以保护隐私，且此类任务不消耗付费额度、也无需联网；建议使用统一内存 36GB 及以上的苹果芯片 Mac。与此同时，用户惊喜发现 macOS 终端内置免费本地大模型，可命令行离线生成代码。这些动作显示本地 AI 正为隐私、成本与日常可靠性发力。", "body_en": "Perplexity Launches Fully Local AI Agent for Mac Users.\n\nImagine handling tasks across your Mac apps and files without sending a single bit of data to the cloud. Perplexity just made that possible with its Computer agent running entirely on-device.\n\nPerplexity updated its Mac app so Pro, Max, and Enterprise subscribers can use the Computer agent fully locally, powered by models like PPLX Pro or Qwen 3.6. It works with native apps such as Notes, Mail, and Numbers, processes files on-device for privacy, and skips paid credits or internet for these tasks—though it recommends Apple silicon Macs with 36 GB+ unified memory.\n\nMeanwhile, users are excited to find Apple's free on-device LLM built into the macOS terminal, accessible via command line for offline code generation and more. These steps show a push toward local AI for better privacy, cost savings, and reliable everyday use.", "body_zh": "Perplexity 为 Mac 用户推出完全本地 AI 智能体。\n\n在 Mac 应用与文件间办事却不把任何数据送上云端——Perplexity 的 Computer 智能体现可完全本地运行。\n\nPerplexity 更新 Mac 应用，Pro、Max 与企业版用户可用由 PPLX Pro 或 Qwen 3.6 等驱动的 Computer 智能体完全本地运行。它可对接备忘录、邮件、Numbers 等原生应用，在设备上处理文件以保护隐私，且此类任务不消耗付费额度、也无需联网；建议使用统一内存 36GB 及以上的苹果芯片 Mac。\n\n与此同时，用户惊喜发现 macOS 终端内置免费本地大模型，可命令行离线生成代码。这些动作显示本地 AI 正为隐私、成本与日常可靠性发力。", "url": "https://x.com/i/trending/2112598856852488607", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T20:52:02.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Brings GPT-6 Models to Google Cloud Marketplace", "title_zh": "OpenAI 将 GPT-6 系列模型上架谷歌云市场", "hook_en": "Enterprises on Google Cloud can now tap OpenAI's cutting-edge AI without switching providers. It's a move that simplifies access to top models like GPT-6 Astra for coding and research.", "hook_zh": "谷歌云上的企业无需换云，即可使用 OpenAI 前沿模型；获取 GPT-6 Astra 等用于编程与研究更简单。", "summary_en": "OpenAI announced on October 21, 2026, that its frontier models including GPT-6 Astra, GPT-6.1 Sol, GPT-6 Luna, and Codex agent are coming to Google Cloud's Model Garden and Marketplace. Customers can buy them using existing commitments on a single invoice, with private previews underway and general availability soon. This follows OpenAI's expansion to AWS after ending Microsoft exclusivity in April 2026, while Microsoft stays the primary partner—giving businesses more choice in regulated industries with strong data controls. Google Cloud now offers all three major closed-source LLMs on one platform, easing enterprise adoption.", "summary_zh": "OpenAI 于 2026 年 10 月 21 日宣布，其前沿模型 GPT-6 Astra、GPT-6.1 Sol、GPT-6 Luna 以及 Codex 智能体将进入谷歌云 Model Garden 与 Marketplace。客户可用既有承诺额度在一张账单上采购，私人预览已启动，正式上线在即。此举继 2026 年 4 月结束微软独家后拓展至 AWS，微软仍是主要伙伴——让受监管行业在数据管控下有更多选择。谷歌云现可在同一平台提供三大主流闭源大模型，降低企业采用门槛。", "body_en": "OpenAI Brings GPT-6 Models to Google Cloud Marketplace.\n\nEnterprises on Google Cloud can now tap OpenAI's cutting-edge AI without switching providers. It's a move that simplifies access to top models like GPT-6 Astra for coding and research.\n\nOpenAI announced on October 21, 2026, that its frontier models including GPT-6 Astra, GPT-6.1 Sol, GPT-6 Luna, and Codex agent are coming to Google Cloud's Model Garden and Marketplace. Customers can buy them using existing commitments on a single invoice, with private previews underway and general availability soon.\n\nThis follows OpenAI's expansion to AWS after ending Microsoft exclusivity in April 2026, while Microsoft stays the primary partner—giving businesses more choice in regulated industries with strong data controls. Google Cloud now offers all three major closed-source LLMs on one platform, easing enterprise adoption.", "body_zh": "OpenAI 将 GPT-6 系列模型上架谷歌云市场。\n\n谷歌云上的企业无需换云，即可使用 OpenAI 前沿模型；获取 GPT-6 Astra 等用于编程与研究更简单。\n\nOpenAI 于 2026 年 10 月 21 日宣布，其前沿模型 GPT-6 Astra、GPT-6.1 Sol、GPT-6 Luna 以及 Codex 智能体将进入谷歌云 Model Garden 与 Marketplace。客户可用既有承诺额度在一张账单上采购，私人预览已启动，正式上线在即。\n\n此举继 2026 年 4 月结束微软独家后拓展至 AWS，微软仍是主要伙伴——让受监管行业在数据管控下有更多选择。谷歌云现可在同一平台提供三大主流闭源大模型，降低企业采用门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-22T18:19:08.000Z"}, {"id": "2112933585816781110", "domain": "商业", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z"}, {"id": "2113270293703635256", "domain": "商业", "title_en": "Apartment Executive Warns of Worst Housing Market in Decades", "title_zh": "公寓高管警告：多户住房市场或创数十年来最差", "hook_en": "Over dinner, a property manager for 150,000 apartments shared a grim reality: today's multifamily struggles top the savings and loan crisis, dot-com bust, and 2008 meltdown.", "hook_zh": "一位管理约 15 万套公寓的物业高管晚餐时直言：当前多户住宅困境已超过储贷危机、互联网泡沫与 2008 年崩盘。", "summary_en": "The executive detailed woes across apartment classes—from Class A tenants using credit cards for rent and living paycheck to paycheck, to Class B oversupply forcing rents below $700 in southern markets, and Class C rents stagnating amid rising costs and payment defaults. Lenders skip mortgage payments in standoffs with banks avoiding foreclosures, while deferred maintenance speeds building decay and pre-foreclosure hits decades-high levels. National data shows some Sun Belt vacancy drops, but overbuilding, tenant strains, and debt maturities signal a potential decade of pain or sudden collapse, as observers note exurban complexes serving families in good school districts.", "summary_zh": "该高管详述各档公寓困境：A 类租客刷信用卡交租、过着月光生活；南部市场 B 类供应过剩迫使租金跌破 700 美元；C 类租金停滞、成本上升且违约增多。贷款方与银行对峙、有人拖延按揭而银行回避止赎，延迟维修加速楼宇老化，预止赎升至数十年来高位。全国数据虽显示阳光带部分空置率回落，但过度建设、租客承压与债务到期暗示或将迎来十年阵痛甚至骤然崩溃；观察者还注意到服务于好学区家庭的远郊综合体。", "body_en": "Apartment Executive Warns of Worst Housing Market in Decades.\n\nOver dinner, a property manager for 150,000 apartments shared a grim reality: today's multifamily struggles top the savings and loan crisis, dot-com bust, and 2008 meltdown.\n\nThe executive detailed woes across apartment classes—from Class A tenants using credit cards for rent and living paycheck to paycheck, to Class B oversupply forcing rents below $700 in southern markets, and Class C rents stagnating amid rising costs and payment defaults.\n\nLenders skip mortgage payments in standoffs with banks avoiding foreclosures, while deferred maintenance speeds building decay and pre-foreclosure hits decades-high levels. National data shows some Sun Belt vacancy drops, but overbuilding, tenant strains, and debt maturities signal a potential decade of pain or sudden collapse, as observers note exurban complexes serving families in good school districts.", "body_zh": "公寓高管警告：多户住房市场或创数十年来最差。\n\n一位管理约 15 万套公寓的物业高管晚餐时直言：当前多户住宅困境已超过储贷危机、互联网泡沫与 2008 年崩盘。\n\n该高管详述各档公寓困境：A 类租客刷信用卡交租、过着月光生活；南部市场 B 类供应过剩迫使租金跌破 700 美元；C 类租金停滞、成本上升且违约增多。\n\n贷款方与银行对峙、有人拖延按揭而银行回避止赎，延迟维修加速楼宇老化，预止赎升至数十年来高位。全国数据虽显示阳光带部分空置率回落，但过度建设、租客承压与债务到期暗示或将迎来十年阵痛甚至骤然崩溃；观察者还注意到服务于好学区家庭的远郊综合体。", "url": "https://x.com/i/trending/2113270293703635256", "category": "News", "topics": ["Business & Finance", "Real Estate"], "updated_at": "2026-10-22T21:59:59.000Z"}, {"id": "2112915461406957899", "domain": "商业", "title_en": "Indian Markets Dip Despite Heavy Institutional Buying", "title_zh": "尽管机构购买量很大，但印度市场仍在下跌", "hook_en": "Institutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'", "hook_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”", "summary_en": "On October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling. Market breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "summary_zh": "2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。 这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "body_en": "Indian Markets Dip Despite Heavy Institutional Buying.\n\nInstitutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'\n\nOn October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling.\n\nMarket breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "body_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”\n\n2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。\n\n各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "url": "https://x.com/i/trending/2112915461406957899", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T18:35:48.000Z"}, {"id": "2112948932623978868", "domain": "商业", "title_en": "India's Core Industries Hit 7.9% Growth in September 2026", "title_zh": "印度核心产业在2026年9月创下30个月新高，增长7.9%", "hook_en": "India's factories and mines powered ahead in September, logging their strongest growth since tracking began two years ago.", "hook_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。", "summary_en": "Core industries output surged 7.9% year-on-year, up from 5.9% in August and far ahead of last September's 3.1%, with the index reaching 118.3. Iron ore jumped 18.4%, electricity rose 11.4%, and coal climbed 10.7%, while seven of nine sectors improved from the prior month. Fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil slipped 1.4%, but April-September growth doubled to 5.1%. Analysts credit infrastructure demand, power restocking, and refinery activity for the broad momentum ahead of festive season.", "summary_zh": "核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。 这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "body_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026.\n\nIndia's factories and mines powered up in September, delivering their strongest output in over two years.\n\nCore industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%.\n\nWhile fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "body_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。\n\n核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。\n\n虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "url": "https://x.com/i/trending/2112948932623978868", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T09:11:59.000Z"}, {"id": "2112825460593934566", "domain": "商业", "title_en": "India Prepares to Raise FDI Limit in Public Sector Banks to 49%", "title_zh": "印度拟将公营银行外商直接投资上限提至 49%", "hook_en": "Prime Minister Modi gathered with top economic advisors and Finance Minister Nirmala Sitharaman for a key meeting on the nation's economic path forward.", "hook_zh": "莫迪总理与顶级经济顾问、财长西塔拉曼开会，讨论国家经济前进路径。", "summary_en": "The Indian government is advancing a plan to increase foreign direct investment in public sector banks from 20% to 49%, with a draft Cabinet note now circulating for departmental input. The Reserve Bank of India supports the move to draw more foreign capital, noting that current foreign holdings—like 12.27% in Canara Bank and 11.07% in State Bank of India—remain far below the existing cap, unlike private banks allowing up to 74%. Proponents say it will ease capital raising for growth and lending, while some question the need given low current utilization; markets are closely tracking developments amid this high-level review.", "summary_zh": "印度政府推进把公营银行外商直接投资上限从 20% 提至 49%，内阁草案正在征求各部门意见。印度储备银行支持此举以吸引更多外资，并指出当前外资持股仍远低于现有上限——如卡纳拉银行约 12.27%、印度国家银行约 11.07%——而私人银行最高可至 74%。支持者认为有助银行筹集资本、扩大放贷；也有人质疑当前利用率偏低是否必要。市场正密切跟踪这一高层审议进展。", "body_en": "India Prepares to Raise FDI Limit in Public Sector Banks to 49%.\n\nPrime Minister Modi gathered with top economic advisors and Finance Minister Nirmala Sitharaman for a key meeting on the nation's economic path forward.\n\nThe Indian government is advancing a plan to increase foreign direct investment in public sector banks from 20% to 49%, with a draft Cabinet note now circulating for departmental input.\n\nThe Reserve Bank of India supports the move to draw more foreign capital, noting that current foreign holdings—like 12.27% in Canara Bank and 11.07% in State Bank of India—remain far below the existing cap, unlike private banks allowing up to 74%. Proponents say it will ease capital raising for growth and lending, while some question the need given low current utilization; markets are closely tracking developments amid this high-level review.", "body_zh": "印度拟将公营银行外商直接投资上限提至 49%。\n\n莫迪总理与顶级经济顾问、财长西塔拉曼开会，讨论国家经济前进路径。\n\n印度政府推进把公营银行外商直接投资上限从 20% 提至 49%，内阁草案正在征求各部门意见。印度储备银行支持此举以吸引更多外资，并指出当前外资持股仍远低于现有上限——如卡纳拉银行约 12.27%、印度国家银行约 11.07%——而私人银行最高可至 74%。\n\n支持者认为有助银行筹集资本、扩大放贷；也有人质疑当前利用率偏低是否必要。市场正密切跟踪这一高层审议进展。", "url": "https://x.com/i/trending/2112825460593934566", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:12:10.000Z"}, {"id": "2112954861562339745", "domain": "商业", "title_en": "Treasury Buys Back $750 Million in Debt as Foreign Holdings Hit Near-Record High", "title_zh": "美国财政部回购 7.5 亿美元国债，海外持仓接近纪录高位", "hook_en": "The U.S. Treasury quietly scooped up $750 million of its own longer-term bonds this week, a move that had crypto watchers cheering for Bitcoin.", "hook_zh": "美国财政部本周悄然回购 7.5 亿美元较长年期国债，加密市场人士为此为比特币欢呼。", "summary_en": "In a Treasury Inflation-Protected Securities operation, the department accepted the full $750 million target from over $4.75 billion in offers, targeting bonds maturing between 2028 and 2036 to smooth trading conditions. This brought October's buybacks to $20.8 billion total. At the same time, foreign investors boosted U.S. Treasury holdings by $83 billion in August to $9.33 trillion—the sixth-highest on record—with Canada and Belgium leading gains despite cuts from Japan and China. Observers see these steps as liquidity support that could ease pressure on yields and lift risk assets like Bitcoin.", "summary_zh": "在一次通胀保值国债操作中，财政部从逾 47.5 亿美元报价中全额接受 7.5 亿美元目标，标的为 2028–2036 年到期债券，以平滑交易条件。这使得 10 月回购总额达 208 亿美元。与此同时，外国投资者 8 月增持美国国债 830 亿美元至 9.33 万亿美元——为纪录第六高——加拿大与比利时领涨，日本与中国则有所减持。观察者认为这些举措可支撑流动性、缓解收益率压力，并提振比特币等风险资产。", "body_en": "Treasury Buys Back $750 Million in Debt as Foreign Holdings Hit Near-Record High.\n\nThe U.S. Treasury quietly scooped up $750 million of its own longer-term bonds this week, a move that had crypto watchers cheering for Bitcoin.\n\nIn a Treasury Inflation-Protected Securities operation, the department accepted the full $750 million target from over $4.75 billion in offers, targeting bonds maturing between 2028 and 2036 to smooth trading conditions. This brought October's buybacks to $20.8 billion total.\n\nAt the same time, foreign investors boosted U.S. Treasury holdings by $83 billion in August to $9.33 trillion—the sixth-highest on record—with Canada and Belgium leading gains despite cuts from Japan and China. Observers see these steps as liquidity support that could ease pressure on yields and lift risk assets like Bitcoin.", "body_zh": "美国财政部回购 7.5 亿美元国债，海外持仓接近纪录高位。\n\n美国财政部本周悄然回购 7.5 亿美元较长年期国债，加密市场人士为此为比特币欢呼。\n\n在一次通胀保值国债操作中，财政部从逾 47.5 亿美元报价中全额接受 7.5 亿美元目标，标的为 2028–2036 年到期债券，以平滑交易条件。这使得 10 月回购总额达 208 亿美元。\n\n与此同时，外国投资者 8 月增持美国国债 830 亿美元至 9.33 万亿美元——为纪录第六高——加拿大与比利时领涨，日本与中国则有所减持。观察者认为这些举措可支撑流动性、缓解收益率压力，并提振比特币等风险资产。", "url": "https://x.com/i/trending/2112954861562339745", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T23:16:34.000Z"}, {"id": "2113379006125142267", "domain": "商业", "title_en": "US Households Hit Record 48.2% Stock Allocation in Q2 2026", "title_zh": "美国家庭股票配置达 48.2% 创历史新高", "hook_en": "American families now have more money in stocks than ever before, topping even the dot-com bubble's peak. This shift puts household finances more tied to market swings than in past decades.", "hook_zh": "美国家庭金融资产中股票占比超过互联网泡沫峰值，家庭财务与市场波动绑定更深。", "summary_en": "Federal Reserve data shows US households held 48.2% of their financial assets in stocks during the second quarter of 2026, surpassing the 38.7% high from early 2000 and other historical marks like 33.5% in 2007. Investor Chamath Palihapitiya highlighted the trend with a simple 'stonks' chart, while Grant Cardone warned it's 24% above 2000 levels. Optimists credit apps and zero-commission trading for broader participation, especially among younger households, but skeptics flag risks to spending if markets drop, noting the top 1% hold over half of equities amid hedge funds ramping up shorts.", "summary_zh": "美联储数据显示，2026 年第二季度美国家庭金融资产中股票占比达 48.2%，超过 2000 年初的 38.7% 以及 2007 年的 33.5% 等历史高点。投资者 Chamath Palihapitiya 用「stonks」图强调趋势，Grant Cardone 则警告已比 2000 年高出约 24%。乐观者归功于零佣金交易与应用普及、尤其年轻家庭参与度上升；怀疑者则提醒市场下跌或冲击消费，并指出前 1% 持有逾半数股权，对冲基金也在加码做空。", "body_en": "US Households Hit Record 48.2% Stock Allocation in Q2 2026.\n\nAmerican families now have more money in stocks than ever before, topping even the dot-com bubble's peak. This shift puts household finances more tied to market swings than in past decades.\n\nFederal Reserve data shows US households held 48.2% of their financial assets in stocks during the second quarter of 2026, surpassing the 38.7% high from early 2000 and other historical marks like 33.5% in 2007.\n\nInvestor Chamath Palihapitiya highlighted the trend with a simple 'stonks' chart, while Grant Cardone warned it's 24% above 2000 levels. Optimists credit apps and zero-commission trading for broader participation, especially among younger households, but skeptics flag risks to spending if markets drop, noting the top 1% hold over half of equities amid hedge funds ramping up shorts.", "body_zh": "美国家庭股票配置达 48.2% 创历史新高。\n\n美国家庭金融资产中股票占比超过互联网泡沫峰值，家庭财务与市场波动绑定更深。\n\n美联储数据显示，2026 年第二季度美国家庭金融资产中股票占比达 48.2%，超过 2000 年初的 38.7% 以及 2007 年的 33.5% 等历史高点。\n\n投资者 Chamath Palihapitiya 用「stonks」图强调趋势，Grant Cardone 则警告已比 2000 年高出约 24%。乐观者归功于零佣金交易与应用普及、尤其年轻家庭参与度上升；怀疑者则提醒市场下跌或冲击消费，并指出前 1% 持有逾半数股权，对冲基金也在加码做空。", "url": "https://x.com/i/trending/2113379006125142267", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-22T21:23:29.000Z"}, {"id": "2112977625979204061", "domain": "商业", "title_en": "Nigerians Highlight Exchange Rate Stability's Boost to Economy", "title_zh": "尼日利亚人热议汇率稳定对经济的提振", "hook_en": "From market traders to students abroad, unpredictable Naira swings hit everyday Nigerians hard. Now, many are sharing an expert's call for steady exchange rates to bring real planning relief.", "hook_zh": "从市场交易员到海外留学生，奈拉剧烈波动冲击日常；许多人转发专家呼吁：稳定汇率才能真正便于规划。", "summary_en": "Finance expert Martins Okorowu explains in a widely shared article how exchange rate stability lets businesses import machinery, farmers buy fertilizer, and families cover foreign school fees without sudden cost shocks. Users praise Central Bank of Nigeria efforts like unifying exchange windows, which narrowed gaps with parallel markets, boosted inflows, and kept the Naira trading steadily around N1,330–N1,400 per dollar amid reserves over $50 billion. The discussion underscores how these steps help everyone—from manufacturers to job creators—plan with confidence and attract investment.", "summary_zh": "金融专家 Martins Okorowu 在一篇广为传播的文章中解释：汇率稳定让企业进口机械、农民购买化肥、家庭支付海外学费时免遭突发成本冲击。用户赞扬尼日利亚央行统一汇兑窗口等举措，缩小了与平行市场的价差、提振流入，并在外汇储备超 500 亿美元背景下把奈拉稳定在约每美元 1330–1400 奈拉。讨论强调这些步骤帮助制造商与就业创造者更有信心地规划并吸引投资。", "body_en": "Nigerians Highlight Exchange Rate Stability's Boost to Economy.\n\nFrom market traders to students abroad, unpredictable Naira swings hit everyday Nigerians hard. Now, many are sharing an expert's call for steady exchange rates to bring real planning relief.\n\nFinance expert Martins Okorowu explains in a widely shared article how exchange rate stability lets businesses import machinery, farmers buy fertilizer, and families cover foreign school fees without sudden cost shocks.\n\nUsers praise Central Bank of Nigeria efforts like unifying exchange windows, which narrowed gaps with parallel markets, boosted inflows, and kept the Naira trading steadily around N1,330–N1,400 per dollar amid reserves over $50 billion. The discussion underscores how these steps help everyone—from manufacturers to job creators—plan with confidence and attract investment.", "body_zh": "尼日利亚人热议汇率稳定对经济的提振。\n\n从市场交易员到海外留学生，奈拉剧烈波动冲击日常；许多人转发专家呼吁：稳定汇率才能真正便于规划。\n\n金融专家 Martins Okorowu 在一篇广为传播的文章中解释：汇率稳定让企业进口机械、农民购买化肥、家庭支付海外学费时免遭突发成本冲击。\n\n用户赞扬尼日利亚央行统一汇兑窗口等举措，缩小了与平行市场的价差、提振流入，并在外汇储备超 500 亿美元背景下把奈拉稳定在约每美元 1330–1400 奈拉。讨论强调这些步骤帮助制造商与就业创造者更有信心地规划并吸引投资。", "url": "https://x.com/i/trending/2112977625979204061", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T18:51:24.000Z"}, {"id": "2113277144415760863", "domain": "商业", "title_en": "Black Thursday Selloff Wipes $750 Billion from U.S. Markets Amid Oil Surge", "title_zh": "「黑色星期四」抛售：油价飙升美股蒸发约 7500 亿美元", "hook_en": "Global stocks plunged Thursday as oil prices spiked on Middle East tensions, erasing over $750 billion from U.S. markets in hours.", "hook_zh": "中东紧张推高油价，全球股市周四重挫，美国市场数小时内蒸发逾 7500 亿美元。", "summary_en": "Asian markets lost nearly $1 trillion early, setting a grim tone before Wall Street's sharp drop, with the S&P 500 tumbling and tech giants like Nvidia, Alphabet, Amazon, Meta, and Tesla down 1-6 percent or more. Brent crude soared above $112 a barrel—its highest since May—driven by Houthi attacks on Saudi sites, Aramco evacuations, and shipping disruptions in the Strait of Hormuz. President Trump warned of U.S. action against Iran soon, while warships deployed and personnel left Saudi Arabia, fueling fears of supply shocks, inflation, and central bank dilemmas amid slowing growth.", "summary_zh": "亚洲市场早盘蒸发近 1 万亿美元，为华尔街急跌定调；标普 500 下挫，英伟达、Alphabet、亚马逊、Meta、特斯拉等科技巨头跌幅约 1%–6% 或更多。布伦特原油飙破每桶 112 美元——为 5 月以来最高——受胡塞武装袭击沙特设施、阿美疏散及霍尔木兹海峡航运受阻推动。特朗普总统警告美国可能很快对伊朗采取行动，军舰部署、人员撤离沙特，加剧供应冲击、通胀与央行两难担忧，同时增长放缓。", "body_en": "Black Thursday Selloff Wipes $750 Billion from U.S. Markets Amid Oil Surge.\n\nGlobal stocks plunged Thursday as oil prices spiked on Middle East tensions, erasing over $750 billion from U.S. markets in hours.\n\nAsian markets lost nearly $1 trillion early, setting a grim tone before Wall Street's sharp drop, with the S&P 500 tumbling and tech giants like Nvidia, Alphabet, Amazon, Meta, and Tesla down 1-6 percent or more. Brent crude soared above $112 a barrel—its highest since May—driven by Houthi attacks on Saudi sites, Aramco evacuations, and shipping disruptions in the Strait of Hormuz.\n\nPresident Trump warned of U.S. action against Iran soon, while warships deployed and personnel left Saudi Arabia, fueling fears of supply shocks, inflation, and central bank dilemmas amid slowing growth.", "body_zh": "「黑色星期四」抛售：油价飙升美股蒸发约 7500 亿美元。\n\n中东紧张推高油价，全球股市周四重挫，美国市场数小时内蒸发逾 7500 亿美元。\n\n亚洲市场早盘蒸发近 1 万亿美元，为华尔街急跌定调；标普 500 下挫，英伟达、Alphabet、亚马逊、Meta、特斯拉等科技巨头跌幅约 1%–6% 或更多。\n\n布伦特原油飙破每桶 112 美元——为 5 月以来最高——受胡塞武装袭击沙特设施、阿美疏散及霍尔木兹海峡航运受阻推动。特朗普总统警告美国可能很快对伊朗采取行动，军舰部署、人员撤离沙特，加剧供应冲击、通胀与央行两难担忧，同时增长放缓。", "url": "https://x.com/i/trending/2113277144415760863", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T23:44:08.000Z"}, {"id": "2112867592407036230", "domain": "商业", "title_en": "Indonesia's President Defies MSCI Over Stock Market Downgrade Threat", "title_zh": "印尼总统硬刚 MSCI：拒绝股市降级威胁", "hook_en": "President Prabowo Subianto stared down global index giant MSCI in a televised cabinet meeting, declaring his nation won't bow to pressure from any outsider.", "hook_zh": "普拉博沃总统在电视转播的内阁会议上直面指数巨头 MSCI，称国家不会向任何外部压力低头。", "summary_en": "MSCI proposed shifting Indonesia's stock market from emerging to standalone status due to issues like poor transparency, concentrated ownership, and suspected trading manipulation, sparking the sharpest two-day drop in the Jakarta Composite Index in nearly 30 years. Prabowo responded boldly, telling his cabinet that Indonesia stands strong with courage and won't be intimidated, even as markets reel and investors worry about outflows. OJK's chairwoman supported the tone but affirmed ongoing reforms for better integrity and liquidity, with a final decision pending until mid-2027.", "summary_zh": "MSCI 提议因透明度不足、股权集中及疑似交易操纵等问题，将印尼股市从新兴市场调至独立地位，引发雅加达综合指数近 30 年来最剧烈的两日跌幅。普拉博沃强硬回应，告诉内阁印尼以勇气站稳、不受恐吓，尽管市场动荡、投资者担忧资金外流。金管局主席支持强硬语气，同时确认正推进提升诚信与流动性的改革，最终决定将等到 2027 年中。", "body_en": "Indonesia's President Defies MSCI Over Stock Market Downgrade Threat.\n\nPresident Prabowo Subianto stared down global index giant MSCI in a televised cabinet meeting, declaring his nation won't bow to pressure from any outsider.\n\nMSCI proposed shifting Indonesia's stock market from emerging to standalone status due to issues like poor transparency, concentrated ownership, and suspected trading manipulation, sparking the sharpest two-day drop in the Jakarta Composite Index in nearly 30 years.\n\nPrabowo responded boldly, telling his cabinet that Indonesia stands strong with courage and won't be intimidated, even as markets reel and investors worry about outflows. OJK's chairwoman supported the tone but affirmed ongoing reforms for better integrity and liquidity, with a final decision pending until mid-2027.", "body_zh": "印尼总统硬刚 MSCI：拒绝股市降级威胁。\n\n普拉博沃总统在电视转播的内阁会议上直面指数巨头 MSCI，称国家不会向任何外部压力低头。\n\nMSCI 提议因透明度不足、股权集中及疑似交易操纵等问题，将印尼股市从新兴市场调至独立地位，引发雅加达综合指数近 30 年来最剧烈的两日跌幅。\n\n普拉博沃强硬回应，告诉内阁印尼以勇气站稳、不受恐吓，尽管市场动荡、投资者担忧资金外流。金管局主席支持强硬语气，同时确认正推进提升诚信与流动性的改革，最终决定将等到 2027 年中。", "url": "https://x.com/i/trending/2112867592407036230", "category": "News", "topics": ["Business & Finance", "Stocks", "Politics"], "updated_at": "2026-10-22T08:35:13.000Z"}, {"id": "2113147019032166574", "domain": "商业", "title_en": "China's CSI 300 Enters Bear Market After 20% Drop", "title_zh": "中国沪深 300 自高点跌 20% 进入熊市", "hook_en": "China's main stock index has fallen 20% from its June peak, erasing $1.75 trillion in value amid the longest losing streak on record.", "hook_zh": "中国主要股指自 6 月高点下跌 20%，市值蒸发约 1.75 万亿美元，创纪录最长连跌。", "summary_en": "The CSI 300 benchmark is down after 11 straight weeks of declines, with Thursday's sharp selloff—dubbed 'Black Thursday'—wiping out nearly $1 trillion across major Asian markets including South Korea's Kospi, Japan's Nikkei, and Hong Kong's Hang Seng. Broad losses hit technology giants like Alibaba and Tencent, alongside sectors from manufacturing to finance, as retail investors pulled back. Analysts cite fading stimulus hopes, weak earnings, heavy AI spending doubts, and geopolitical tensions like surging oil prices as drivers, despite state funds buying to support prices.", "summary_zh": "沪深 300 连续 11 周下跌；周四急挫被称「黑色星期四」，韩国综指、日经与恒生等亚洲主要市场合计蒸发近 1 万亿美元。阿里巴巴、腾讯等科技巨头及制造到金融板块普跌，散户撤离。分析师归因于刺激预期消退、盈利疲软、AI 开支疑虑及油价飙升等地缘因素；尽管有国家队资金护盘，跌势仍在延续。", "body_en": "China's CSI 300 Enters Bear Market After 20% Drop.\n\nChina's main stock index has fallen 20% from its June peak, erasing $1.75 trillion in value amid the longest losing streak on record.\n\nThe CSI 300 benchmark is down after 11 straight weeks of declines, with Thursday's sharp selloff—dubbed 'Black Thursday'—wiping out nearly $1 trillion across major Asian markets including South Korea's Kospi, Japan's Nikkei, and Hong Kong's Hang Seng.\n\nBroad losses hit technology giants like Alibaba and Tencent, alongside sectors from manufacturing to finance, as retail investors pulled back. Analysts cite fading stimulus hopes, weak earnings, heavy AI spending doubts, and geopolitical tensions like surging oil prices as drivers, despite state funds buying to support prices.", "body_zh": "中国沪深 300 自高点跌 20% 进入熊市。\n\n中国主要股指自 6 月高点下跌 20%，市值蒸发约 1.75 万亿美元，创纪录最长连跌。\n\n沪深 300 连续 11 周下跌；周四急挫被称「黑色星期四」，韩国综指、日经与恒生等亚洲主要市场合计蒸发近 1 万亿美元。\n\n阿里巴巴、腾讯等科技巨头及制造到金融板块普跌，散户撤离。分析师归因于刺激预期消退、盈利疲软、AI 开支疑虑及油价飙升等地缘因素；尽管有国家队资金护盘，跌势仍在延续。", "url": "https://x.com/i/trending/2113147019032166574", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-22T15:41:46.000Z"}, {"id": "2112620331987062878", "domain": "商业", "title_en": "Investors Buy Record CDS to Guard Against AI Boom Collapse", "title_zh": "投资者创纪录买入 CDS 对冲 AI 热潮违约风险", "hook_en": "As AI companies borrow billions for data centers and chips, investors are snapping up insurance contracts at unprecedented levels to shield their portfolios from potential defaults.", "hook_zh": "AI 公司为数据中心与芯片大举举债之际，投资者以前所未有力度抢购违约保险，保护投资组合。", "summary_en": "Five-year credit default swap spreads for Meta and Nvidia hit all-time highs around 108 and 101 basis points this month, with similar records for Alphabet, Amazon, and Oracle seeing spreads more than double since January. Trading volumes in these hedges exploded from under $2 billion weekly in July to over $9 billion in September, amid $419 billion in record 2026 AI-related bond issuance led by hyperscalers. Warnings highlight risky data center debt flowing into pensions and endowments, echoing subprime concerns, though some cite strong tech revenues as a counterpoint.", "summary_zh": "Meta 与英伟达五年期信用违约互换利差本月分别升至约 108 与 101 基点的历史高位；Alphabet、亚马逊与甲骨文也创纪录，自 1 月以来利差翻倍有余。对冲成交量从 7 月每周不足 20 亿美元飙升至 9 月逾 90 亿美元，同期超大规模云厂商主导的 2026 年 AI 相关发债达创纪录的 4190 亿美元。警告称风险数据中心债务流入养老金与捐赠基金，令人联想起次贷；也有人指出科技收入强劲可作对冲。", "body_en": "Investors Buy Record CDS to Guard Against AI Boom Collapse.\n\nAs AI companies borrow billions for data centers and chips, investors are snapping up insurance contracts at unprecedented levels to shield their portfolios from potential defaults.\n\nFive-year credit default swap spreads for Meta and Nvidia hit all-time highs around 108 and 101 basis points this month, with similar records for Alphabet, Amazon, and Oracle seeing spreads more than double since January.\n\nTrading volumes in these hedges exploded from under $2 billion weekly in July to over $9 billion in September, amid $419 billion in record 2026 AI-related bond issuance led by hyperscalers. Warnings highlight risky data center debt flowing into pensions and endowments, echoing subprime concerns, though some cite strong tech revenues as a counterpoint.", "body_zh": "投资者创纪录买入 CDS 对冲 AI 热潮违约风险。\n\nAI 公司为数据中心与芯片大举举债之际，投资者以前所未有力度抢购违约保险，保护投资组合。\n\nMeta 与英伟达五年期信用违约互换利差本月分别升至约 108 与 101 基点的历史高位；Alphabet、亚马逊与甲骨文也创纪录，自 1 月以来利差翻倍有余。\n\n对冲成交量从 7 月每周不足 20 亿美元飙升至 9 月逾 90 亿美元，同期超大规模云厂商主导的 2026 年 AI 相关发债达创纪录的 4190 亿美元。警告称风险数据中心债务流入养老金与捐赠基金，令人联想起次贷；也有人指出科技收入强劲可作对冲。", "url": "https://x.com/i/trending/2112620331987062878", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T18:19:47.000Z"}, {"id": "2113041959728066952", "domain": "商业", "title_en": "S&P 500 Climbs 0.58% to 7,757 Amid Earnings and Resistance Watch", "title_zh": "标普 500 涨 0.58% 收于 7757，市场关注阻力位", "hook_en": "Traders breathed a bit easier as the S&P 500 nudged higher on October 21, reclaiming key moving averages despite late-session swings from VIX expiration.", "hook_zh": "10 月 21 日标普小幅回升、夺回关键均线，尽管尾盘受 VIX 到期扰动。", "summary_en": "The index rose 0.58% to close at 7,757.17, with SPY ending near 773.19 after hitting its daily high, boosted by positive SpaceX results and other tech names. Traders eyed stacked resistance at 775, 779.80, and 781.85, plotting put buys toward 760 or 755 if rallies falter, while noting QQQ's lag below its averages. Tesla reported flat $28.05 billion revenue and positive cash flow after hours, as Meta beat with $64.6 billion and strong guidance, keeping tech sentiment supportive yet mixed. Views split on next moves, with light volume signaling potential volatility ahead.", "summary_zh": "指数上涨 0.58% 收于 7757.17，SPY 收于约 773.19 并触及当日高点，受益于 SpaceX 等科技正面消息。交易员盯住 775、779.80、781.85 等层层阻力，若反弹失败则考虑买入看跌期权押注 760 或 755，并指出 QQQ 仍处均线下方。特斯拉盘后公布营收约 280.5 亿美元持平、现金流为正；Meta 报 646 亿美元并给出强劲指引，科技情绪喜忧参半。成交清淡暗示后市仍可能波动。", "body_en": "S&P 500 Climbs 0.58% to 7,757 Amid Earnings and Resistance Watch.\n\nTraders breathed a bit easier as the S&P 500 nudged higher on October 21, reclaiming key moving averages despite late-session swings from VIX expiration.\n\nThe index rose 0.58% to close at 7,757.17, with SPY ending near 773.19 after hitting its daily high, boosted by positive SpaceX results and other tech names. Traders eyed stacked resistance at 775, 779.80, and 781.85, plotting put buys toward 760 or 755 if rallies falter, while noting QQQ's lag below its averages.\n\nTesla reported flat $28.05 billion revenue and positive cash flow after hours, as Meta beat with $64.6 billion and strong guidance, keeping tech sentiment supportive yet mixed. Views split on next moves, with light volume signaling potential volatility ahead.", "body_zh": "标普 500 涨 0.58% 收于 7757，市场关注阻力位。\n\n10 月 21 日标普小幅回升、夺回关键均线，尽管尾盘受 VIX 到期扰动。\n\n指数上涨 0.58% 收于 7757.17，SPY 收于约 773.19 并触及当日高点，受益于 SpaceX 等科技正面消息。交易员盯住 775、779.80、781.85 等层层阻力，若反弹失败则考虑买入看跌期权押注 760 或 755，并指出 QQQ 仍处均线下方。\n\n特斯拉盘后公布营收约 280.5 亿美元持平、现金流为正；Meta 报 646 亿美元并给出强劲指引，科技情绪喜忧参半。成交清淡暗示后市仍可能波动。", "url": "https://x.com/i/trending/2113041959728066952", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-22T01:46:33.000Z"}, {"id": "2113005005959799033", "domain": "商业", "title_en": "IBM Shares Surge on Strong Q3 Earnings and AI Boost", "title_zh": "IBM 第三季财报超预期、AI 助力，股价盘后大涨", "hook_en": "IBM's third-quarter numbers landed better than expected, sending shares up over 6% right after the bell. But the excitement cooled fast, with one observer noting 'And it’s gone' as gains faded.", "hook_zh": "IBM 第三季数字好于预期，收盘后股价一度涨逾 6%；但兴奋很快消退，有人感叹「涨幅没了」。", "summary_en": "The tech giant reported $17.10 billion in revenue, topping estimates of $16.82 billion, with adjusted earnings per share at $2.95 against $2.86 expected. Software revenue climbed 8% to $7.80 billion, infrastructure rose 4%, and free cash flow hit $3.0 billion, prompting IBM to raise its full-year software growth outlook to 7-8% and boost cash flow guidance by over $1 billion. CEO Arvind Krishna highlighted clients deploying 'Super Intelligence' amid hybrid cloud and data momentum, though after-hours trading saw shares spike near 10% before pulling back sharply.", "summary_zh": "该公司营收 171.0 亿美元，高于预期的 168.2 亿；调整后每股收益 2.95 美元，好于预期 2.86 美元。软件营收增 8% 至 78.0 亿，基础设施增 4%，自由现金流 30 亿美元，促使 IBM 将全年软件增长展望上调至 7%–8%，并上调现金流指引逾 10 亿美元。CEO 阿尔温德·克里希纳强调客户在混合云与数据动能下部署「超级智能」；盘后股价一度近涨 10% 后大幅回落。", "body_en": "IBM Shares Surge on Strong Q3 Earnings and AI Boost.\n\nIBM's third-quarter numbers landed better than expected, sending shares up over 6% right after the bell. But the excitement cooled fast, with one observer noting 'And it’s gone' as gains faded.\n\nThe tech giant reported $17.10 billion in revenue, topping estimates of $16.82 billion, with adjusted earnings per share at $2.95 against $2.86 expected.\n\nSoftware revenue climbed 8% to $7.80 billion, infrastructure rose 4%, and free cash flow hit $3.0 billion, prompting IBM to raise its full-year software growth outlook to 7-8% and boost cash flow guidance by over $1 billion. CEO Arvind Krishna highlighted clients deploying 'Super Intelligence' amid hybrid cloud and data momentum, though after-hours trading saw shares spike near 10% before pulling back sharply.", "body_zh": "IBM 第三季财报超预期、AI 助力，股价盘后大涨。\n\nIBM 第三季数字好于预期，收盘后股价一度涨逾 6%；但兴奋很快消退，有人感叹「涨幅没了」。\n\n该公司营收 171.0 亿美元，高于预期的 168.2 亿；调整后每股收益 2.95 美元，好于预期 2.86 美元。\n\n软件营收增 8% 至 78.0 亿，基础设施增 4%，自由现金流 30 亿美元，促使 IBM 将全年软件增长展望上调至 7%–8%，并上调现金流指引逾 10 亿美元。CEO 阿尔温德·克里希纳强调客户在混合云与数据动能下部署「超级智能」；盘后股价一度近涨 10% 后大幅回落。", "url": "https://x.com/i/trending/2113005005959799033", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T05:38:57.000Z"}, {"id": "2113211294543392944", "domain": "商业", "title_en": "Hermès Q3 Revenue Rises 4.3% but Misses Expectations, Shares Drop 7.5%", "title_zh": "爱马仕第三季营收增 4.3% 不及预期，股价跌 7.5%", "hook_en": "Hermès posted solid growth in its iconic leather goods, even as broader luxury headwinds took a toll on other lines.", "hook_zh": "爱马仕标志性皮具仍稳健增长，但更广泛的奢侈品逆风拖累其他品类。", "summary_en": "The French luxury brand reported third-quarter revenue of €4.1 billion, up 4.3% at constant exchange rates, driven by a standout 10.8% increase in leather goods and saddlery to €1.91 billion. Ready-to-wear and accessories fell 2%, marking the first decline in years, while regions like the Americas, Europe excluding France, and Japan grew 8.8% to 9.6%, offset by flat Asia ex-Japan and a 4.5% drop in the Middle East. For the first nine months, revenue hit €12.26 billion, up 5.5% at constant rates, with executives calling it robust growth amid challenges; shares fell to €1,293 as investors noted the weakest quarterly pace in 17 years outside early pandemic times.", "summary_zh": "这家法国奢侈品牌第三季营收 41 亿欧元，按不变汇率计增 4.3%，皮具与马具大增 10.8% 至 19.1 亿欧元。成衣与配饰下降 2%，为多年来首次；美洲、除法国外欧洲与日本增长约 8.8%–9.6%，亚洲（除日本）持平，中东跌 4.5%。前九个月营收 122.6 亿欧元，按不变汇率增 5.5%，管理层称增长仍稳健；股价跌至 1293 欧元，投资者指出这是疫情初期以外 17 年来最弱单季增速。", "body_en": "Hermès Q3 Revenue Rises 4.3% but Misses Expectations, Shares Drop 7.5%.\n\nHermès posted solid growth in its iconic leather goods, even as broader luxury headwinds took a toll on other lines.\n\nThe French luxury brand reported third-quarter revenue of €4.1 billion, up 4.3% at constant exchange rates, driven by a standout 10.8% increase in leather goods and saddlery to €1.91 billion.\n\nReady-to-wear and accessories fell 2%, marking the first decline in years, while regions like the Americas, Europe excluding France, and Japan grew 8.8% to 9.6%, offset by flat Asia ex-Japan and a 4.5% drop in the Middle East. For the first nine months, revenue hit €12.26 billion, up 5.5% at constant rates, with executives calling it robust growth amid challenges; shares fell to €1,293 as investors noted the weakest quarterly pace in 17 years outside early pandemic times.", "body_zh": "爱马仕第三季营收增 4.3% 不及预期，股价跌 7.5%。\n\n爱马仕标志性皮具仍稳健增长，但更广泛的奢侈品逆风拖累其他品类。\n\n这家法国奢侈品牌第三季营收 41 亿欧元，按不变汇率计增 4.3%，皮具与马具大增 10.8% 至 19.1 亿欧元。\n\n成衣与配饰下降 2%，为多年来首次；美洲、除法国外欧洲与日本增长约 8.8%–9.6%，亚洲（除日本）持平，中东跌 4.5%。前九个月营收 122.6 亿欧元，按不变汇率增 5.5%，管理层称增长仍稳健；股价跌至 1293 欧元，投资者指出这是疫情初期以外 17 年来最弱单季增速。", "url": "https://x.com/i/trending/2113211294543392944", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T12:23:36.000Z"}, {"id": "2112895365657567737", "domain": "中国", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2113047921575018577", "domain": "中国", "title_en": "Chinese Fentanyl Firms Now Sell Unregulated Weight Loss Peptides to Americans", "title_zh": "部分曾涉芬太尼前体的中国供应商转售未批准减肥肽", "hook_en": "A company once indicted for supplying fentanyl precursors to cartels is openly listing weight-loss drugs like semaglutide on its website. Now those same manufacturers are shipping unregulated peptides straight to U.S. buyers.", "hook_zh": "一些曾因芬太尼危机被起诉的公司，正公开向美国人在线销售实验性减肥药物，引发安全与监管担忧。", "summary_en": "Chinese firms previously linked to fentanyl production, including Anhui Renchen Technology indicted in 2023, have shifted to selling peptides such as semaglutide and melanotan II for weight loss and tanning. At least 50 of 200 tracked companies now offer these, with shipments often mislabeled as snack food to evade detection; U.S. Customs seized over 130,000 vials last year. The FDA links two deaths to unapproved retatrutide from black-market sources, including a 41-year-old woman and a 49-year-old patient who suffered cardiac arrest, underscoring risks in this unregulated market.", "summary_zh": "在约 200 家被追踪销售芬太尼前体的中国企业中，约 50 家已转向直接向美国买家推销司美格鲁肽、melanotan II 等未批准肽类，货运常伪装成零食。海关去年查获逾 13 万瓶，FDA 将两起死亡与黑市 retatrutide（礼来在研、尚未获批）联系起来。礼来警告黑市版本可能含杂质或剂量错误，包括实验室检测出痕量芬太尼的样本；安徽仁辰科技等曾被起诉的供应商仍在运作。", "body_en": "Chinese Fentanyl Suppliers Now Sell Unapproved Weight-Loss Peptides to Americans.\n\nCompanies once indicted for fueling the fentanyl crisis are openly offering experimental weight-loss drugs online, raising fresh alarms about hidden risks in every vial.\n\nAround 50 of the 200 Chinese firms tracked for selling fentanyl precursors have shifted to marketing unapproved peptides like semaglutide and melanotan II directly to U.S. buyers, with shipments often disguised as snack food.\n\nCustoms seized over 130,000 vials last year, while the FDA links two deaths to bootleg retatrutide, an Eli Lilly experimental drug not yet approved. Eli Lilly warns these black-market versions carry contaminants or wrong doses, including one lab-tested vial with fentanyl traces, as former suppliers like Anhui Renchen Technology continue operations despite past indictments.", "body_zh": "部分曾涉芬太尼前体的中国供应商转售未批准减肥肽。\n\n一些曾因芬太尼危机被起诉的公司，正公开向美国人在线销售实验性减肥药物，引发安全与监管担忧。\n\n在约 200 家被追踪销售芬太尼前体的中国企业中，约 50 家已转向直接向美国买家推销司美格鲁肽、melanotan II 等未批准肽类，货运常伪装成零食。\n\n海关去年查获逾 13 万瓶，FDA 将两起死亡与黑市 retatrutide（礼来在研、尚未获批）联系起来。礼来警告黑市版本可能含杂质或剂量错误，包括实验室检测出痕量芬太尼的样本；安徽仁辰科技等曾被起诉的供应商仍在运作。", "url": "https://x.com/i/trending/2113047921575018577", "category": "News", "topics": ["News", "Crime"], "updated_at": "2026-10-22T02:30:22.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2113277138665382340", "domain": "中国", "title_en": "Graphic Foot Binding Images Prompt Historical Reflection", "title_zh": "缠足旧照再度流传，引发历史反思", "hook_en": "Elderly women's feet, toes broken and folded under soles into tiny lotus shapes, appear in resurfaced photos that reveal the painful reality of an ancient custom.", "hook_zh": "老年妇女脚趾折断并折向脚底、形成「三寸金莲」的旧照再次流传，呈现古代习俗的残酷现实。", "summary_en": "Foot binding started around the 10th century in China, where girls as young as five or six had their toes broken and bound with cloth to create small, arched feet measuring 7.5 to 10 centimeters—seen as a symbol of beauty and status. The practice caused lifelong pain, infections, and mobility issues, peaking in the Ming and Qing dynasties before an official 1912 ban, with remnants lasting into the 1950s. Reactions highlight its role in limiting women's independence, while historians note it was often upheld by families for marriage prospects and social values, drawing comparisons to other rigid beauty standards like corsets.", "summary_zh": "缠足约始于中国 10 世纪，五六岁女孩脚趾被折断并用布裹紧，形成约 7.5–10 厘米的小脚，被视为美与地位象征。该习俗导致终身疼痛、感染与行动障碍，明清达峰，1912 年官方禁止，残留持续到 1950 年代。舆论强调其限制女性独立；史家指出家庭常为婚配与社会价值而坚持，并与紧身胸衣等其他严苛审美标准相比较。", "body_en": "Graphic Foot Binding Images Prompt Historical Reflection.\n\nElderly women's feet, toes broken and folded under soles into tiny lotus shapes, appear in resurfaced photos that reveal the painful reality of an ancient custom.\n\nFoot binding started around the 10th century in China, where girls as young as five or six had their toes broken and bound with cloth to create small, arched feet measuring 7.5 to 10 centimeters—seen as a symbol of beauty and status.\n\nThe practice caused lifelong pain, infections, and mobility issues, peaking in the Ming and Qing dynasties before an official 1912 ban, with remnants lasting into the 1950s. Reactions highlight its role in limiting women's independence, while historians note it was often upheld by families for marriage prospects and social values, drawing comparisons to other rigid beauty standards like corsets.", "body_zh": "缠足旧照再度流传，引发历史反思。\n\n老年妇女脚趾折断并折向脚底、形成「三寸金莲」的旧照再次流传，呈现古代习俗的残酷现实。\n\n缠足约始于中国 10 世纪，五六岁女孩脚趾被折断并用布裹紧，形成约 7.5–10 厘米的小脚，被视为美与地位象征。\n\n该习俗导致终身疼痛、感染与行动障碍，明清达峰，1912 年官方禁止，残留持续到 1950 年代。舆论强调其限制女性独立；史家指出家庭常为婚配与社会价值而坚持，并与紧身胸衣等其他严苛审美标准相比较。", "url": "https://x.com/i/trending/2113277138665382340", "category": "News", "topics": ["Beauty"], "updated_at": "2026-10-22T14:38:32.000Z"}, {"id": "2113108167571976335", "domain": "中国", "title_en": "DeepSeek Raises $15 Billion to Challenge OpenAI and Anthropic", "title_zh": "DeepSeek 融资 150 亿美元，挑战 OpenAI 与 Anthropic", "hook_en": "DeepSeek just pulled in $15 billion from giants like Tencent and CATL, fueling massive data centers and open-source AI models. It's a bold move amid U.S. security scrutiny and standout speed records.", "hook_zh": "DeepSeek 获腾讯、宁德时代等约 150 亿美元注资，扩建数据中心与开源模型；在美国安全审查与刷新速度纪录中仍高调推进。", "summary_en": "The Hangzhou-based AI firm secured about 100 billion yuan in one of China's largest funding rounds ever, valuing it at $74 billion pre-money, after investor demand doubled their initial $7 billion target. Days earlier, U.S. agencies were told to remove DeepSeek tech over security concerns, yet the company's V4.1 Flash 1017 model hit over 1,521 tokens per second—fast enough to code a playable Tetris game in 11 seconds. Developers praised the speed jump, with integrations on platforms like Vercel for cheap, rapid coding tasks, as DeepSeek eyes an IPO while prioritizing performance and low costs.", "summary_zh": "这家杭州 AI 公司完成约 1000 亿元人民币融资，为国内最大轮次之一，投前估值约 740 亿美元；投资人需求使目标从最初约 70 亿美元翻倍。数日前美国机构被要求移除 DeepSeek 技术，而其 V4.1 Flash 1017 模型吞吐超每秒 1521 token，11 秒可写出可玩的俄罗斯方块。开发者赞赏速度跃升，并在 Vercel 等平台用于低成本快速编程；DeepSeek 在优先性能与低成本的同时放眼 IPO。", "body_en": "DeepSeek Raises $15 Billion to Challenge OpenAI and Anthropic.\n\nDeepSeek just pulled in $15 billion from giants like Tencent and CATL, fueling massive data centers and open-source AI models. It's a bold move amid U.S. security scrutiny and standout speed records.\n\nThe Hangzhou-based AI firm secured about 100 billion yuan in one of China's largest funding rounds ever, valuing it at $74 billion pre-money, after investor demand doubled their initial $7 billion target. Days earlier, U.S.\n\nagencies were told to remove DeepSeek tech over security concerns, yet the company's V4.1 Flash 1017 model hit over 1,521 tokens per second—fast enough to code a playable Tetris game in 11 seconds. Developers praised the speed jump, with integrations on platforms like Vercel for cheap, rapid coding tasks, as DeepSeek eyes an IPO while prioritizing performance and low costs.", "body_zh": "DeepSeek 融资 150 亿美元，挑战 OpenAI 与 Anthropic。\n\nDeepSeek 获腾讯、宁德时代等约 150 亿美元注资，扩建数据中心与开源模型；在美国安全审查与刷新速度纪录中仍高调推进。\n\n这家杭州 AI 公司完成约 1000 亿元人民币融资，为国内最大轮次之一，投前估值约 740 亿美元；投资人需求使目标从最初约 70 亿美元翻倍。\n\n数日前美国机构被要求移除 DeepSeek 技术，而其 V4.1 Flash 1017 模型吞吐超每秒 1521 token，11 秒可写出可玩的俄罗斯方块。开发者赞赏速度跃升，并在 Vercel 等平台用于低成本快速编程；DeepSeek 在优先性能与低成本的同时放眼 IPO。", "url": "https://x.com/i/trending/2113108167571976335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-22T20:57:40.000Z"}, {"id": "2113169909131952574", "domain": "中国", "title_en": "Family's Trip to China Secures Lung Cancer Pill Before U.S. Launch", "title_zh": "美国家庭赴华购肺癌靶向药，早于美国上市近两年", "hook_en": "Max Doppelt flew to Shanghai for 26 boxes of a targeted lung cancer pill when none was available at home for his mother Debbie. Nineteen months later, she's still active and working.", "hook_zh": "Max Doppelt 飞赴上海为母亲 Debbie 购得 26 盒靶向肺癌药；19 个月后她仍活跃工作。", "summary_en": "Debbie Doppelt's rare lung cancer had spread to her brain in January 2025, and with no U.S. options after FDA accelerated approval of sunvozertinib in July 2025, her son traveled to China to buy the drug. He brought back enough for her treatment, and she calls the time an 'amazing three years,' while knowing of at least 30 other Americans who did the same. AstraZeneca, which licensed the drug, made it available in the U.S. on October 22, 2026, after a gap caused by commercial delays. The story highlights growing Chinese leadership in drug development and calls for faster patient access.", "summary_zh": "Debbie Doppelt 罕见肺癌 2025 年 1 月扩散至脑部，美国无药可购；FDA 2025 年 7 月加速批准 sunvozertinib 后仍难获得，其子赴华购药带回。她称这段时间为「奇妙的三年」，并知至少还有约 30 名美国人做了同样选择。授权该药的阿斯利康于 2026 年 10 月 22 日使其在美上市，此前因商业延迟留有缺口。故事凸显中国在药物研发上的领先，并呼吁加快患者可及。", "body_en": "Family's Trip to China Secures Lung Cancer Pill Before U.S. Launch.\n\nMax Doppelt flew to Shanghai for 26 boxes of a targeted lung cancer pill when none was available at home for his mother Debbie. Nineteen months later, she's still active and working.\n\nDebbie Doppelt's rare lung cancer had spread to her brain in January 2025, and with no U.S. options after FDA accelerated approval of sunvozertinib in July 2025, her son traveled to China to buy the drug. He brought back enough for her treatment, and she calls the time an 'amazing three years,' while knowing of at least 30 other Americans who did the same.\n\nAstraZeneca, which licensed the drug, made it available in the U.S. on October 22, 2026, after a gap caused by commercial delays. The story highlights growing Chinese leadership in drug development and calls for faster patient access.", "body_zh": "美国家庭赴华购肺癌靶向药，早于美国上市近两年。\n\nMax Doppelt 飞赴上海为母亲 Debbie 购得 26 盒靶向肺癌药；19 个月后她仍活跃工作。\n\nDebbie Doppelt 罕见肺癌 2025 年 1 月扩散至脑部，美国无药可购；FDA 2025 年 7 月加速批准 sunvozertinib 后仍难获得，其子赴华购药带回。她称这段时间为「奇妙的三年」，并知至少还有约 30 名美国人做了同样选择。\n\n授权该药的阿斯利康于 2026 年 10 月 22 日使其在美上市，此前因商业延迟留有缺口。故事凸显中国在药物研发上的领先，并呼吁加快患者可及。", "url": "https://x.com/i/trending/2113169909131952574", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-22T20:46:15.000Z"}, {"id": "2113347488698565024", "domain": "中国", "title_en": "First Tungsten Price Hedge Shields U.S. Manufacturers on Kalshi", "title_zh": "美国制造商在 Kalshi 完成首笔钨价对冲", "hook_en": "An Ohio metals distributor just locked in protection against skyrocketing tungsten prices, using a novel hedge on the Kalshi prediction market.", "hook_zh": "俄亥俄州金属分销商借助 Kalshi 预测市场创新对冲，锁定飙升钨价风险。", "summary_en": "Tungsten prices have surged over 500% due to tight supply and China's export controls, hitting U.S. makers of jet engines, munitions, semiconductors, and EV parts. Through commodity risk manager Pillar and liquidity from Susquehanna Predictions, the distributor secured a hedge tied to the Shanghai Metals Market benchmark, settling December 17, 2026. Pillar CEO Harsha Ramesh called it a key edge for American manufacturers, while investors praised the innovation for boosting industrial resilience amid supply-chain strains and upcoming Pentagon restrictions on Chinese tungsten.", "summary_zh": "受供应收紧与中国出口管制影响，钨价已飙升逾 500%，冲击喷气发动机、弹药、半导体与电动车零部件等美国制造商。通过商品风险管理商 Pillar 与 Susquehanna Predictions 提供的流动性，该分销商以上海有色网基准完成对冲，结算日为 2026 年 12 月 17 日。Pillar CEO Harsha Ramesh 称这对美国制造业是关键优势；投资者赞赏此举有助在供应链承压与五角大楼即将限制中国钨的背景下提升工业韧性。", "body_en": "First Tungsten Price Hedge Shields U.S. Manufacturers on Kalshi.\n\nAn Ohio metals distributor just locked in protection against skyrocketing tungsten prices, using a novel hedge on the Kalshi prediction market.\n\nTungsten prices have surged over 500% due to tight supply and China's export controls, hitting U.S. makers of jet engines, munitions, semiconductors, and EV parts.\n\nThrough commodity risk manager Pillar and liquidity from Susquehanna Predictions, the distributor secured a hedge tied to the Shanghai Metals Market benchmark, settling December 17, 2026. Pillar CEO Harsha Ramesh called it a key edge for American manufacturers, while investors praised the innovation for boosting industrial resilience amid supply-chain strains and upcoming Pentagon restrictions on Chinese tungsten.", "body_zh": "美国制造商在 Kalshi 完成首笔钨价对冲。\n\n俄亥俄州金属分销商借助 Kalshi 预测市场创新对冲，锁定飙升钨价风险。\n\n受供应收紧与中国出口管制影响，钨价已飙升逾 500%，冲击喷气发动机、弹药、半导体与电动车零部件等美国制造商。\n\n通过商品风险管理商 Pillar 与 Susquehanna Predictions 提供的流动性，该分销商以上海有色网基准完成对冲，结算日为 2026 年 12 月 17 日。Pillar CEO Harsha Ramesh 称这对美国制造业是关键优势；投资者赞赏此举有助在供应链承压与五角大楼即将限制中国钨的背景下提升工业韧性。", "url": "https://x.com/i/trending/2113347488698565024", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T19:18:16.000Z"}, {"id": "2113277135578407105", "domain": "中国", "title_en": "U.S. Soybean Exports Surge on Strong Chinese Demand", "title_zh": "中国强劲采购推动美国大豆出口飙升", "hook_en": "Last week, U.S. soybean sales hit their highest mark in nearly three years, driven by massive purchases from China—the world's top importer.", "hook_zh": "上周美国大豆销售创近三年最高，主因全球最大进口国中国大举购买。", "summary_en": "The USDA reported net soybean sales of 104.4 million bushels for the week ending October 15, with China buying about 80 million bushels or 2.18 million metric tons—the largest since November 2023. A flash sale of 202,000 metric tons to China for the 2026/27 marketing year added to the momentum, pushing total 2026/27 commitments to 2.84 million metric tons. These strong figures exceeded trade expectations, lifted soybean futures, and signal tighter supplies despite a bigger U.S. harvest, as Brazil continues to dominate China's long-term imports.", "summary_zh": "美国农业部报告，截至 10 月 15 日当周大豆净销售约 1.044 亿蒲式耳，其中中国约 8000 万蒲式耳（218 万吨）——为 2023 年 11 月以来最大。另有一笔 2026/27 市场年度对华 20.2 万吨闪售，使该年度承诺总量达 284 万吨。数据好于交易预期，推高大豆期货，并在丰收背景下暗示供应趋紧；长期看巴西仍主导对华出口。", "body_en": "U.S. Soybean Exports Surge on Strong Chinese Demand.\n\nLast week, U.S. soybean sales hit their highest mark in nearly three years, driven by massive purchases from China—the world's top importer.\n\nThe USDA reported net soybean sales of 104.4 million bushels for the week ending October 15, with China buying about 80 million bushels or 2.18 million metric tons—the largest since November 2023. A flash sale of 202,000 metric tons to China for the 2026/27 marketing year added to the momentum, pushing total 2026/27 commitments to 2.84 million metric tons.\n\nThese strong figures exceeded trade expectations, lifted soybean futures, and signal tighter supplies despite a bigger U.S. harvest, as Brazil continues to dominate China's long-term imports.", "body_zh": "中国强劲采购推动美国大豆出口飙升。\n\n上周美国大豆销售创近三年最高，主因全球最大进口国中国大举购买。\n\n美国农业部报告，截至 10 月 15 日当周大豆净销售约 1.044 亿蒲式耳，其中中国约 8000 万蒲式耳（218 万吨）——为 2023 年 11 月以来最大。\n\n另有一笔 2026/27 市场年度对华 20.2 万吨闪售，使该年度承诺总量达 284 万吨。数据好于交易预期，推高大豆期货，并在丰收背景下暗示供应趋紧；长期看巴西仍主导对华出口。", "url": "https://x.com/i/trending/2113277135578407105", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T17:15:55.000Z"}, {"id": "2113284617771810829", "domain": "中国", "title_en": "7.0 Earthquake Hits Remote Northern Tibet, Killing at Least 16", "title_zh": "西藏北部偏远地区发生 7.0 级地震，至少 16 人死亡", "hook_en": "In a remote, high-altitude corner of northern Tibet, the ground shook violently Thursday night, toppling homes and leaving families in the cold mountain air.", "hook_zh": "周四夜间，西藏北部高海拔偏远地区剧烈震动，房屋倒塌，民众暴露在寒冷山风中。", "summary_en": "The magnitude 7.0 quake struck around 10:33 p.m. local time near the Xizang-Qinghai border, about 183-191 kilometers east-northeast of Nagqu, at a shallow depth of 10-18 kilometers. It killed at least 16 people—some reports say 18—and injured 32 others, with over 300 houses collapsing in the sparsely populated area above 4,800 meters elevation. Chinese authorities launched a Level II emergency response, sending rescue teams, tents, quilts, and stoves to Baqing County, where efforts continue amid aftershock risks and potential landslides.", "summary_zh": "震级 7.0 的地震约于当地时间晚上 10:33 发生在西藏—青海交界附近，那曲东北偏东约 183–191 公里，震源深度约 10–18 公里。至少 16 人死亡（有报道称 18 人），32 人受伤，海拔逾 4800 米的稀疏居住区有超 300 间房屋倒塌。中国当局启动二级应急响应，向比如县派遣救援队并运送帐篷、被褥与炉具，余震与滑坡风险仍在。", "body_en": "7.0 Earthquake Hits Remote Northern Tibet, Killing at Least 16.\n\nIn a remote, high-altitude corner of northern Tibet, the ground shook violently Thursday night, toppling homes and leaving families in the cold mountain air.\n\nThe magnitude 7.0 quake struck around 10:33 p.m. local time near the Xizang-Qinghai border, about 183-191 kilometers east-northeast of Nagqu, at a shallow depth of 10-18 kilometers.\n\nIt killed at least 16 people—some reports say 18—and injured 32 others, with over 300 houses collapsing in the sparsely populated area above 4,800 meters elevation. Chinese authorities launched a Level II emergency response, sending rescue teams, tents, quilts, and stoves to Baqing County, where efforts continue amid aftershock risks and potential landslides.", "body_zh": "西藏北部偏远地区发生 7.0 级地震，至少 16 人死亡。\n\n周四夜间，西藏北部高海拔偏远地区剧烈震动，房屋倒塌，民众暴露在寒冷山风中。\n\n震级 7.0 的地震约于当地时间晚上 10:33 发生在西藏—青海交界附近，那曲东北偏东约 183–191 公里，震源深度约 10–18 公里。\n\n至少 16 人死亡（有报道称 18 人），32 人受伤，海拔逾 4800 米的稀疏居住区有超 300 间房屋倒塌。中国当局启动二级应急响应，向比如县派遣救援队并运送帐篷、被褥与炉具，余震与滑坡风险仍在。", "url": "https://x.com/i/trending/2113284617771810829", "category": "News", "topics": ["Natural Disasters"], "updated_at": "2026-10-22T23:43:43.000Z"}, {"id": "2112981235027075558", "domain": "中国", "title_en": "Super Typhoon Champi Nears Taiwan After Tying 2026's Strongest Winds", "title_zh": "超强台风「灿琵」逼近台湾，风速追平 2026 年最强", "hook_en": "With winds once roaring at 185 mph, Super Typhoon Champi looms just off Taiwan's coast, prompting widespread closures so residents can hunker down safely.", "hook_zh": "一度达每小时 185 英里的超强台风「灿琵」逼近台湾沿海，当局大范围停班停课以便民众避险。", "summary_en": "Champi tied Super Typhoon Sinlaku as 2026's most powerful storm by wind speed, peaking at 185 mph before slightly weakening to around 170 mph. Taiwan's authorities closed schools and offices across the main island on October 23, canceled over 125 flights, and issued warnings for heavy rain, flash floods, and landslides. The massive system, with clouds spanning from the Philippines to Japan, will brush Taiwan's northeast coast late Friday into Saturday before hitting Japan's Yonaguni island as a Category 2 typhoon.", "summary_zh": "「灿琵」以风速追平超强台风「辛乐克」，成为 2026 年最强风暴之一，峰值约 185 英里/小时后略降至约 170。台湾当局 10 月 23 日在本岛停班停课，取消逾 125 个航班，并发布暴雨、山洪与滑坡警告。云系横跨菲律宾至日本的庞大系统将于周五晚至周六擦过台湾东北沿海，再以二级台风强度影响日本与那国岛。", "body_en": "Super Typhoon Champi Nears Taiwan After Tying 2026's Strongest Winds.\n\nWith winds once roaring at 185 mph, Super Typhoon Champi looms just off Taiwan's coast, prompting widespread closures so residents can hunker down safely.\n\nChampi tied Super Typhoon Sinlaku as 2026's most powerful storm by wind speed, peaking at 185 mph before slightly weakening to around 170 mph.\n\nTaiwan's authorities closed schools and offices across the main island on October 23, canceled over 125 flights, and issued warnings for heavy rain, flash floods, and landslides. The massive system, with clouds spanning from the Philippines to Japan, will brush Taiwan's northeast coast late Friday into Saturday before hitting Japan's Yonaguni island as a Category 2 typhoon.", "body_zh": "超强台风「灿琵」逼近台湾，风速追平 2026 年最强。\n\n一度达每小时 185 英里的超强台风「灿琵」逼近台湾沿海，当局大范围停班停课以便民众避险。\n\n「灿琵」以风速追平超强台风「辛乐克」，成为 2026 年最强风暴之一，峰值约 185 英里/小时后略降至约 170。\n\n台湾当局 10 月 23 日在本岛停班停课，取消逾 125 个航班，并发布暴雨、山洪与滑坡警告。云系横跨菲律宾至日本的庞大系统将于周五晚至周六擦过台湾东北沿海，再以二级台风强度影响日本与那国岛。", "url": "https://x.com/i/trending/2112981235027075558", "category": "News", "topics": ["Natural Disasters"], "updated_at": "2026-10-22T23:43:33.000Z"}, {"id": "2112895365049471028", "domain": "中国", "title_en": "China Commemorates 90th Anniversary of Red Army's Long March", "title_zh": "中国纪念红军长征胜利 90 周年", "hook_en": "In Beijing, leaders gathered under posters of weary marchers crossing mountains and rivers, honoring a grueling journey that saved a revolution.", "hook_zh": "北京举行纪念活动，海报再现翻山渡河的疲惫行军者，缅怀挽救革命的艰苦征途。", "summary_en": "President Xi Jinping spoke at a major event on Thursday, marking 90 years since the Red Army's 1934-1936 Long March, a strategic retreat over thousands of kilometers that preserved Communist forces amid encirclement. Xi urged new achievements on this 'new Long March' toward national rejuvenation, with participants observing silence for fallen heroes. The commemoration included historical images, new stamps from China Post, and echoes of the march's spirit of resilience and Party leadership in today's challenges.", "summary_zh": "习近平主席周四在重大活动上讲话，纪念红军 1934–1936 年长征胜利 90 周年——那场跨越千里的战略转移在重重包围中保存了革命力量。他号召在通往民族复兴的「新长征」上再立新功，与会者向英烈默哀。纪念还包括历史影像、中国邮政新邮票，并重申长征所象征的坚韧与党的领导，用以应对今日挑战。", "body_en": "China Commemorates 90th Anniversary of Red Army's Long March.\n\nIn Beijing, leaders gathered under posters of weary marchers crossing mountains and rivers, honoring a grueling journey that saved a revolution.\n\nPresident Xi Jinping spoke at a major event on Thursday, marking 90 years since the Red Army's 1934-1936 Long March, a strategic retreat over thousands of kilometers that preserved Communist forces amid encirclement.\n\nXi urged new achievements on this 'new Long March' toward national rejuvenation, with participants observing silence for fallen heroes. The commemoration included historical images, new stamps from China Post, and echoes of the march's spirit of resilience and Party leadership in today's challenges.", "body_zh": "中国纪念红军长征胜利 90 周年。\n\n北京举行纪念活动，海报再现翻山渡河的疲惫行军者，缅怀挽救革命的艰苦征途。\n\n习近平主席周四在重大活动上讲话，纪念红军 1934–1936 年长征胜利 90 周年——那场跨越千里的战略转移在重重包围中保存了革命力量。\n\n他号召在通往民族复兴的「新长征」上再立新功，与会者向英烈默哀。纪念还包括历史影像、中国邮政新邮票，并重申长征所象征的坚韧与党的领导，用以应对今日挑战。", "url": "https://x.com/i/trending/2112895365049471028", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T21:35:21.000Z"}, {"id": "2113270291602268395", "domain": "中国", "title_en": "India Builds Own Tunnel Boring Machines Amid China Export Curbs", "title_zh": "中国限制出口盾构机，印度加速国产化", "hook_en": "China's new export controls on massive tunnel boring machines hit just as India ramps up mega infrastructure projects. Railway Minister Ashwini Vaishnaw shared how the country is now developing its full TBM ecosystem at home.", "hook_zh": "中国对大型盾构机实施新出口管制之际，印度正推进巨型基建；铁道部长瓦伊什纳夫介绍本国正打造完整 TBM 生态。", "summary_en": "China imposed licensing requirements on TBMs and related equipment starting November 18, citing national security for dual-use items. India, needing around 340 of these 3,000-tonne machines for metros, bullet trains, and hydropower through 2035, is pushing domestic production under Atmanirbhar Bharat. Public firm BEML seeks design partners for TBMs up to 16.5 metres wide, building on existing 8- and 15-metre capabilities in Tamil Nadu, while Germany's Herrenknecht provides an alternative via its Chennai plant.", "summary_zh": "中国自 11 月 18 日起对盾构机及相关设备实施许可管理，称涉及国家安全与两用物项。印度到 2035 年地铁、高铁与水电等项目约需 340 台重约 3000 吨的盾构机，正借「自力更生」推动国产。国企 BEML 寻求设计伙伴研制直径达 16.5 米机型，泰米尔纳德邦已有 8 米与 15 米能力；德国海瑞克通过金奈工厂提供替代方案。", "body_en": "India Builds Own Tunnel Boring Machines Amid China Export Curbs.\n\nChina's new export controls on massive tunnel boring machines hit just as India ramps up mega infrastructure projects. Railway Minister Ashwini Vaishnaw shared how the country is now developing its full TBM ecosystem at home.\n\nChina imposed licensing requirements on TBMs and related equipment starting November 18, citing national security for dual-use items.\n\nIndia, needing around 340 of these 3,000-tonne machines for metros, bullet trains, and hydropower through 2035, is pushing domestic production under Atmanirbhar Bharat. Public firm BEML seeks design partners for TBMs up to 16.5 metres wide, building on existing 8- and 15-metre capabilities in Tamil Nadu, while Germany's Herrenknecht provides an alternative via its Chennai plant.", "body_zh": "中国限制出口盾构机，印度加速国产化。\n\n中国对大型盾构机实施新出口管制之际，印度正推进巨型基建；铁道部长瓦伊什纳夫介绍本国正打造完整 TBM 生态。\n\n中国自 11 月 18 日起对盾构机及相关设备实施许可管理，称涉及国家安全与两用物项。\n\n印度到 2035 年地铁、高铁与水电等项目约需 340 台重约 3000 吨的盾构机，正借「自力更生」推动国产。国企 BEML 寻求设计伙伴研制直径达 16.5 米机型，泰米尔纳德邦已有 8 米与 15 米能力；德国海瑞克通过金奈工厂提供替代方案。", "url": "https://x.com/i/trending/2113270291602268395", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-22T19:06:01.000Z"}, {"id": "2112807301782638724", "domain": "中国", "title_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027", "title_zh": "金惠奫出任 2026–2027 台湾观光宣传大使", "hook_en": "Kim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.", "hook_zh": "金惠奫身着白裤装亮相首尔发布会，手持聘书笑容满面，粉丝围拍。", "summary_en": "South Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season. Organizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "summary_zh": "韩国女演员金惠奫在首尔记者会获聘台湾观光宣传大使，新片以「Everyone, Anytime, Taiwan Delights」为口号：与兄逛台南小吃、与家人游日月潭、高雄独行、海边友人行，展示四季与多元玩法。主办方看中其明朗形象与《浪漫速成班》人气及 2024 台湾粉丝见面会号召力。她希望影片启发观众规划适合自己的行程。", "body_en": "Kim Hyeyoon Named Taiwan Tourism Ambassador for 2026-2027.\n\nKim Hyeyoon stepped out in a crisp white pantsuit, flashing smiles and holding her official certificate as fans snapped photos at the Seoul launch.\n\nSouth Korean actress Kim Hyeyoon was appointed promotional ambassador for Taiwan Tourism at a Seoul press conference, where new campaign videos debuted under the slogan 'Everyone, Anytime, Taiwan Delights.' The clips show her enjoying Tainan food streets with her brother, Sun Moon Lake with family, solo time in Kaohsiung, and beach fun with friends, highlighting Taiwan's charms for any traveler or season.\n\nOrganizers picked her for her bright image and wide appeal, boosted by her popularity from *Lovely Runner* and a 2024 Taiwan fan meeting. She hopes the videos inspire people to plan trips that fit their style.", "body_zh": "金惠奫出任 2026–2027 台湾观光宣传大使。\n\n金惠奫身着白裤装亮相首尔发布会，手持聘书笑容满面，粉丝围拍。\n\n韩国女演员金惠奫在首尔记者会获聘台湾观光宣传大使，新片以「Everyone, Anytime, Taiwan Delights」为口号：与兄逛台南小吃、与家人游日月潭、高雄独行、海边友人行，展示四季与多元玩法。\n\n主办方看中其明朗形象与《浪漫速成班》人气及 2024 台湾粉丝见面会号召力。她希望影片启发观众规划适合自己的行程。", "url": "https://x.com/i/trending/2112807301782638724", "category": "Entertainment", "topics": ["Travel"], "updated_at": "2026-10-21T12:40:57.000Z"}, {"id": "2112948936755286232", "domain": "国际", "title_en": "JD Vance Remarks Revive Budapest Memorandum Debate", "title_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点", "hook_en": "JD Vance pointed out the US has no formal alliance with Ukraine, sparking reminders of a 1994 deal where Ukraine gave up nuclear weapons for security promises.", "hook_zh": "万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。", "summary_en": "In a recent interview, Vice President JD Vance noted Ukraine is not in NATO and described it as a partner with differing interests, like strikes on Russian energy sites. This led people to highlight the 1994 Budapest Memorandum, where Ukraine surrendered its inherited Soviet nuclear arsenal—over 4,400 warheads—in exchange for assurances from the US, Russia, and UK to respect its borders and sovereignty. Signed on December 5, 1994, the memorandum provided political commitments but no binding military obligations, fueling discussions on Russia's violations and US support limits amid the ongoing conflict.", "summary_zh": "美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "body_en": "JD Vance Questions US Obligations to Ukraine Amid Budapest Memorandum Debate.\n\nJD Vance called Ukraine a partner, not an ally, with no formal obligation to defend it. That statement quickly brought back memories of a 1994 promise Ukraine trusted when it gave up its nuclear arsenal.\n\nIn an October 20, 2026 interview, US Vice President JD Vance said America has no treaty-bound duty to stand by Ukraine.\n\nMany pointed to the 1994 Budapest Memorandum, where Ukraine surrendered about 4,400 nuclear warheads in exchange for security assurances from the US, Russia, and the UK—assurances that respected its sovereignty and borders but lacked binding military commitments like NATO's Article 5. While the US has sent billions in aid since Russia's 2014 Crimea annexation and 2022 invasion, the debate highlights the memorandum's moral weight versus its non-binding nature, raising questions for nations weighing nuclear disarmament.", "body_zh": "万斯质疑美国对乌克兰义务，布达佩斯备忘录再成焦点。\n\n万斯称乌克兰是伙伴而非盟友，美国并无正式协防义务。此言迅速勾起1994年乌克兰弃核时所信承诺的记忆。\n\n美国副总统万斯在2026年10月20日采访中表示，美国对乌克兰并无条约约束的协防责任。\n\n许多人提及1994年《布达佩斯备忘录》：乌克兰交出约4400枚核弹头，换取美、俄、英对其主权与边界的安全保证，但该保证并不具备北约第五条那样的强制军事承诺。尽管自2014年克里米亚事件与2022年全面入侵以来美国已提供巨额援助，这场辩论仍凸显备忘录的道德分量与非约束性之间的张力，也令正考虑弃核的国家心生疑虑。", "url": "https://x.com/i/trending/2112948936755286232", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T13:05:03.000Z"}, {"id": "2112529719405031486", "domain": "国际", "title_en": "Calls Grow for Jonathan Powell to Resign Over Wife's Social Media Posts", "title_zh": "英国家安全顾问妻子社媒言论引辞职呼声", "hook_en": "Jonathan Powell holds Britain's deepest secrets as national security adviser. Now, his wife Sarah Helm's posts questioning Israeli victims and defending Hamas have critics demanding he step down.", "hook_zh": "乔纳森·鲍威尔执掌英国最深机密；其妻萨拉·赫尔姆质疑以方受害者、为哈马斯辩护的帖文，令批评者要求他下台。", "summary_en": "Sarah Helm, a journalist, shared and reposted content that defends Hamas, questions UN findings on October 7 rapes, compares Israel to Nazis, and appears to back the proscribed group Palestine Action. Conservative MP Alicia Kearns called Powell's position untenable, citing these posts alongside past concerns like Chagos Islands talks and China meetings; Talk TV's Julia Hartley-Brewer told Helm directly that her husband must quit. The Metropolitan Police reviewed one post but found no crime, and Downing Street says Helm's views are personal, though critics question vetting for such a sensitive role. Both Conservative and some Labour figures urge Powell to resign, but the government stands by him.", "summary_zh": "记者萨拉·赫尔姆转发并分享为哈马斯辩护、质疑联合国关于 10 月 7 日性侵调查、将以色列比作纳粹、以及似支持被禁组织 Palestine Action 的内容。保守党议员艾丽西亚·基恩斯称鲍威尔职位难再维持，并列举查戈斯谈判、对华会晤等过往争议；Talk TV 的朱莉娅·哈特利-布鲁尔直接对赫尔姆说其丈夫必须辞职。伦敦警察厅审查一帖后未认定犯罪，唐宁街称其观点属个人，但批评者质疑敏感职位审查。部分工党人士亦吁辞职，政府仍表支持。", "body_en": "Calls Grow for Jonathan Powell to Resign Over Wife's Social Media Posts.\n\nJonathan Powell holds Britain's deepest secrets as national security adviser. Now, his wife Sarah Helm's posts questioning Israeli victims and defending Hamas have critics demanding he step down.\n\nSarah Helm, a journalist, shared and reposted content that defends Hamas, questions UN findings on October 7 rapes, compares Israel to Nazis, and appears to back the proscribed group Palestine Action. Conservative MP Alicia Kearns called Powell's position untenable, citing these posts alongside past concerns like Chagos Islands talks and China meetings; Talk TV's Julia Hartley-Brewer told Helm directly that her husband must quit.\n\nThe Metropolitan Police reviewed one post but found no crime, and Downing Street says Helm's views are personal, though critics question vetting for such a sensitive role. Both Conservative and some Labour figures urge Powell to resign, but the government stands by him.", "body_zh": "英国家安全顾问妻子社媒言论引辞职呼声。\n\n乔纳森·鲍威尔执掌英国最深机密；其妻萨拉·赫尔姆质疑以方受害者、为哈马斯辩护的帖文，令批评者要求他下台。\n\n记者萨拉·赫尔姆转发并分享为哈马斯辩护、质疑联合国关于 10 月 7 日性侵调查、将以色列比作纳粹、以及似支持被禁组织 Palestine Action 的内容。保守党议员艾丽西亚·基恩斯称鲍威尔职位难再维持，并列举查戈斯谈判、对华会晤等过往争议；Talk TV 的朱莉娅·哈特利-布鲁尔直接对赫尔姆说其丈夫必须辞职。\n\n伦敦警察厅审查一帖后未认定犯罪，唐宁街称其观点属个人，但批评者质疑敏感职位审查。部分工党人士亦吁辞职，政府仍表支持。", "url": "https://x.com/i/trending/2112529719405031486", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T21:04:30.000Z"}, {"id": "2113181910314664307", "domain": "国际", "title_en": "Keir Starmer Faces Grooming Gangs Inquiry Testimony Amid Global Role Speculation", "title_zh": "斯塔默将就性侵团伙调查作证，国际职位传闻升温", "hook_en": "Keir Starmer stepped down as UK prime minister in June 2026, and now he's listed to testify in a major inquiry into grooming gangs failures while rumors swirl about top international jobs.", "hook_zh": "基尔·斯塔默 2026 年 6 月卸任英国首相，现被列入性侵团伙失职调查证人名单，同时有顶级国际职位传闻。", "summary_en": "The independent inquiry, led by Baroness Anne Longfield, probes why police, councils, and prosecutors repeatedly let down victims of group-based child sexual exploitation, with hearings starting later this year on victim stories before accountability phases. Starmer, who resigned amid political pressures, will explain the government's response during his time as prime minister and earlier as Director of Public Prosecutions, where in 2012 he admitted justice system shortcomings and restructured CPS handling of such cases. Online talk highlights unconfirmed links to roles like NATO or UN Secretary-General and ICC Chief Prosecutor, with some calling it 'failing upward' into unelected global posts.", "summary_zh": "由安妮·朗菲尔德女男爵主持的独立调查，审视警察、议会与检方为何一再辜负群体性儿童性剥削受害者；听证将先听受害者故事，再进入问责阶段。斯塔默将解释其任首相期间及早年任公共起诉署署长时的政府与检方应对——2012 年他曾承认司法系统不足并重组相关案件处理。网络讨论出现北约、联合国秘书长或国际刑事法院首席检察官等未证实传闻，有人讥为「越失败越往上升」进入非民选全球职位。", "body_en": "Keir Starmer Faces Grooming Gangs Inquiry Testimony Amid Global Role Speculation.\n\nKeir Starmer stepped down as UK prime minister in June 2026, and now he's listed to testify in a major inquiry into grooming gangs failures while rumors swirl about top international jobs.\n\nThe independent inquiry, led by Baroness Anne Longfield, probes why police, councils, and prosecutors repeatedly let down victims of group-based child sexual exploitation, with hearings starting later this year on victim stories before accountability phases.\n\nStarmer, who resigned amid political pressures, will explain the government's response during his time as prime minister and earlier as Director of Public Prosecutions, where in 2012 he admitted justice system shortcomings and restructured CPS handling of such cases. Online talk highlights unconfirmed links to roles like NATO or UN Secretary-General and ICC Chief Prosecutor, with some calling it 'failing upward' into unelected global posts.", "body_zh": "斯塔默将就性侵团伙调查作证，国际职位传闻升温。\n\n基尔·斯塔默 2026 年 6 月卸任英国首相，现被列入性侵团伙失职调查证人名单，同时有顶级国际职位传闻。\n\n由安妮·朗菲尔德女男爵主持的独立调查，审视警察、议会与检方为何一再辜负群体性儿童性剥削受害者；听证将先听受害者故事，再进入问责阶段。\n\n斯塔默将解释其任首相期间及早年任公共起诉署署长时的政府与检方应对——2012 年他曾承认司法系统不足并重组相关案件处理。网络讨论出现北约、联合国秘书长或国际刑事法院首席检察官等未证实传闻，有人讥为「越失败越往上升」进入非民选全球职位。", "url": "https://x.com/i/trending/2113181910314664307", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T11:21:14.000Z"}, {"id": "2113177242985750649", "domain": "国际", "title_en": "Hamas Warns Israel of New October 7-Style Attack via UN Envoy", "title_zh": "哈马斯经联合国协调员警告以色列或再发动「10·7」式袭击", "hook_en": "In a stark message passed through a UN coordinator, Hamas signaled readiness for another devastating assault like the one three years ago.", "hook_zh": "哈马斯通过联合国协调员传递强硬信息，称已准备发动类似三年前的毁灭性袭击。", "summary_en": "Last week, Hamas representatives met UN humanitarian coordinator Dr. Ramiz Alakbarov in Gaza and asked him to warn Israeli authorities of a potential October 7-style attack targeting Israel, Judea and Samaria, and even abroad. Alakbarov relayed the unusually direct threat to Maj. Gen. Yoram Halevy of COGAT on Wednesday, prompting a detailed document to Israel's leadership. Hamas linked the warning to Israeli military operations, shifts in Gaza positions, and the Palestinian Authority's election cancellation, amid its financial strains and losses to targeted strikes. While some call the reports fake news, the communication highlights ongoing tensions as Hamas resists eroding control.", "summary_zh": "上周哈马斯代表在加沙会见联合国人道协调员拉米兹·阿拉克巴罗夫，要求其向以色列当局转达可能对以色列、犹地亚与撒玛利亚乃至海外发动「10·7」式袭击的警告。阿拉克巴罗夫周三将这一异常直接的威胁转告 COGAT 的约拉姆·哈莱维少将，并形成文件上报以色列领导层。哈马斯把警告与以军行动、加沙阵地变化及巴勒斯坦权力机构取消选举挂钩，同时面临财政压力与定点打击损失。虽有人指报道虚假，沟通仍凸显哈马斯抗拒控制权被削弱的紧张局势。", "body_en": "Hamas Warns Israel of New October 7-Style Attack via UN Envoy.\n\nIn a stark message passed through a UN coordinator, Hamas signaled readiness for another devastating assault like the one three years ago.\n\nLast week, Hamas representatives met UN humanitarian coordinator Dr. Ramiz Alakbarov in Gaza and asked him to warn Israeli authorities of a potential October 7-style attack targeting Israel, Judea and Samaria, and even abroad. Alakbarov relayed the unusually direct threat to Maj.\n\nGen. Yoram Halevy of COGAT on Wednesday, prompting a detailed document to Israel's leadership. Hamas linked the warning to Israeli military operations, shifts in Gaza positions, and the Palestinian Authority's election cancellation, amid its financial strains and losses to targeted strikes. While some call the reports fake news, the communication highlights ongoing tensions as Hamas resists eroding control.", "body_zh": "哈马斯经联合国协调员警告以色列或再发动「10·7」式袭击。\n\n哈马斯通过联合国协调员传递强硬信息，称已准备发动类似三年前的毁灭性袭击。\n\n上周哈马斯代表在加沙会见联合国人道协调员拉米兹·阿拉克巴罗夫，要求其向以色列当局转达可能对以色列、犹地亚与撒玛利亚乃至海外发动「10·7」式袭击的警告。阿拉克巴罗夫周三将这一异常直接的威胁转告 COGAT 的约拉姆·哈莱维少将，并形成文件上报以色列领导层。\n\n哈马斯把警告与以军行动、加沙阵地变化及巴勒斯坦权力机构取消选举挂钩，同时面临财政压力与定点打击损失。虽有人指报道虚假，沟通仍凸显哈马斯抗拒控制权被削弱的紧张局势。", "url": "https://x.com/i/trending/2113177242985750649", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-22T23:24:34.000Z"}, {"id": "2112994548645540037", "domain": "国际", "title_en": "National Security Officials Prep States for Potential Trump Midterm Interference", "title_zh": "国家安全官员为潜在的特朗普中期干预做好准备", "hook_en": "A handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.", "hook_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。", "summary_en": "The Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms. They focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "summary_zh": "《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。他们专注于预防措施，担心民主规范，没有党派动机。 批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "body_en": "National Security Officials Prep States for Potential Trump Midterm Interference.\n\nA handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.\n\nThe Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms.\n\nThey focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "body_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。\n\n《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。\n\n他们专注于预防措施，担心民主规范，没有党派动机。批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "url": "https://x.com/i/trending/2112994548645540037", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:43.000Z"}, {"id": "2112991178429722996", "domain": "国际", "title_en": "Europe Scrambles for Negotiator to Engage Putin on Ukraine", "title_zh": "欧洲急寻谈判代表，直接与普京谈乌克兰", "hook_en": "With US-Russia-Ukraine talks gaining momentum, European leaders worry they'll be left on the sidelines as deals get made without them.", "hook_zh": "美俄乌磋商升温，欧洲领导人担心协议在自己缺席下谈成。", "summary_en": "US envoy Steve Witkoff met Putin in St. Petersburg this week, where Moscow agreed in principle to technical-level talks on postwar security guarantees as soon as mid-November; Ukraine had already backed the idea in Oslo. Europe is urgently debating a unified negotiator to speak directly with Putin, floating names like Finnish President Alexander Stubb, Ursula von der Leyen, António Costa, and Kaja Kallas amid fears of being sidelined by a US-led deal. Stubb draws interest due to Finland's border with Russia and his ties to Trump, though skeptics see Russia's openness as tactical rather than a true shift, with real bargaining eyed for early November.", "summary_zh": "美国特使史蒂夫·维特科夫本周在圣彼得堡会见普京，莫斯科原则上同意最早 11 月中旬就战后安全保证展开技术层会谈；乌克兰此前在奥斯陆已支持该设想。欧洲正紧急讨论统一谈判代表直接对话普京，候选包括芬兰总统斯图布、冯德莱恩、安东尼奥·科斯塔与卡娅·卡拉斯，担心被美国主导的协议边缘化。斯图布因芬俄边境与特朗普关系受关注；怀疑者视俄方开放为战术，真正讨价还价或在 11 月初。", "body_en": "Europe Scrambles for Negotiator to Engage Putin on Ukraine.\n\nWith US-Russia-Ukraine talks gaining momentum, European leaders worry they'll be left on the sidelines as deals get made without them.\n\nUS envoy Steve Witkoff met Putin in St. Petersburg this week, where Moscow agreed in principle to technical-level talks on postwar security guarantees as soon as mid-November; Ukraine had already backed the idea in Oslo.\n\nEurope is urgently debating a unified negotiator to speak directly with Putin, floating names like Finnish President Alexander Stubb, Ursula von der Leyen, António Costa, and Kaja Kallas amid fears of being sidelined by a US-led deal. Stubb draws interest due to Finland's border with Russia and his ties to Trump, though skeptics see Russia's openness as tactical rather than a true shift, with real bargaining eyed for early November.", "body_zh": "欧洲急寻谈判代表，直接与普京谈乌克兰。\n\n美俄乌磋商升温，欧洲领导人担心协议在自己缺席下谈成。\n\n美国特使史蒂夫·维特科夫本周在圣彼得堡会见普京，莫斯科原则上同意最早 11 月中旬就战后安全保证展开技术层会谈；乌克兰此前在奥斯陆已支持该设想。\n\n欧洲正紧急讨论统一谈判代表直接对话普京，候选包括芬兰总统斯图布、冯德莱恩、安东尼奥·科斯塔与卡娅·卡拉斯，担心被美国主导的协议边缘化。斯图布因芬俄边境与特朗普关系受关注；怀疑者视俄方开放为战术，真正讨价还价或在 11 月初。", "url": "https://x.com/i/trending/2112991178429722996", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T22:31:32.000Z"}, {"id": "2113277136840880496", "domain": "国际", "title_en": "State Department Questions Officers on Presidential Votes for Promotions", "title_zh": "美国国务院被指在晋升审查中询问总统选票", "hook_en": "Career diplomats expecting routine promotion reviews instead faced a surprising question: who did you vote for in 2016, 2020, and 2024?", "hook_zh": "本以为例行晋升面谈的职业外交官，却被问到 2016、2020、2024 年投了谁。", "summary_en": "The State Department is reportedly asking some foreign service officers about their votes in recent presidential elections and reviewing their campaign donations, with only Trump voters eligible for mid-to-upper level roles according to top officials. Six current and former officials confirmed the practice, which critics call a blatant violation of federal law barring political affiliation in civil service decisions. A department spokesperson denied questioning political affiliations, insisting promotions prioritize merit, fidelity to the Constitution, and executing the president's foreign policy vision amid efforts to reshape senior ranks.", "summary_zh": "据报国务院询问部分外交官近期总统选举投票，并审查竞选捐款；高层称仅特朗普选民可晋升中高层。六名现任与前任官员证实做法，批评者称公然违反禁止以政治归属决定文职任用的联邦法律。部门发言人否认询问政治归属，坚称晋升重视业绩、忠于宪法与执行总统外交愿景，同时正重塑高级职级。", "body_en": "State Department Questions Officers on Presidential Votes for Promotions.\n\nCareer diplomats expecting routine promotion reviews instead faced a surprising question: who did you vote for in 2016, 2020, and 2024?\n\nThe State Department is reportedly asking some foreign service officers about their votes in recent presidential elections and reviewing their campaign donations, with only Trump voters eligible for mid-to-upper level roles according to top officials.\n\nSix current and former officials confirmed the practice, which critics call a blatant violation of federal law barring political affiliation in civil service decisions. A department spokesperson denied questioning political affiliations, insisting promotions prioritize merit, fidelity to the Constitution, and executing the president's foreign policy vision amid efforts to reshape senior ranks.", "body_zh": "美国国务院被指在晋升审查中询问总统选票。\n\n本以为例行晋升面谈的职业外交官，却被问到 2016、2020、2024 年投了谁。\n\n据报国务院询问部分外交官近期总统选举投票，并审查竞选捐款；高层称仅特朗普选民可晋升中高层。\n\n六名现任与前任官员证实做法，批评者称公然违反禁止以政治归属决定文职任用的联邦法律。部门发言人否认询问政治归属，坚称晋升重视业绩、忠于宪法与执行总统外交愿景，同时正重塑高级职级。", "url": "https://x.com/i/trending/2113277136840880496", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T21:46:38.000Z"}, {"id": "2112984436081897542", "domain": "国际", "title_en": "U.S. Orders Embassy Families to Leave Saudi Arabia Amid Houthi Attacks", "title_zh": "胡塞袭击后美国下令驻沙特使馆家属撤离", "hook_en": "Two people lost their lives in a Houthi drone strike on a Saudi airport, prompting the U.S. to pull non-emergency embassy staff and families out immediately.", "hook_zh": "胡塞无人机袭击沙特机场致两人死亡，美国立即撤离驻沙特使馆非紧急人员与家属。", "summary_en": "The U.S. has directed non-emergency personnel and families at its Saudi Arabia embassy to depart right away due to escalating attacks by Iranian-backed Houthi militants on civilian airports and infrastructure. Similar orders went out for families in the UAE, Jordan, Qatar, and Bahrain. Saudi authorities confirmed the October 21 attack on King Fahd International Airport in Dammam killed a Saudi citizen and an Indian national, injured eight others, and briefly halted operations before resuming. The moves highlight rising regional tensions, with oil prices climbing and coalition forces intercepting drones aimed at cities like Riyadh.", "summary_zh": "因伊朗支持的胡塞武装对民用机场与基础设施袭击升级，美国指示驻沙特使馆非紧急人员与家属立即离境；阿联酋、约旦、卡塔尔与巴林家属亦接类似指令。沙特证实 10 月 21 日达曼法赫德国王国际机场遇袭，造成一名沙特公民与一名印度公民死亡、八人受伤，机场短暂关闭后恢复。地区紧张升温，油价攀升，联军拦截飞向利雅得等城市的无人机。", "body_en": "U.S. Orders Embassy Families to Leave Saudi Arabia Amid Houthi Attacks.\n\nTwo people lost their lives in a Houthi drone strike on a Saudi airport, prompting the U.S. to pull non-emergency embassy staff and families out immediately.\n\nThe U.S. has directed non-emergency personnel and families at its Saudi Arabia embassy to depart right away due to escalating attacks by Iranian-backed Houthi militants on civilian airports and infrastructure.\n\nSimilar orders went out for families in the UAE, Jordan, Qatar, and Bahrain. Saudi authorities confirmed the October 21 attack on King Fahd International Airport in Dammam killed a Saudi citizen and an Indian national, injured eight others, and briefly halted operations before resuming. The moves highlight rising regional tensions, with oil prices climbing and coalition forces intercepting drones aimed at cities like Riyadh.", "body_zh": "胡塞袭击后美国下令驻沙特使馆家属撤离。\n\n胡塞无人机袭击沙特机场致两人死亡，美国立即撤离驻沙特使馆非紧急人员与家属。\n\n因伊朗支持的胡塞武装对民用机场与基础设施袭击升级，美国指示驻沙特使馆非紧急人员与家属立即离境；阿联酋、约旦、卡塔尔与巴林家属亦接类似指令。\n\n沙特证实 10 月 21 日达曼法赫德国王国际机场遇袭，造成一名沙特公民与一名印度公民死亡、八人受伤，机场短暂关闭后恢复。地区紧张升温，油价攀升，联军拦截飞向利雅得等城市的无人机。", "url": "https://x.com/i/trending/2112984436081897542", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-22T23:44:15.000Z"}, {"id": "2112984434769109280", "domain": "国际", "title_en": "U.S. Embassy Accuses Canada of Influencing American Elections", "title_zh": "美国驻渥太华使馆指责加拿大干预美国选举", "hook_en": "The U.S. Embassy in Ottawa dropped a pointed fact sheet listing Canadian officials' moves to sway U.S. politics amid rising tariff tensions.", "hook_zh": "美国驻渥太华使馆发布尖锐事实清单，罗列加方官员在关税紧张下试图影响美国政治的举动。", "summary_en": "On October 21, the embassy released 'Monitoring Canadian Activities in U.S. Politics,' citing Industry Minister Mélanie Joly's threats of tariffs on Republican states, Ontario Premier Doug Ford's $75 million ad campaign in those areas, and Liberal MP Anthony Housefather campaigning for a Democrat in Florida. It highlights Canada's high rate of citizens prosecuted for illegal U.S. voting and warns all Canadians to stay out of American elections. Canadian leaders like Prime Minister Mark Carney call their actions economic defenses against U.S. tariffs, announcing $9 billion in support for Ontario's key industries the same day.", "summary_zh": "10 月 21 日使馆发布《监测加拿大在美国政治中的活动》，列举工业部长梅兰妮·乔利威胁对共和党州加征关税、安大略省长道格·福特在这些地区投放 7500 万美元广告，以及自由党议员安东尼·豪斯法瑟在佛罗里达为民主党助选等。文件称加拿大公民因非法在美投票被起诉比例高，并警告所有加拿大人勿介入美国选举。总理马克·卡尼等称此为应对美国关税的经济防卫，同日宣布向安大略关键产业提供 90 亿加元支持。", "body_en": "U.S. Embassy Accuses Canada of Influencing American Elections.\n\nThe U.S. Embassy in Ottawa dropped a pointed fact sheet listing Canadian officials' moves to sway U.S. politics amid rising tariff tensions.\n\nOn October 21, the embassy released 'Monitoring Canadian Activities in U.S. Politics,' citing Industry Minister Mélanie Joly's threats of tariffs on Republican states, Ontario Premier Doug Ford's $75 million ad campaign in those areas, and Liberal MP Anthony Housefather campaigning for a Democrat in Florida. It highlights Canada's high rate of citizens prosecuted for illegal U.S.\n\nvoting and warns all Canadians to stay out of American elections. Canadian leaders like Prime Minister Mark Carney call their actions economic defenses against U.S. tariffs, announcing $9 billion in support for Ontario's key industries the same day.", "body_zh": "美国驻渥太华使馆指责加拿大干预美国选举。\n\n美国驻渥太华使馆发布尖锐事实清单，罗列加方官员在关税紧张下试图影响美国政治的举动。\n\n10 月 21 日使馆发布《监测加拿大在美国政治中的活动》，列举工业部长梅兰妮·乔利威胁对共和党州加征关税、安大略省长道格·福特在这些地区投放 7500 万美元广告，以及自由党议员安东尼·豪斯法瑟在佛罗里达为民主党助选等。\n\n文件称加拿大公民因非法在美投票被起诉比例高，并警告所有加拿大人勿介入美国选举。总理马克·卡尼等称此为应对美国关税的经济防卫，同日宣布向安大略关键产业提供 90 亿加元支持。", "url": "https://x.com/i/trending/2112984434769109280", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T22:01:02.000Z"}, {"id": "2112787035866206217", "domain": "国际", "title_en": "Zelenskyy Open to Freezing Ukraine War Along Current Lines", "title_zh": "泽连斯基表示可接受按现有战线冻结乌战", "hook_en": "Zelenskyy spoke candidly about the heartache of lost lives and stolen childhoods, while signaling readiness for a ceasefire to halt the suffering.", "hook_zh": "泽连斯基坦言生命与童年被夺走的痛楚，同时释放接受停火以止住苦难的信号。", "summary_en": "Ukrainian President Volodymyr Zelenskyy said he would accept a peace deal that freezes the war along current front lines, retaining 75 percent or more of Ukraine’s territory as a realistic step to stop the fighting. The remarks follow pressure from President Donald Trump, who urged Zelenskyy to negotiate, amid meetings like U.S. envoy Steve Witkoff’s talks with both leaders and potential trilateral discussions in November. Zelenskyy stressed a ceasefire as the minimum from Russia before seeking security guarantees, while recounting horrors like tortured civilians in Bucha that fuel Ukraine’s resolve despite the human cost.", "summary_zh": "乌克兰总统泽连斯基称，可接受沿现有前线冻结战争的和平方案，保留乌克兰 75% 或更多领土，作为停止战斗的现实一步。言论出现在特朗普总统敦促其谈判的压力下，美国特使维特科夫已分别会晤双方，三方会谈或于 11 月。泽连斯基强调至少需俄方停火，再谈安全保证，并忆及布查平民遭酷刑等惨剧支撑乌方决心，尽管代价沉重。", "body_en": "Zelenskyy Open to Freezing Ukraine War Along Current Lines.\n\nZelenskyy spoke candidly about the heartache of lost lives and stolen childhoods, while signaling readiness for a ceasefire to halt the suffering.\n\nUkrainian President Volodymyr Zelenskyy said he would accept a peace deal that freezes the war along current front lines, retaining 75 percent or more of Ukraine’s territory as a realistic step to stop the fighting. The remarks follow pressure from President Donald Trump, who urged Zelenskyy to negotiate, amid meetings like U.S.\n\nenvoy Steve Witkoff’s talks with both leaders and potential trilateral discussions in November. Zelenskyy stressed a ceasefire as the minimum from Russia before seeking security guarantees, while recounting horrors like tortured civilians in Bucha that fuel Ukraine’s resolve despite the human cost.", "body_zh": "泽连斯基表示可接受按现有战线冻结乌战。\n\n泽连斯基坦言生命与童年被夺走的痛楚，同时释放接受停火以止住苦难的信号。\n\n乌克兰总统泽连斯基称，可接受沿现有前线冻结战争的和平方案，保留乌克兰 75% 或更多领土，作为停止战斗的现实一步。\n\n言论出现在特朗普总统敦促其谈判的压力下，美国特使维特科夫已分别会晤双方，三方会谈或于 11 月。泽连斯基强调至少需俄方停火，再谈安全保证，并忆及布查平民遭酷刑等惨剧支撑乌方决心，尽管代价沉重。", "url": "https://x.com/i/trending/2112787035866206217", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T16:27:29.000Z"}, {"id": "2113261578745249983", "domain": "国际", "title_en": "Carney Holds Palestinian Authority Accountable as Elections Delayed to 2027", "title_zh": "卡尼称将问责巴勒斯坦权力机构推迟选举至 2027", "hook_en": "Prime Minister Mark Carney promised accountability for the Palestinian Authority's election delay, but many questioned what that really means amid continued Canadian aid.", "hook_zh": "总理马克·卡尼承诺就巴权力机构推迟选举问责，但许多人质疑在持续对加援助下这意味着什么。", "summary_en": "During a press conference in Ottawa, Carney stated Canada supports free elections excluding Hamas and will hold the authority to its commitments after President Mahmoud Abbas postponed legislative votes from next month to September 2027. The delay followed talks with Palestinian factions, prompting Canada and allies like Australia, France, and the UK to express regret and urge a rethink. Critics highlighted the lack of clear enforcement amid $100 million in recent funding and hundreds of millions since 2023, sparking debate on whether recognition conditions tied to reforms and a two-state solution carry real weight.", "summary_zh": "卡尼在渥太华记者会上表示，加拿大支持排除哈马斯的自由选举，并将在马哈茂德·阿巴斯把立法选举从下月推迟至 2027 年 9 月后，要求权力机构兑现承诺。推迟发生在与巴勒斯坦各派会谈后，加拿大及澳、法、英等盟友表示遗憾并敦促重新考虑。批评者指出近期约 1 亿美元及自 2023 年以来数亿美元援助下缺乏明确强制手段，引发对「改革与两国方案」承认条件是否真正有分量的辩论。", "body_en": "Carney Holds Palestinian Authority Accountable as Elections Delayed to 2027.\n\nPrime Minister Mark Carney promised accountability for the Palestinian Authority's election delay, but many questioned what that really means amid continued Canadian aid.\n\nDuring a press conference in Ottawa, Carney stated Canada supports free elections excluding Hamas and will hold the authority to its commitments after President Mahmoud Abbas postponed legislative votes from next month to September 2027.\n\nThe delay followed talks with Palestinian factions, prompting Canada and allies like Australia, France, and the UK to express regret and urge a rethink. Critics highlighted the lack of clear enforcement amid $100 million in recent funding and hundreds of millions since 2023, sparking debate on whether recognition conditions tied to reforms and a two-state solution carry real weight.", "body_zh": "卡尼称将问责巴勒斯坦权力机构推迟选举至 2027。\n\n总理马克·卡尼承诺就巴权力机构推迟选举问责，但许多人质疑在持续对加援助下这意味着什么。\n\n卡尼在渥太华记者会上表示，加拿大支持排除哈马斯的自由选举，并将在马哈茂德·阿巴斯把立法选举从下月推迟至 2027 年 9 月后，要求权力机构兑现承诺。\n\n推迟发生在与巴勒斯坦各派会谈后，加拿大及澳、法、英等盟友表示遗憾并敦促重新考虑。批评者指出近期约 1 亿美元及自 2023 年以来数亿美元援助下缺乏明确强制手段，引发对「改革与两国方案」承认条件是否真正有分量的辩论。", "url": "https://x.com/i/trending/2113261578745249983", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T13:35:25.000Z"}, {"id": "2113325565457404345", "domain": "国际", "title_en": "Guterres Calls for Immediate Halt to Global Conflicts", "title_zh": "古特雷斯呼吁立即停止全球冲突", "hook_en": "Standing at a UN podium on October 22, António Guterres pleaded for an end to wars spreading like an 'El Nino' across the world, urging protection for civilians everywhere.", "hook_zh": "10 月 22 日安东尼奥·古特雷斯在联合国讲台呼吁，像「厄尔尼诺」般扩散的战争必须停止，保护各地平民。", "summary_en": "UN Secretary-General António Guterres demanded an immediate stop to fighting in conflicts from Gaza and the West Bank to Ukraine and Sudan, warning that wars are expanding and causing economic chaos like drained resources and rising prices. He highlighted severe aid restrictions in Gaza, daily settler attacks in the West Bank, and called for a two-state solution between Israel and Palestine. Guterres condemned attacks on civilians and infrastructure as violations of international law, including Houthi strikes on Saudi Arabia, while stressing the need for diplomacy ahead of his Egypt visit as winter nears in Gaza.", "summary_zh": "联合国秘书长古特雷斯要求立即停止从加沙、约旦河西岸到乌克兰与苏丹等地的战斗，警告战争扩张正造成资源枯竭、物价上涨等经济混乱。他强调加沙援助严重受限、西岸定居者袭击频发，并呼吁以巴两国方案。古特雷斯谴责袭击平民与基础设施违反国际法，包括胡塞对沙特的打击，并在加沙入冬前出访埃及前强调外交必要性。", "body_en": "Guterres Calls for Immediate Halt to Global Conflicts.\n\nStanding at a UN podium on October 22, António Guterres pleaded for an end to wars spreading like an 'El Nino' across the world, urging protection for civilians everywhere.\n\nUN Secretary-General António Guterres demanded an immediate stop to fighting in conflicts from Gaza and the West Bank to Ukraine and Sudan, warning that wars are expanding and causing economic chaos like drained resources and rising prices.\n\nHe highlighted severe aid restrictions in Gaza, daily settler attacks in the West Bank, and called for a two-state solution between Israel and Palestine. Guterres condemned attacks on civilians and infrastructure as violations of international law, including Houthi strikes on Saudi Arabia, while stressing the need for diplomacy ahead of his Egypt visit as winter nears in Gaza.", "body_zh": "古特雷斯呼吁立即停止全球冲突。\n\n10 月 22 日安东尼奥·古特雷斯在联合国讲台呼吁，像「厄尔尼诺」般扩散的战争必须停止，保护各地平民。\n\n联合国秘书长古特雷斯要求立即停止从加沙、约旦河西岸到乌克兰与苏丹等地的战斗，警告战争扩张正造成资源枯竭、物价上涨等经济混乱。\n\n他强调加沙援助严重受限、西岸定居者袭击频发，并呼吁以巴两国方案。古特雷斯谴责袭击平民与基础设施违反国际法，包括胡塞对沙特的打击，并在加沙入冬前出访埃及前强调外交必要性。", "url": "https://x.com/i/trending/2113325565457404345", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-22T17:56:03.000Z"}, {"id": "2113133157100699818", "domain": "国际", "title_en": "Trump Signals Imminent Action Against Iran After Midterms", "title_zh": "特朗普暗示中期选举后或对伊朗采取行动", "hook_en": "Under the nighttime lights near Air Force One, President Trump told reporters the U.S. isn't negotiating with Iran and something will happen fairly soon.", "hook_zh": "在空军一号附近夜间灯光下，特朗普告诉记者：美国未与伊朗谈判，事情「很快」会发生。", "summary_en": "Speaking at Joint Base Andrews, Trump indicated a potential U.S. policy shift toward Iran, expecting action after the November 3 midterms, amid reports of U.S.-Israeli plans for strikes on energy infrastructure, nuclear sites, and missile arsenals. The two nations have ramped up joint exercises, including flights over Iraq, while Iranian officials warn of strong retaliation and Israeli leaders hold off unless missile preparations are spotted. This comes after eight months of conflict sparked by initial U.S. and Israeli strikes in February, with aims to pressure Iran's economy though escalation risks remain.", "summary_zh": "特朗普在安德鲁斯联合基地表示，美国对伊朗政策或有转变，预期 11 月 3 日中期选举后采取行动；有报道称美以正筹划打击能源设施、核设施与导弹库。两国加大联合演习，包括飞越伊拉克；伊朗官员警告将强力报复，以色列领导层则称除非发现导弹准备否则暂缓。此前景出现在 2 月美以首轮打击引爆的约八个月冲突之后，旨在施压伊朗经济，但升级风险仍在。", "body_en": "Trump Signals Imminent Action Against Iran After Midterms.\n\nUnder the nighttime lights near Air Force One, President Trump told reporters the U.S. isn't negotiating with Iran and something will happen fairly soon.\n\nSpeaking at Joint Base Andrews, Trump indicated a potential U.S. policy shift toward Iran, expecting action after the November 3 midterms, amid reports of U.S.-Israeli plans for strikes on energy infrastructure, nuclear sites, and missile arsenals.\n\nThe two nations have ramped up joint exercises, including flights over Iraq, while Iranian officials warn of strong retaliation and Israeli leaders hold off unless missile preparations are spotted. This comes after eight months of conflict sparked by initial U.S. and Israeli strikes in February, with aims to pressure Iran's economy though escalation risks remain.", "body_zh": "特朗普暗示中期选举后或对伊朗采取行动。\n\n在空军一号附近夜间灯光下，特朗普告诉记者：美国未与伊朗谈判，事情「很快」会发生。\n\n特朗普在安德鲁斯联合基地表示，美国对伊朗政策或有转变，预期 11 月 3 日中期选举后采取行动；有报道称美以正筹划打击能源设施、核设施与导弹库。\n\n两国加大联合演习，包括飞越伊拉克；伊朗官员警告将强力报复，以色列领导层则称除非发现导弹准备否则暂缓。此前景出现在 2 月美以首轮打击引爆的约八个月冲突之后，旨在施压伊朗经济，但升级风险仍在。", "url": "https://x.com/i/trending/2113133157100699818", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T22:32:14.000Z"}, {"id": "2113209486047637631", "domain": "体育", "title_en": "Rwanda Secures 10-Year Deal to Host F1 African Grand Prix from 2030s", "title_zh": "卢旺达签下十年协议，2030 年代起举办 F1 非洲大奖赛", "hook_en": "Formula One returns to Africa after over 30 years, landing in Rwanda with a stunning new track near Kigali that promises dramatic elevation drops and 100,000 cheering fans.", "hook_zh": "一级方程式时隔三十多年重返非洲，落户卢旺达基加利附近新赛道，落差巨大、可容纳约 10 万观众。", "summary_en": "Rwanda signed a 10-year contract this month to host the Formula 1 African Grand Prix starting in the early 2030s on a purpose-built circuit in Bugesera, 40 kilometers south of Kigali, next to a new international airport. F1 chief Stefano Domenicali called it a landmark for racing on every inhabited continent, while President Paul Kagame sees it as a boost for tourism, jobs, and infrastructure. Rwandans celebrated the nation's drive to thrive, though critics including Amnesty International question human rights issues and ties to DRC conflict, labeling it potential sportswashing.", "summary_zh": "卢旺达本月签署十年合约，自 2030 年代初起在布格塞拉专为 F1 建造的赛道举办非洲大奖赛，位于基加利以南约 40 公里、毗邻新建国际机场。F1 总裁多梅尼卡利称之为覆盖每一有人居住大洲的里程碑；总统卡加梅视其为旅游、就业与基建助力。卢旺达人为国家进取欢呼，大赦国际等批评者则质疑人权与刚果（金）冲突关联，指或为「体育洗白」。", "body_en": "Rwanda Secures 10-Year Deal to Host F1 African Grand Prix from 2030s.\n\nFormula One returns to Africa after over 30 years, landing in Rwanda with a stunning new track near Kigali that promises dramatic elevation drops and 100,000 cheering fans.\n\nRwanda signed a 10-year contract this month to host the Formula 1 African Grand Prix starting in the early 2030s on a purpose-built circuit in Bugesera, 40 kilometers south of Kigali, next to a new international airport.\n\nF1 chief Stefano Domenicali called it a landmark for racing on every inhabited continent, while President Paul Kagame sees it as a boost for tourism, jobs, and infrastructure. Rwandans celebrated the nation's drive to thrive, though critics including Amnesty International question human rights issues and ties to DRC conflict, labeling it potential sportswashing.", "body_zh": "卢旺达签下十年协议，2030 年代起举办 F1 非洲大奖赛。\n\n一级方程式时隔三十多年重返非洲，落户卢旺达基加利附近新赛道，落差巨大、可容纳约 10 万观众。\n\n卢旺达本月签署十年合约，自 2030 年代初起在布格塞拉专为 F1 建造的赛道举办非洲大奖赛，位于基加利以南约 40 公里、毗邻新建国际机场。\n\nF1 总裁多梅尼卡利称之为覆盖每一有人居住大洲的里程碑；总统卡加梅视其为旅游、就业与基建助力。卢旺达人为国家进取欢呼，大赦国际等批评者则质疑人权与刚果（金）冲突关联，指或为「体育洗白」。", "url": "https://x.com/i/trending/2113209486047637631", "category": "News", "topics": ["Formula 1"], "updated_at": "2026-10-22T10:07:41.000Z"}, {"id": "2112692979785679112", "domain": "体育", "title_en": "Trump Demands Apology from LeBron James Over Anthem Golf Swing Video", "title_zh": "特朗普要求勒布朗就国歌时「高尔夫挥杆」道歉", "hook_en": "Before the 76ers' opener at Madison Square Garden, LeBron James swung his arms like a golf club during the national anthem—prompting President Trump to call it a total disgrace.", "hook_zh": "76 人队在麦迪逊广场花园揭幕战国歌期间，勒布朗·詹姆斯挥臂如打高尔夫，特朗普称完全丢脸并要求道歉。", "summary_en": "The video from Tuesday's game against the Knicks shows the 41-year-old James in his new 76ers uniform making the motion while most teammates stood still, leading to online backlash labeling it disrespectful to the flag and military. Trump posted Thursday demanding James apologize to fallen heroes, amid their long history of public clashes. James tallied 14 points, nine rebounds, and seven assists in the 106-100 win but has not responded; past clips show him stretching during anthems, fueling debate on athlete conduct.", "summary_zh": "对阵尼克斯的周二比赛视频显示，41 岁的詹姆斯身着新 76 人队服做挥杆动作，多数队友则肃立，网络指责其不敬国旗与军人。特朗普周四发文要求詹姆斯向牺牲英雄道歉，二人素有公开交锋。詹姆斯该场 14 分 9 篮板 7 助攻助球队 106-100 取胜，尚未回应；过往亦有国歌期间拉伸画面，续燃运动员举止辩论。", "body_en": "Trump Demands Apology from LeBron James Over Anthem Golf Swing Video.\n\nBefore the 76ers' opener at Madison Square Garden, LeBron James swung his arms like a golf club during the national anthem—prompting President Trump to call it a total disgrace.\n\nThe video from Tuesday's game against the Knicks shows the 41-year-old James in his new 76ers uniform making the motion while most teammates stood still, leading to online backlash labeling it disrespectful to the flag and military.\n\nTrump posted Thursday demanding James apologize to fallen heroes, amid their long history of public clashes. James tallied 14 points, nine rebounds, and seven assists in the 106-100 win but has not responded; past clips show him stretching during anthems, fueling debate on athlete conduct.", "body_zh": "特朗普要求勒布朗就国歌时「高尔夫挥杆」道歉。\n\n76 人队在麦迪逊广场花园揭幕战国歌期间，勒布朗·詹姆斯挥臂如打高尔夫，特朗普称完全丢脸并要求道歉。\n\n对阵尼克斯的周二比赛视频显示，41 岁的詹姆斯身着新 76 人队服做挥杆动作，多数队友则肃立，网络指责其不敬国旗与军人。\n\n特朗普周四发文要求詹姆斯向牺牲英雄道歉，二人素有公开交锋。詹姆斯该场 14 分 9 篮板 7 助攻助球队 106-100 取胜，尚未回应；过往亦有国歌期间拉伸画面，续燃运动员举止辩论。", "url": "https://x.com/i/trending/2112692979785679112", "category": "News", "topics": ["NBA", "Politics"], "updated_at": "2026-10-22T21:39:34.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2113335031733379561", "domain": "体育", "title_en": "FIFA Opens Bids for U.S. Media Rights to 2030 and 2034 World Cups", "title_zh": "国际足联就 2030、2034 世界杯美国转播权公开招标", "hook_en": "Fresh off the record-breaking 2026 World Cup that drew 13.5 million U.S. viewers per match, FIFA is now inviting bids for the next tournaments' broadcast rights.", "hook_zh": "2026 世界杯美国场均约 1350 万观众创纪录后，国际足联开始邀请下届赛事转播权竞标。", "summary_en": "The tender process targets U.S. and Puerto Rican media rights, with bids due November 19 and a winner expected by year's end. Fox, Telemundo, ESPN, Netflix, Amazon, and YouTube are among those poised to compete, potentially offering bundled English-Spanish packages or streamer-network partnerships. Following 2026's massive ratings jump and $664 million in ad revenue through nine months, experts anticipate much higher fees than the prior $485 million English and $600 million Spanish deals. The process could transform how American fans tune into the 2030 event in Spain, Portugal, and Morocco, plus Saudi Arabia's 2034 hosting.", "summary_zh": "招标面向美国与波多黎各媒体权，投标截止 11 月 19 日，年底前望定标。福克斯、特莱蒙多、ESPN、Netflix、亚马逊与 YouTube 等或参与，可能打包英西双语或流媒体—电视网合作。继 2026 收视大涨与九个月广告收入约 6.64 亿美元后，专家预期报价远高于此前英语 4.85 亿、西语 6 亿美元的交易。结果将重塑美国球迷观看 2030（西班牙、葡萄牙、摩洛哥）与 2034（沙特）赛事的方式。", "body_en": "FIFA Opens Bids for U.S. Media Rights to 2030 and 2034 World Cups.\n\nFresh off the record-breaking 2026 World Cup that drew 13.5 million U.S. viewers per match, FIFA is now inviting bids for the next tournaments' broadcast rights.\n\nThe tender process targets U.S. and Puerto Rican media rights, with bids due November 19 and a winner expected by year's end.\n\nFox, Telemundo, ESPN, Netflix, Amazon, and YouTube are among those poised to compete, potentially offering bundled English-Spanish packages or streamer-network partnerships. Following 2026's massive ratings jump and $664 million in ad revenue through nine months, experts anticipate much higher fees than the prior $485 million English and $600 million Spanish deals. The process could transform how American fans tune into the 2030 event in Spain, Portugal, and Morocco, plus Saudi Arabia's 2034 hosting.", "body_zh": "国际足联就 2030、2034 世界杯美国转播权公开招标。\n\n2026 世界杯美国场均约 1350 万观众创纪录后，国际足联开始邀请下届赛事转播权竞标。\n\n招标面向美国与波多黎各媒体权，投标截止 11 月 19 日，年底前望定标。福克斯、特莱蒙多、ESPN、Netflix、亚马逊与 YouTube 等或参与，可能打包英西双语或流媒体—电视网合作。\n\n继 2026 收视大涨与九个月广告收入约 6.64 亿美元后，专家预期报价远高于此前英语 4.85 亿、西语 6 亿美元的交易。结果将重塑美国球迷观看 2030（西班牙、葡萄牙、摩洛哥）与 2034（沙特）赛事的方式。", "url": "https://x.com/i/trending/2113335031733379561", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-22T18:27:54.000Z"}, {"id": "2112839270939480210", "domain": "体育", "title_en": "Fans Debate Sehwag's Chances in 2003 World Cup Final", "title_zh": "球迷热议：2003 世界杯决赛赛瓦格能否改变结局", "hook_en": "A clip from the 2003 Cricket World Cup final brings back memories of Virender Sehwag's gritty 82 against Australia's massive 359. Fans now question if anyone truly believed India could chase it down.", "hook_zh": "2003 板球世界杯决赛片段重温赛瓦格对阵澳大利亚狂砍 82 分的韧性；球迷追问：当时真有人相信印度能追上 359 吗？", "summary_en": "In Johannesburg's Wanderers Stadium, Australia racked up 359 for 2, powered by Ricky Ponting's unbeaten 140 and Damien Martyn's 88, while India collapsed to 234 in 39.2 overs. Sehwag top-scored with 82 before a run-out, but many fans say the match was lost early, especially after Sachin Tendulkar's quick dismissal for 4, with no real belief in a miracle chase. Others recall fleeting hope while Sehwag batted or during rain breaks under Duckworth-Lewis, noting the era's rarity of big chases and Australia's dominance. The clip revives nostalgia, blending on-field drama with debates over how time warps those tense moments.", "summary_zh": "约翰内斯堡 Wanderers，澳大利亚以庞廷未出局 140、马汀 88 分打出 359/2，印度 39.2 轮仅得 234。赛瓦格 82 分为最高分后被跑出，许多球迷认为早早丢掉比赛，尤其萨钦·滕杜尔卡仅得 4 分速退，无人真正相信奇迹追分。也有人记得赛瓦格在场或雨延用达克沃斯-刘易斯时的一丝希望，并指出那个年代大分追赶罕见、澳队统治力强。片段唤起怀旧，交织场上戏剧与时间如何改写紧张记忆的争论。", "body_en": "Fans Debate Sehwag's Chances in 2003 World Cup Final.\n\nA clip from the 2003 Cricket World Cup final brings back memories of Virender Sehwag's gritty 82 against Australia's massive 359. Fans now question if anyone truly believed India could chase it down.\n\nIn Johannesburg's Wanderers Stadium, Australia racked up 359 for 2, powered by Ricky Ponting's unbeaten 140 and Damien Martyn's 88, while India collapsed to 234 in 39.2 overs. Sehwag top-scored with 82 before a run-out, but many fans say the match was lost early, especially after Sachin Tendulkar's quick dismissal for 4, with no real belief in a miracle chase.\n\nOthers recall fleeting hope while Sehwag batted or during rain breaks under Duckworth-Lewis, noting the era's rarity of big chases and Australia's dominance. The clip revives nostalgia, blending on-field drama with debates over how time warps those tense moments.", "body_zh": "球迷热议：2003 世界杯决赛赛瓦格能否改变结局。\n\n2003 板球世界杯决赛片段重温赛瓦格对阵澳大利亚狂砍 82 分的韧性；球迷追问：当时真有人相信印度能追上 359 吗？\n\n约翰内斯堡 Wanderers，澳大利亚以庞廷未出局 140、马汀 88 分打出 359/2，印度 39.2 轮仅得 234。赛瓦格 82 分为最高分后被跑出，许多球迷认为早早丢掉比赛，尤其萨钦·滕杜尔卡仅得 4 分速退，无人真正相信奇迹追分。\n\n也有人记得赛瓦格在场或雨延用达克沃斯-刘易斯时的一丝希望，并指出那个年代大分追赶罕见、澳队统治力强。片段唤起怀旧，交织场上戏剧与时间如何改写紧张记忆的争论。", "url": "https://x.com/i/trending/2112839270939480210", "category": "Sports", "topics": ["Cricket"], "updated_at": "2026-10-21T11:57:55.000Z"}, {"id": "2113307172050497543", "domain": "体育", "title_en": "NFL Paris Game Proceeds Despite French Unrest and Steelers Fan Event Cancellation", "title_zh": "法国动荡中 NFL 巴黎赛照常，钢人粉丝活动取消", "hook_en": "Amid violent protests and arrests in Paris, NFL Commissioner Roger Goodell voiced strong confidence in security for the Steelers-Saints showdown at Stade de France.", "hook_zh": "巴黎暴力抗议与逮捕之际，NFL 总裁古德尔对法兰西体育场钢人—圣徒大战安保表达高度信心。", "summary_en": "The NFL is pushing ahead with its first regular-season game in Paris on Sunday between the Pittsburgh Steelers and New Orleans Saints, despite recent clashes over cost-of-living and education issues that led to nearly 2,400 arrests and property damage. Goodell highlighted close coordination with U.S. and French officials, including Secretary of State Marco Rubio, and a 'very high' comfort level with the plans. The Steelers canceled their 'Steelers House' fan event in the tense Bastille area for safety, but the league's activities and the game at the distant Stade de France remain on track with heightened security.", "summary_zh": "NFL 周日仍将在巴黎举行常规赛首场法国赛，匹兹堡钢人对阵新奥尔良圣徒；近期生活成本与教育议题冲突已致近 2400 人被捕并造成财产损失。古德尔强调与美法官员（含国务卿鲁比奥）密切协调，对方案「舒适度非常高」。钢人取消气氛紧张的巴士底区「Steelers House」粉丝活动以确保安全，但联盟活动与较远的法兰西体育场比赛仍按计划加强安保推进。", "body_en": "NFL Paris Game Proceeds Despite French Unrest and Steelers Fan Event Cancellation.\n\nAmid violent protests and arrests in Paris, NFL Commissioner Roger Goodell voiced strong confidence in security for the Steelers-Saints showdown at Stade de France.\n\nThe NFL is pushing ahead with its first regular-season game in Paris on Sunday between the Pittsburgh Steelers and New Orleans Saints, despite recent clashes over cost-of-living and education issues that led to nearly 2,400 arrests and property damage. Goodell highlighted close coordination with U.S.\n\nand French officials, including Secretary of State Marco Rubio, and a 'very high' comfort level with the plans. The Steelers canceled their 'Steelers House' fan event in the tense Bastille area for safety, but the league's activities and the game at the distant Stade de France remain on track with heightened security.", "body_zh": "法国动荡中 NFL 巴黎赛照常，钢人粉丝活动取消。\n\n巴黎暴力抗议与逮捕之际，NFL 总裁古德尔对法兰西体育场钢人—圣徒大战安保表达高度信心。\n\nNFL 周日仍将在巴黎举行常规赛首场法国赛，匹兹堡钢人对阵新奥尔良圣徒；近期生活成本与教育议题冲突已致近 2400 人被捕并造成财产损失。\n\n古德尔强调与美法官员（含国务卿鲁比奥）密切协调，对方案「舒适度非常高」。钢人取消气氛紧张的巴士底区「Steelers House」粉丝活动以确保安全，但联盟活动与较远的法兰西体育场比赛仍按计划加强安保推进。", "url": "https://x.com/i/trending/2113307172050497543", "category": "Sports", "topics": ["American Football"], "updated_at": "2026-10-22T21:39:27.000Z"}, {"id": "2113335043133444271", "domain": "体育", "title_en": "Atlanta Dream Fans Swag Surf in WNBA Finals Win, Stirring Fan Debate", "title_zh": "亚特兰大梦想队决赛主场「人浪」引球迷争论", "hook_en": "Over 17,000 fans packed State Farm Arena, swag surfing in unison after the Atlanta Dream's dominant 97-71 victory in Game 3.", "hook_zh": "逾 1.7 万球迷挤满州立农场球馆，梦想队 97-71 大胜后齐做人浪。", "summary_en": "The Dream hosted the Golden State Valkyries on October 21 in a sold-out venue shifted from their usual arena to build a bigger home crowd, taking a 2-1 series lead behind strong play. The electric atmosphere sparked online arguments, with some calling Atlanta fans bandwagon supporters who only show up for wins, while locals defended their passion as genuine and typical of sports cities tired of losses. Atlanta's fan base blends transplants, college loyalty, and rising pro attendance during successful runs like this postseason fueled by stars such as Angel Reese. Game 4 heads to Atlanta on Saturday.", "summary_zh": "10 月 21 日梦想队为营造更大主场氛围，将与金州女武神的比赛改到售罄场馆，以强势表现取得系列赛 2-1 领先。热烈气氛引发网络争论：有人称亚特兰大球迷只会在赢球时出现的「跟风」；本地人则捍卫热情，称失败城市惯见的常态。亚特兰大球迷由外来人口、大学忠诚与职业赛出席共同构成，本季季后赛因安吉尔·里斯等球星升温。第四场周六仍在亚特兰大。", "body_en": "Atlanta Dream Fans Swag Surf in WNBA Finals Win, Stirring Fan Debate.\n\nOver 17,000 fans packed State Farm Arena, swag surfing in unison after the Atlanta Dream's dominant 97-71 victory in Game 3.\n\nThe Dream hosted the Golden State Valkyries on October 21 in a sold-out venue shifted from their usual arena to build a bigger home crowd, taking a 2-1 series lead behind strong play. The electric atmosphere sparked online arguments, with some calling Atlanta fans bandwagon supporters who only show up for wins, while locals defended their passion as genuine and typical of sports cities tired of losses.\n\nAtlanta's fan base blends transplants, college loyalty, and rising pro attendance during successful runs like this postseason fueled by stars such as Angel Reese. Game 4 heads to Atlanta on Saturday.", "body_zh": "亚特兰大梦想队决赛主场「人浪」引球迷争论。\n\n逾 1.7 万球迷挤满州立农场球馆，梦想队 97-71 大胜后齐做人浪。\n\n10 月 21 日梦想队为营造更大主场氛围，将与金州女武神的比赛改到售罄场馆，以强势表现取得系列赛 2-1 领先。热烈气氛引发网络争论：有人称亚特兰大球迷只会在赢球时出现的「跟风」；本地人则捍卫热情，称失败城市惯见的常态。\n\n亚特兰大球迷由外来人口、大学忠诚与职业赛出席共同构成，本季季后赛因安吉尔·里斯等球星升温。第四场周六仍在亚特兰大。", "url": "https://x.com/i/trending/2113335043133444271", "category": "Sports", "topics": ["Sports"], "updated_at": "2026-10-22T18:29:52.000Z"}, {"id": "2113163573044150452", "domain": "体育", "title_en": "Megan Schutt Suspended Two Matches Over Medication Breach", "title_zh": "梅根·舒特因用药规定违规停赛两场", "hook_en": "Megan Schutt, Australia's seasoned fast bowler, accepted a two-match ban after a one-off slip with prescription medication rules.", "hook_zh": "澳大利亚资深速球手梅根·舒特因一次性未遵守处方药规定，接受两场禁赛。", "summary_en": "Cricket Australia suspended the 33-year-old pacer for failing to follow Sports Science and Sports Medicine guidelines on prescription medication during an out-of-competition incident. The ban means she misses Australia's third T20I against New Zealand on Thursday at North Sydney Oval and the Adelaide Strikers' WBBL opener against Melbourne Stars on October 31. Authorities stressed it was not performance-enhancing, and Schutt apologized, saying she fully accepts the penalty and values the support received. Cricket Australia will continue supporting her while reinforcing guidelines for all players.", "summary_zh": "板球澳大利亚因她在赛外未遵循运动科学与运动医学关于处方药的指引而停赛。33 岁的她将缺席周四北悉尼椭圆形球场对新西兰的第三场 T20I，以及 10 月 31 日阿德莱德打击者队女板大联盟揭幕战对墨尔本星队。当局强调非提高成绩药物；舒特道歉并完全接受处罚，感谢支持。板球澳大利亚将继续支持她，同时强化全体球员指引。", "body_en": "Megan Schutt Suspended Two Matches Over Medication Breach.\n\nMegan Schutt, Australia's seasoned fast bowler, accepted a two-match ban after a one-off slip with prescription medication rules.\n\nCricket Australia suspended the 33-year-old pacer for failing to follow Sports Science and Sports Medicine guidelines on prescription medication during an out-of-competition incident. The ban means she misses Australia's third T20I against New Zealand on Thursday at North Sydney Oval and the Adelaide Strikers' WBBL opener against Melbourne Stars on October 31.\n\nAuthorities stressed it was not performance-enhancing, and Schutt apologized, saying she fully accepts the penalty and values the support received. Cricket Australia will continue supporting her while reinforcing guidelines for all players.", "body_zh": "梅根·舒特因用药规定违规停赛两场。\n\n澳大利亚资深速球手梅根·舒特因一次性未遵守处方药规定，接受两场禁赛。\n\n板球澳大利亚因她在赛外未遵循运动科学与运动医学关于处方药的指引而停赛。33 岁的她将缺席周四北悉尼椭圆形球场对新西兰的第三场 T20I，以及 10 月 31 日阿德莱德打击者队女板大联盟揭幕战对墨尔本星队。\n\n当局强调非提高成绩药物；舒特道歉并完全接受处罚，感谢支持。板球澳大利亚将继续支持她，同时强化全体球员指引。", "url": "https://x.com/i/trending/2113163573044150452", "category": "Sports", "topics": ["Cricket"], "updated_at": "2026-10-22T09:18:06.000Z"}, {"id": "2112563671352139931", "domain": "体育", "title_en": "Texas Flair Takes Over F1 Ahead of Austin Grand Prix", "title_zh": "奥斯汀大奖赛前 F1 车队刮起德州风", "hook_en": "As the sun sets over Circuit of the Americas, teams roll out cowboy-inspired liveries and suits that blend high-speed racing with Lone Star pride.", "hook_zh": "美国赛道日落时分，车队推出牛仔灵感涂装与赛车服，把高速竞速与孤星州骄傲融为一体。", "summary_en": "Formula 1 teams are celebrating the United States Grand Prix in Austin with special designs nodding to Texas culture, like Cadillac's western-wear livery featuring denim patterns, cacti, and Austin skyline details, plus Mercedes' custom cowboy boots and hats for George Russell and Kimi Antonelli. Ferrari, Aston Martin, and Red Bull also unveiled unique looks. On track, Antonelli leads the drivers’ championship by 102 points and could clinch the title this weekend with a win and weak results from rivals like Russell. Practice kicks off soon for a mix of racing drama and Texas energy.", "summary_zh": "一级方程式车队为奥斯汀美国大奖赛推出向德州文化致敬的特别设计：凯迪拉克西部风涂装含牛仔布纹、仙人掌与奥斯汀天际线；梅赛德斯为拉塞尔与安东内利定制牛仔靴与帽。法拉利、阿斯顿马丁与红牛亦亮相独特造型。积分榜上安东内利领先车手榜 102 分，本周末若夺冠且拉塞尔等对手成绩疲软即可锁定冠军。练习赛即将开始，竞速与德州氛围并至。", "body_en": "Texas Flair Takes Over F1 Ahead of Austin Grand Prix.\n\nAs the sun sets over Circuit of the Americas, teams roll out cowboy-inspired liveries and suits that blend high-speed racing with Lone Star pride.\n\nFormula 1 teams are celebrating the United States Grand Prix in Austin with special designs nodding to Texas culture, like Cadillac's western-wear livery featuring denim patterns, cacti, and Austin skyline details, plus Mercedes' custom cowboy boots and hats for George Russell and Kimi Antonelli. Ferrari, Aston Martin, and Red Bull also unveiled unique looks.\n\nOn track, Antonelli leads the drivers’ championship by 102 points and could clinch the title this weekend with a win and weak results from rivals like Russell. Practice kicks off soon for a mix of racing drama and Texas energy.", "body_zh": "奥斯汀大奖赛前 F1 车队刮起德州风。\n\n美国赛道日落时分，车队推出牛仔灵感涂装与赛车服，把高速竞速与孤星州骄傲融为一体。\n\n一级方程式车队为奥斯汀美国大奖赛推出向德州文化致敬的特别设计：凯迪拉克西部风涂装含牛仔布纹、仙人掌与奥斯汀天际线；梅赛德斯为拉塞尔与安东内利定制牛仔靴与帽。法拉利、阿斯顿马丁与红牛亦亮相独特造型。\n\n积分榜上安东内利领先车手榜 102 分，本周末若夺冠且拉塞尔等对手成绩疲软即可锁定冠军。练习赛即将开始，竞速与德州氛围并至。", "url": "https://x.com/i/trending/2112563671352139931", "category": "Sports", "topics": ["Formula 1"], "updated_at": "2026-10-22T10:21:08.000Z"}, {"id": "2112998138847912273", "domain": "体育", "title_en": "Analyst Josh Pate Calls College Football Not a Tournament Sport Amid 24-Team Playoff Push", "title_zh": "分析师称大学橄榄球不是锦标赛运动，反对 24 队季后赛", "hook_en": "ESPN analyst Josh Pate stirred the pot on the Rich Eisen Show, insisting college football's magic lies in its grueling regular season, not a bloated playoff.", "hook_zh": "ESPN 分析师 Josh Pate 在 Rich Eisen 节目上坚持：大学橄榄球魅力在残酷常规赛，而非膨胀的季后赛。", "summary_en": "Pate argued that expanding to a 24-team playoff in 2027 would dilute the urgency of regular-season rivalries and key games, turning the sport more like basketball's tournament model. A survey of over 6,300 fans backed this view, with 71 percent saying it would make them less excited for the regular season and 81.7 percent opposing the size. While some fans and analysts favor more teams and extra meaningful matchups, critics worry it risks making the season just a long qualifier, highlighting the sport's core tension between its demanding schedule and postseason access.", "summary_zh": "Pate 认为 2027 年扩至 24 队季后赛会稀释常规赛宿敌对决与关键场次的紧迫感，使这项运动更像篮球锦标赛模式。逾 6300 名球迷调查支持此见：71% 称会降低对常规赛兴奋度，81.7% 反对如此规模。虽有球迷与分析师欢迎更多球队与有意义场次，批评者担心赛季沦为漫长资格赛，凸显苛刻赛程与季后赛准入之间的核心张力。", "body_en": "Analyst Josh Pate Calls College Football Not a Tournament Sport Amid 24-Team Playoff Push.\n\nESPN analyst Josh Pate stirred the pot on the Rich Eisen Show, insisting college football's magic lies in its grueling regular season, not a bloated playoff.\n\nPate argued that expanding to a 24-team playoff in 2027 would dilute the urgency of regular-season rivalries and key games, turning the sport more like basketball's tournament model.\n\nA survey of over 6,300 fans backed this view, with 71 percent saying it would make them less excited for the regular season and 81.7 percent opposing the size. While some fans and analysts favor more teams and extra meaningful matchups, critics worry it risks making the season just a long qualifier, highlighting the sport's core tension between its demanding schedule and postseason access.", "body_zh": "分析师称大学橄榄球不是锦标赛运动，反对 24 队季后赛。\n\nESPN 分析师 Josh Pate 在 Rich Eisen 节目上坚持：大学橄榄球魅力在残酷常规赛，而非膨胀的季后赛。\n\nPate 认为 2027 年扩至 24 队季后赛会稀释常规赛宿敌对决与关键场次的紧迫感，使这项运动更像篮球锦标赛模式。\n\n逾 6300 名球迷调查支持此见：71% 称会降低对常规赛兴奋度，81.7% 反对如此规模。虽有球迷与分析师欢迎更多球队与有意义场次，批评者担心赛季沦为漫长资格赛，凸显苛刻赛程与季后赛准入之间的核心张力。", "url": "https://x.com/i/trending/2112998138847912273", "category": "Sports", "topics": ["NCAA Football"], "updated_at": "2026-10-22T13:18:27.000Z"}, {"id": "2113255303315939387", "domain": "体育", "title_en": "Nintendo Switch Sports Resort Launches on Switch 2", "title_zh": "《任天堂 Switch 运动 度假胜地》登陆 Switch 2", "hook_en": "Friends are grabbing Joy-Con 2 controllers to swing rackets, shred skateboards, and even thumb wrestle on sunny Wuhu Island.", "hook_zh": "好友拿起 Joy-Con 2，在阳光武瑚岛上挥拍、滑板，甚至掰手腕。", "summary_en": "Nintendo Switch Sports Resort hits the Switch 2 today with 12 sports, blending classics like tennis and bowling with new additions such as skateboarding and thumb wrestling. Players enjoy intuitive motion controls in solo, local, and online modes, plus an explorable island packed with collectibles and changing times of day. A bundle with the console and three months of Nintendo Switch Online costs $529.99, while the game runs $49.99 digital or $59.99 physical. Early players share clips of archery and power cruising, praising polished visuals and family-friendly fun.", "summary_zh": "《Nintendo Switch Sports Resort》今日登陆 Switch 2，含 12 项运动，既有网球、保龄球等经典，也有滑板与拇指摔跤等新项目。玩家可用直觉体感在单人、本地与在线模式游玩，还可探索满是收集品、昼夜变化的岛屿。主机捆绑含三个月 Nintendo Switch Online 售价 529.99 美元，游戏数字版 49.99、实体 59.99 美元。早期玩家分享射箭与动力巡航片段，称赞画面与家庭友好乐趣。", "body_en": "Nintendo Switch Sports Resort Launches on Switch 2.\n\nFriends are grabbing Joy-Con 2 controllers to swing rackets, shred skateboards, and even thumb wrestle on sunny Wuhu Island.\n\nNintendo Switch Sports Resort hits the Switch 2 today with 12 sports, blending classics like tennis and bowling with new additions such as skateboarding and thumb wrestling. Players enjoy intuitive motion controls in solo, local, and online modes, plus an explorable island packed with collectibles and changing times of day.\n\nA bundle with the console and three months of Nintendo Switch Online costs $529.99, while the game runs $49.99 digital or $59.99 physical. Early players share clips of archery and power cruising, praising polished visuals and family-friendly fun.", "body_zh": "《任天堂 Switch 运动 度假胜地》登陆 Switch 2。\n\n好友拿起 Joy-Con 2，在阳光武瑚岛上挥拍、滑板，甚至掰手腕。\n\n《Nintendo Switch Sports Resort》今日登陆 Switch 2，含 12 项运动，既有网球、保龄球等经典，也有滑板与拇指摔跤等新项目。玩家可用直觉体感在单人、本地与在线模式游玩，还可探索满是收集品、昼夜变化的岛屿。\n\n主机捆绑含三个月 Nintendo Switch Online 售价 529.99 美元，游戏数字版 49.99、实体 59.99 美元。早期玩家分享射箭与动力巡航片段，称赞画面与家庭友好乐趣。", "url": "https://x.com/i/trending/2113255303315939387", "category": "Entertainment", "topics": ["Gaming"], "updated_at": "2026-10-22T21:36:01.000Z"}, {"id": "2113335031775264942", "domain": "体育", "title_en": "Qatar to Host Final Three Matches of FIFA Intercontinental Cup in December", "title_zh": "卡塔尔将承办国际足联洲际杯最后三场", "hook_en": "Qatar's stadiums will light up again this December as the world's top clubs battle for intercontinental glory. Fans from South Africa are already buzzing with dreams of trophy lifts.", "hook_zh": "卡塔尔球场 12 月再亮灯，世界顶级俱乐部争夺洲际荣耀；南非球迷已梦想举杯。", "summary_en": "The decisive stages of the FIFA Intercontinental Cup return to Doha for the third year in a row, with matches set for December 9, 12, and 16. It kicks off with a Derby of the Americas between Toluca FC and the CONMEBOL champion at Jassim bin Hamad Stadium, followed by the winner facing South Africa's Mamelodi Sundowns in the Challenger Cup. Paris Saint-Germain, the defending European champions, awaits the victor in the final at Ahmad bin Ali Stadium. Sundowns fans are thrilled after their 2-1 win over Al Ahli, with some joking that PSG is dreading the matchup.", "summary_zh": "国际足联洲际杯决定性阶段连续第三年回到多哈，比赛定于 12 月 9、12、16 日。先是托卢卡对南美冠军的美洲德比，在贾西姆·本·哈马德球场；胜者再战南非马梅洛迪日落队争夺挑战者杯。卫冕欧冠巴黎圣日耳曼在艾哈迈德·本·阿里球场等待决赛对手。日落队球迷在 2-1 击败艾阿里后热情高涨，有人调侃巴黎惧怕对决。", "body_en": "Qatar to Host Final Three Matches of FIFA Intercontinental Cup in December.\n\nQatar's stadiums will light up again this December as the world's top clubs battle for intercontinental glory. Fans from South Africa are already buzzing with dreams of trophy lifts.\n\nThe decisive stages of the FIFA Intercontinental Cup return to Doha for the third year in a row, with matches set for December 9, 12, and 16. It kicks off with a Derby of the Americas between Toluca FC and the CONMEBOL champion at Jassim bin Hamad Stadium, followed by the winner facing South Africa's Mamelodi Sundowns in the Challenger Cup.\n\nParis Saint-Germain, the defending European champions, awaits the victor in the final at Ahmad bin Ali Stadium. Sundowns fans are thrilled after their 2-1 win over Al Ahli, with some joking that PSG is dreading the matchup.", "body_zh": "卡塔尔将承办国际足联洲际杯最后三场。\n\n卡塔尔球场 12 月再亮灯，世界顶级俱乐部争夺洲际荣耀；南非球迷已梦想举杯。\n\n国际足联洲际杯决定性阶段连续第三年回到多哈，比赛定于 12 月 9、12、16 日。先是托卢卡对南美冠军的美洲德比，在贾西姆·本·哈马德球场；胜者再战南非马梅洛迪日落队争夺挑战者杯。\n\n卫冕欧冠巴黎圣日耳曼在艾哈迈德·本·阿里球场等待决赛对手。日落队球迷在 2-1 击败艾阿里后热情高涨，有人调侃巴黎惧怕对决。", "url": "https://x.com/i/trending/2113335031775264942", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-22T18:28:12.000Z"}, {"id": "2113298162085416990", "domain": "娱乐", "title_en": "CBS Local Stations to Feature DraftKings Sponsorship in Election Coverage", "title_zh": "CBS 地方台选举报道将植入 DraftKings 赞助", "hook_en": "As election night approaches, CBS's local stations are set to include DraftKings sponsorship in their newscasts, stirring unease among some executives and viewers alike.", "hook_zh": "选举夜临近，CBS 地方台新闻拟加入 DraftKings 赞助，令部分高管与观众不安。", "summary_en": "The deal, running from October 26 through election night, brings four sponsored segments daily on CBS owned-and-operated stations nationwide, with DraftKings branding even on seating in studio environments. CBS executives raised concerns internally, but the company proceeded, insisting the partnership stays purely commercial and won't touch journalism or editorial choices—no odds or betting data will appear. Online reactions ranged from dismay over gambling apps funding news to views of it as necessary revenue, amid broader talks on betting's role in election coverage.", "summary_zh": "合作自 10 月 26 日持续至选举夜，在全国 CBS 自有与运营电视台每日植入四段赞助内容，演播室座椅亦可出现 DraftKings 品牌。CBS 内部有高管担忧，但公司推进，坚称纯属商业、不触及新闻与编辑——不会出现赔率或博彩数据。网络反应从不满博彩 App 资助新闻，到视作必要收入不等，并延伸到博彩在选举报道中角色的讨论。", "body_en": "CBS Local Stations to Feature DraftKings Sponsorship in Election Coverage.\n\nAs election night approaches, CBS's local stations are set to include DraftKings sponsorship in their newscasts, stirring unease among some executives and viewers alike.\n\nThe deal, running from October 26 through election night, brings four sponsored segments daily on CBS owned-and-operated stations nationwide, with DraftKings branding even on seating in studio environments.\n\nCBS executives raised concerns internally, but the company proceeded, insisting the partnership stays purely commercial and won't touch journalism or editorial choices—no odds or betting data will appear. Online reactions ranged from dismay over gambling apps funding news to views of it as necessary revenue, amid broader talks on betting's role in election coverage.", "body_zh": "CBS 地方台选举报道将植入 DraftKings 赞助。\n\n选举夜临近，CBS 地方台新闻拟加入 DraftKings 赞助，令部分高管与观众不安。\n\n合作自 10 月 26 日持续至选举夜，在全国 CBS 自有与运营电视台每日植入四段赞助内容，演播室座椅亦可出现 DraftKings 品牌。\n\nCBS 内部有高管担忧，但公司推进，坚称纯属商业、不触及新闻与编辑——不会出现赔率或博彩数据。网络反应从不满博彩 App 资助新闻，到视作必要收入不等，并延伸到博彩在选举报道中角色的讨论。", "url": "https://x.com/i/trending/2113298162085416990", "category": "News", "topics": ["Elections"], "updated_at": "2026-10-22T16:05:20.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录。\n\n从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。\n\n印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。\n\n前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112675329613672597", "domain": "娱乐", "title_en": "YouTube Hits Record 15.8% Share of U.S. TV Viewing Time", "title_zh": "YouTube 占美国电视观看时长份额达纪录 15.8%", "hook_en": "YouTube just set a new high, grabbing 15.8% of all U.S. TV time in August—twice Netflix's share. It's becoming the screen Americans turn to most.", "hook_zh": "YouTube 创下新高，8 月占据美国全部电视时长的 15.8%——约为 Netflix 两倍，成为美国人最常转向的屏幕。", "summary_en": "Nielsen's August 2026 report shows YouTube reaching a platform record of 15.8% viewing share among people 2 and older, outpacing Netflix at 7.7% and every other individual streamer. The platform grew 6% that month, driven by strong engagement from adults 50 and older, even as total TV usage dipped after the World Cup. Observers like investor Chamath Palihapitiya point to daily viewing habits and lower content costs, while creator Joseph Carlson notes YouTube paid creators more than Netflix spent on originals last year. This steady rise since 2024 highlights YouTube's broad appeal with clips, long videos, music, and live content.", "summary_zh": "尼尔森 2026 年 8 月报告显示，YouTube 在 2 岁及以上人群中观看份额达平台纪录 15.8%，超过 Netflix 的 7.7% 及其他单一流媒体。当月增长 6%，50 岁及以上成人参与强劲，尽管世界杯后整体电视使用下降。投资者 Chamath 等指向日常观看习惯与较低内容成本；创作者 Joseph Carlson 指出 YouTube 付给创作者的钱超过 Netflix 去年原创开支。自 2024 年以来的稳步上升凸显短视频、长视频、音乐与直播的广泛吸引力。", "body_en": "YouTube Hits Record 15.8% Share of U.S. TV Viewing Time.\n\nYouTube just set a new high, grabbing 15.8% of all U.S. TV time in August—twice Netflix's share. It's becoming the screen Americans turn to most.\n\nNielsen's August 2026 report shows YouTube reaching a platform record of 15.8% viewing share among people 2 and older, outpacing Netflix at 7.7% and every other individual streamer. The platform grew 6% that month, driven by strong engagement from adults 50 and older, even as total TV usage dipped after the World Cup.\n\nObservers like investor Chamath Palihapitiya point to daily viewing habits and lower content costs, while creator Joseph Carlson notes YouTube paid creators more than Netflix spent on originals last year. This steady rise since 2024 highlights YouTube's broad appeal with clips, long videos, music, and live content.", "body_zh": "YouTube 占美国电视观看时长份额达纪录 15.8%。\n\nYouTube 创下新高，8 月占据美国全部电视时长的 15.8%——约为 Netflix 两倍，成为美国人最常转向的屏幕。\n\n尼尔森 2026 年 8 月报告显示，YouTube 在 2 岁及以上人群中观看份额达平台纪录 15.8%，超过 Netflix 的 7.7% 及其他单一流媒体。当月增长 6%，50 岁及以上成人参与强劲，尽管世界杯后整体电视使用下降。\n\n投资者 Chamath 等指向日常观看习惯与较低内容成本；创作者 Joseph Carlson 指出 YouTube 付给创作者的钱超过 Netflix 去年原创开支。自 2024 年以来的稳步上升凸显短视频、长视频、音乐与直播的广泛吸引力。", "url": "https://x.com/i/trending/2112675329613672597", "category": "News", "topics": ["Streaming"], "updated_at": "2026-10-22T21:38:24.000Z"}, {"id": "2112840787054743961", "domain": "娱乐", "title_en": "Moonlight Marks 10 Years with Netflix Debut and 4K Return", "title_zh": "Moonlight标志着美国首次亮相和奥斯卡辉煌10周年", "hook_en": "A decade after its quiet premiere, Moonlight's tender beach scenes and raw family moments are pulling fans back in for fresh viewings.", "hook_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。", "summary_en": "Barry Jenkins's intimate drama follows Chiron, a young Black man in Miami navigating identity, sexuality, and love across three life stages, portrayed by Alex R. Hibbert, Ashton Sanders, and Trevante Rhodes. Mahershala Ali's Oscar-winning role as mentor Juan anchors the story that swept three Academy Awards, including Best Picture amid the infamous envelope mix-up. This week, Netflix added it to its U.S. lineup, A24 shared Jenkins's anniversary reflections, and theaters launched limited 4K remaster screenings, prompting fans to celebrate its enduring impact on Black queer storytelling.", "summary_zh": "这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。 Mahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "body_en": "Ten years ago today, Barry Jenkins' Moonlight quietly arrived in U.S. theaters, forever changing conversations about identity and love through its tender gaze on a young man's life in Miami.\n\nReleased on October 21, 2016, by A24, the film follows Chiron from childhood to adulthood across three chapters, earning three Oscars including Best Picture as the first with an all-Black cast and LGBT theme. Standout performances by Mahershala Ali, Naomie Harris, Trevante Rhodes, Ashton Sanders, and Jharrel Jerome, paired with luminous cinematography and Nicholas Britell's score, turned its $1.5 million budget into $67 million worldwide and lasting praise.\n\nThis week, Netflix added it to its U.S. library while a 4K remaster returned to theaters, as fans share personal stories of its themes of vulnerability and self-acceptance.", "body_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。\n\n这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。\n\nMahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "url": "https://x.com/i/trending/2112840787054743961", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-22T02:29:50.000Z"}, {"id": "2113014995948831070", "domain": "娱乐", "title_en": "Tom Cruise to Receive 52nd AFI Life Achievement Award in 2027", "title_zh": "汤姆·克鲁斯将获美国电影学院终身成就奖", "hook_en": "Tom Cruise, the star behind Mission: Impossible and Top Gun, is set for his biggest career honor yet. The American Film Institute calls him a global icon who unites audiences through film.", "hook_zh": "数十年来让观众肾上腺素飙升的汤姆·克鲁斯，将在星光晚宴上接受 AFI 最高生涯荣誉。", "summary_en": "The AFI announced on October 21 that Cruise will get its top career honor at a gala on April 24, 2027, at the Dolby Theatre in Hollywood. AFI Board Chair Kathleen Kennedy praised his extraordinary commitment as an actor and producer, noting his films have grossed nearly $13 billion worldwide. Cruise, 64, has Oscar nods for Born on the Fourth of July, Jerry Maguire, Magnolia, and Top Gun: Maverick, plus an Honorary Oscar in 2025; he's currently in Digger and prepping Days of Thunder 2. The event supports AFI's arts and education programs, following Eddie Murphy as last year's honoree.", "summary_zh": "AFI 10 月 21 日宣布，克鲁斯将于 2027 年 4 月 24 日在洛杉矶杜比剧院领取第 52 届终身成就奖。董事会主席凯瑟琳·肯尼迪称其为全球偶像，对电影的热情凝聚观众，并担任美国电影大使。64 岁的他作品全球票房近 130 亿美元，从《危险生意》到《碟中谍》《壮志凌云：独行侠》，三获奥斯卡演技提名并于 2025 年获荣誉奖。该奖上届得主为艾迪·墨菲，亦支持 AFI 教育与保存工作。", "body_en": "Tom Cruise to Receive AFI Life Achievement Award.\n\nTom Cruise, the star who's thrilled audiences for decades, will be honored with the American Film Institute's top career award at a star-studded gala.\n\nThe AFI announced on October 21, 2026, that Cruise will receive its 52nd Life Achievement Award on April 24, 2027, at the Dolby Theatre in Los Angeles. AFI Board chair Kathleen Kennedy called him a global icon whose passion for movies brings people together and serves as an ambassador for American film.\n\nAt 64, Cruise has starred in films grossing nearly $13 billion worldwide, from Risky Business to Mission: Impossible and Top Gun: Maverick, earning three Oscar acting nods and an honorary Oscar in 2025. The award follows Eddie Murphy as last year's honoree and supports AFI's education and preservation work.", "body_zh": "汤姆·克鲁斯将获美国电影学院终身成就奖。\n\n数十年来让观众肾上腺素飙升的汤姆·克鲁斯，将在星光晚宴上接受 AFI 最高生涯荣誉。\n\nAFI 10 月 21 日宣布，克鲁斯将于 2027 年 4 月 24 日在洛杉矶杜比剧院领取第 52 届终身成就奖。董事会主席凯瑟琳·肯尼迪称其为全球偶像，对电影的热情凝聚观众，并担任美国电影大使。\n\n64 岁的他作品全球票房近 130 亿美元，从《危险生意》到《碟中谍》《壮志凌云：独行侠》，三获奥斯卡演技提名并于 2025 年获荣誉奖。该奖上届得主为艾迪·墨菲，亦支持 AFI 教育与保存工作。", "url": "https://x.com/i/trending/2113014995948831070", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-22T00:11:50.000Z"}, {"id": "2112630069361570032", "domain": "娱乐", "title_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories", "title_zh": "金球奖将迈克尔·杰克逊的传记片列入戏剧类", "hook_en": "Jaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.", "hook_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。", "summary_en": "Lionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "summary_zh": "Lionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。 球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "body_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories.\n\nJaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.\n\nLionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot.\n\nFans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "body_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。\n\nLionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。\n\n这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "url": "https://x.com/i/trending/2112630069361570032", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:48:00.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier's Nature-Inspired Event in Singapore", "title_zh": "泰星玲玲·邝亮相新加坡 Cartier「Into the Wild」", "hook_en": "Thai actress Lingling Kwong glided through glowing gardens in dazzling high jewelry, blending elegance with the wild spirit of Cartier's immersive celebration.", "hook_zh": "玲玲·邝走进新加坡如丛林般的花园会场，黑色亮片礼裙与戏剧性手套在灯光下闪烁，动物主题珠宝吸睛。", "summary_en": "At Cartier’s “Into the Wild” event in Rochester Park, Kwong turned heads in black gowns paired with onyx, sapphire, and diamond pieces from the Faune & Flore collection. The gathering featured artisan demos, dance, music, and explorations of nature-themed jewelry, watches, and more across heritage houses and lush grounds. Soon after, she switched to biker chic for her Always Wonder brand, posing in a leather vest on a motorcycle to promote the Joy Ride collection. Her versatile style, from red-carpet grace to adventurous edge, captivated fans everywhere.", "summary_zh": "泰国女演员玲玲·邝以特邀嘉宾身份出席罗彻斯特公园 Cartier「Into the Wild」，身着 Faune & Flore 系列亮片、花卉细节与标志性图案造型。活动将遗产宅邸与花园变为沉浸空间，含光影装置、匠人演示、舞蹈，并呈现珠宝、腕表、香氛与皮具。粉丝与媒体称赞其优雅风范；公众可通过预约于 10 月 25 日前在 17 Rochester Park 体验。", "body_en": "Thai Actress Lingling Kwong Shines at Cartier’s Into the Wild Event in Singapore.\n\nLingling Kwong stepped into a lush garden paradise in Singapore, her shimmering black sequined gown and dramatic gloves catching every light amid animal-inspired jewelry.\n\nThai actress Lingling Kwong attended Cartier’s “Into the Wild” celebration at Rochester Park as a special guest, wearing striking ensembles from the Faune & Flore collection that blended sequins, floral details, and signature motifs.\n\nThe event transformed heritage houses and gardens into immersive spaces with illuminated designs, artisan demos, dance performances, and sensory highlights of Cartier’s jewelry, watches, fragrances, and leather goods. Fans and media praised her elegant presence, with the experience open to the public through October 25 at 17 Rochester Park via advance registration.", "body_zh": "泰星玲玲·邝亮相新加坡 Cartier「Into the Wild」。\n\n玲玲·邝走进新加坡如丛林般的花园会场，黑色亮片礼裙与戏剧性手套在灯光下闪烁，动物主题珠宝吸睛。\n\n泰国女演员玲玲·邝以特邀嘉宾身份出席罗彻斯特公园 Cartier「Into the Wild」，身着 Faune & Flore 系列亮片、花卉细节与标志性图案造型。\n\n活动将遗产宅邸与花园变为沉浸空间，含光影装置、匠人演示、舞蹈，并呈现珠宝、腕表、香氛与皮具。粉丝与媒体称赞其优雅风范；公众可通过预约于 10 月 25 日前在 17 Rochester Park 体验。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-22T17:03:32.000Z"}, {"id": "2112352804241285515", "domain": "娱乐", "title_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music", "title_zh": "德维恩·约翰逊（ Dwayne Johnson ）变身为蜥蜴音乐的老鸡人", "hook_en": "Dwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.", "hook_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。", "summary_en": "Johnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV. Set photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "summary_zh": "约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "body_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music.\n\nDwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.\n\nJohnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV.\n\nSet photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "body_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。\n\n约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:07:08.000Z"}, {"id": "2112958295611003176", "domain": "娱乐", "title_en": "Backlash Hits Greta Gerwig's Narnia Adaptation After Trailer", "title_zh": "格蕾塔·葛韦格版《纳尼亚》预告引粉丝反弹", "hook_en": "Fans lit up social media when Netflix's trailer for Greta Gerwig's Narnia take dropped this month, zeroing in on her direction of the classic Christian tale.", "hook_zh": "Netflix 本月放出葛韦格执导《纳尼亚》预告后，社交平台聚焦她如何改编这部经典基督教故事。", "summary_en": "The film, *Narnia: The Magician’s Nephew*, brings C.S. Lewis’s 1955 origin story to IMAX theaters on February 12, 2027, before Netflix streaming on April 2, with a $280 million budget and stars like Daniel Craig, Emma Mackey, Carey Mulligan, and Meryl Streep voicing Aslan. Online critics call it a mismatch for Gerwig's style from *Barbie* and *Little Women*, slamming choices like rock opera vibes with Led Zeppelin, Streep's casting, gender-swapped elements, and anti-patriarchy framing amid rumors of test screening issues and executive clashes. While some defend the bold risks and emotional core shown in previews, others fear it strays from the original allegory's spirit.", "summary_zh": "影片《纳尼亚：魔法师的外甥》改编自 C.S. 刘易斯 1955 年起源故事，2027 年 2 月 12 日登陆 IMAX，4 月 2 日上线 Netflix，预算约 2.8 亿美元，丹尼尔·克雷格、艾玛·麦基、凯瑞·穆里根主演，梅丽尔·斯特里普为阿斯兰配音。网上批评其风格与《芭比》《小妇人》错位，抨击齐柏林飞艇摇滚歌剧感、斯特里普选角、性别置换与反父权框架，并传试映与高管冲突。亦有人捍卫大胆冒险与预告中的情感内核，担心偏离原作寓言精神。", "body_en": "Backlash Hits Greta Gerwig's Narnia Adaptation After Trailer.\n\nFans lit up social media when Netflix's trailer for Greta Gerwig's Narnia take dropped this month, zeroing in on her direction of the classic Christian tale.\n\nThe film, *Narnia: The Magician’s Nephew*, brings C.S. Lewis’s 1955 origin story to IMAX theaters on February 12, 2027, before Netflix streaming on April 2, with a $280 million budget and stars like Daniel Craig, Emma Mackey, Carey Mulligan, and Meryl Streep voicing Aslan.\n\nOnline critics call it a mismatch for Gerwig's style from *Barbie* and *Little Women*, slamming choices like rock opera vibes with Led Zeppelin, Streep's casting, gender-swapped elements, and anti-patriarchy framing amid rumors of test screening issues and executive clashes. While some defend the bold risks and emotional core shown in previews, others fear it strays from the original allegory's spirit.", "body_zh": "格蕾塔·葛韦格版《纳尼亚》预告引粉丝反弹。\n\nNetflix 本月放出葛韦格执导《纳尼亚》预告后，社交平台聚焦她如何改编这部经典基督教故事。\n\n影片《纳尼亚：魔法师的外甥》改编自 C.S. 刘易斯 1955 年起源故事，2027 年 2 月 12 日登陆 IMAX，4 月 2 日上线 Netflix，预算约 2.8 亿美元，丹尼尔·克雷格、艾玛·麦基、凯瑞·穆里根主演，梅丽尔·斯特里普为阿斯兰配音。\n\n网上批评其风格与《芭比》《小妇人》错位，抨击齐柏林飞艇摇滚歌剧感、斯特里普选角、性别置换与反父权框架，并传试映与高管冲突。亦有人捍卫大胆冒险与预告中的情感内核，担心偏离原作寓言精神。", "url": "https://x.com/i/trending/2112958295611003176", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:32:14.000Z"}, {"id": "2113222568811643223", "domain": "娱乐", "title_en": "BTS Delivers Epic Full-Group Concert in Argentina", "title_zh": "BTS 在阿根廷献上史诗级全员演唱会", "hook_en": "Jungkook gripped his pink microphone amid swirling lights and smoke, connecting instantly with the roaring crowd. Fans captured every unforgettable moment from BTS's first complete performance in the country.", "hook_zh": "柾国握着粉色麦克风，在灯光与烟雾中瞬间点燃全场；粉丝记录下 BTS 该国首场完整演出的难忘瞬间。", "summary_en": "BTS performed at Estadio Único de La Plata on October 21, marking their first full-group show in Argentina as part of the ARIRANG World Tour supporting their new album. The sold-out concert featured a 360-degree stage, extended walkways, massive screens, and dramatic lighting that brought the seven members close to thousands of ARMYs waving light sticks. Nearly three hours of precise choreography, live vocals, and hits from the album mixed with fan favorites created an electric atmosphere, with fans sharing clips of standout outfits like Jimin's yellow ensemble and Taehyung's charismatic energy. More shows follow on October 23 and 24 before heading to São Paulo.", "summary_zh": "BTS 10 月 21 日在拉普拉塔唯一体育场演出，作为 ARIRANG 世界巡演暨新专辑宣传的阿根廷首场全员秀。售罄演唱会设 360 度舞台、延伸通道、巨型屏幕与戏剧灯光，七名成员贴近成千上万挥动应援棒的 ARMY。近三小时精准编舞、现场演唱与专辑曲加经典曲目营造电光氛围；粉丝分享智旻黄衣、泰亨魅力等造型片段。10 月 23、24 日还有场次，随后前往圣保罗。", "body_en": "BTS Delivers Epic Full-Group Concert in Argentina.\n\nJungkook gripped his pink microphone amid swirling lights and smoke, connecting instantly with the roaring crowd. Fans captured every unforgettable moment from BTS's first complete performance in the country.\n\nBTS performed at Estadio Único de La Plata on October 21, marking their first full-group show in Argentina as part of the ARIRANG World Tour supporting their new album. The sold-out concert featured a 360-degree stage, extended walkways, massive screens, and dramatic lighting that brought the seven members close to thousands of ARMYs waving light sticks.\n\nNearly three hours of precise choreography, live vocals, and hits from the album mixed with fan favorites created an electric atmosphere, with fans sharing clips of standout outfits like Jimin's yellow ensemble and Taehyung's charismatic energy. More shows follow on October 23 and 24 before heading to São Paulo.", "body_zh": "BTS 在阿根廷献上史诗级全员演唱会。\n\n柾国握着粉色麦克风，在灯光与烟雾中瞬间点燃全场；粉丝记录下 BTS 该国首场完整演出的难忘瞬间。\n\nBTS 10 月 21 日在拉普拉塔唯一体育场演出，作为 ARIRANG 世界巡演暨新专辑宣传的阿根廷首场全员秀。售罄演唱会设 360 度舞台、延伸通道、巨型屏幕与戏剧灯光，七名成员贴近成千上万挥动应援棒的 ARMY。\n\n近三小时精准编舞、现场演唱与专辑曲加经典曲目营造电光氛围；粉丝分享智旻黄衣、泰亨魅力等造型片段。10 月 23、24 日还有场次，随后前往圣保罗。", "url": "https://x.com/i/trending/2113222568811643223", "category": "Entertainment", "topics": ["K-pop"], "updated_at": "2026-10-22T11:02:33.000Z"}, {"id": "2112545585349738844", "domain": "娱乐", "title_en": "LISA's 'Press Play' EP Drops October 23 with PlayStation Tie-In", "title_zh": "LISA 携手 PlayStation 推出定制手柄并预告新歌", "hook_en": "Fans are buzzing as LISA's team shares the 'Tarantino' teaser, just hours from the full EP release. The track already turned heads in a PlayStation ad.", "hook_zh": "LISA 的眼神与标志性星星出现在限量版 PlayStation 手柄上，音乐与游戏跨界联名。", "summary_en": "LISA's six-track EP 'Press Play' arrives October 23 via Lloud and RCA Records, featuring songs like 'SaWaDiKa,' 'V12,' 'Cobra,' 'Tarantino,' 'Cut U Off,' and 'Sweat.' It pairs with a PlayStation partnership, including a limited-edition DualSense controller with LISA's signature bangs, eyes, stars, and 'LL' on a Chroma Pearl finish, available October 30. Early listening parties drew praise for the bold, empowering tracks like 'Cobra' and 'Sweat,' with fans loving the high-energy vibe and sharp production.", "summary_zh": "BLACKPINK 成员 LISA 与 PlayStation 合作推出定制 DualSense 手柄，采用她偏爱的 Chroma Pearl 配色，带「LL」字母、星星以及触控板上网眼与刘海插画。手柄定价 84.99 美元并配周边，10 月底上市前开放预购，恰逢其六首歌 EP《Press Play》于 10 月 23 日发行。她于 10 月 21 日以短片预告电影感单曲，片段已出现在 PlayStation 广告中，粉丝称歌词赋能且与游戏契合；LISA 称联名是通过音乐与时尚放松的有趣方式。", "body_en": "LISA Teams with PlayStation for Custom Controller and 'Tarantura' Teaser.\n\nLISA's eyes and signature stars now grace a limited-edition PlayStation controller, blending her music world with gaming vibes just before her new EP drops.\n\nBLACKPINK's LISA partnered with PlayStation on a custom DualSense controller in her favorite Chroma Pearl color, featuring her \"LL\" lettering, stars, and a touchpad illustration of her eyes and bangs.\n\nThe controller, priced at $84.99 with matching merch, is available for pre-order ahead of a late October launch, timed with her six-track EP \"Press Play\" releasing October 23. She teased cinematic single \"Tarantino\" via music video clip on October 21, with a snippet already in a PlayStation ad that fans love for its empowering lyrics and gaming fit; LISA calls the collab a fun way to unwind through her music and fashion passions.", "body_zh": "LISA 携手 PlayStation 推出定制手柄并预告新歌。\n\nLISA 的眼神与标志性星星出现在限量版 PlayStation 手柄上，音乐与游戏跨界联名。\n\nBLACKPINK 成员 LISA 与 PlayStation 合作推出定制 DualSense 手柄，采用她偏爱的 Chroma Pearl 配色，带「LL」字母、星星以及触控板上网眼与刘海插画。\n\n手柄定价 84.99 美元并配周边，10 月底上市前开放预购，恰逢其六首歌 EP《Press Play》于 10 月 23 日发行。她于 10 月 21 日以短片预告电影感单曲，片段已出现在 PlayStation 广告中，粉丝称歌词赋能且与游戏契合；LISA 称联名是通过音乐与时尚放松的有趣方式。", "url": "https://x.com/i/trending/2112545585349738844", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-22T12:24:09.000Z"}, {"id": "2113154981465342189", "domain": "娱乐", "title_en": "LenaMiu Arrive in Taipei for Fan Meeting Excitement", "title_zh": "LenaMiu 抵台北出席粉丝见面会", "hook_en": "Lena and Miu stepped off the plane to fans waving signs and snapping photos, their smiles lighting up the airport amid cheers from Gumber Bears.", "hook_zh": "Lena 与 Miu 走下飞机，粉丝举牌拍照，笑容点亮机场，Gumber Bears 欢呼迎接。", "summary_en": "Thai GL stars Lena Lorena Schuett and Miu Natsha Taechamongkalapiwat, known as LenaMiu, touched down in Taipei on October 22 for their fan meeting the next day at Legacy TERA in Nangang District. Supporters welcomed them warmly with airport gatherings, billboards in Ximending and Shin Kong Mitsukoshi, plus stickers and lucky charms. The duo shared playful moments at an indoor play center, forming heart shapes and bouncing on trampolines, while fans anticipate stories from their hit series like *Pls Love*. Official posts thanked everyone, building hype for the intimate event despite minor weather worries.", "summary_zh": "泰国 GL 明星 Lena Lorena Schuett 与 Miu Natsha Taechamongkalapiwat（组合 LenaMiu）10 月 22 日抵台，次日在南港 Legacy TERA 举办粉丝见面会。支持者在机场热情迎接，西门町与新光三越有广告牌，还有贴纸与幸运符。两人在室内游乐场比心、蹦床玩闹；粉丝期待她们分享《Pls Love》等热剧故事。官方发文致谢并预热亲密活动，仅有轻微天气顾虑。", "body_en": "LenaMiu Arrive in Taipei for Fan Meeting Excitement.\n\nLena and Miu stepped off the plane to fans waving signs and snapping photos, their smiles lighting up the airport amid cheers from Gumber Bears.\n\nThai GL stars Lena Lorena Schuett and Miu Natsha Taechamongkalapiwat, known as LenaMiu, touched down in Taipei on October 22 for their fan meeting the next day at Legacy TERA in Nangang District. Supporters welcomed them warmly with airport gatherings, billboards in Ximending and Shin Kong Mitsukoshi, plus stickers and lucky charms.\n\nThe duo shared playful moments at an indoor play center, forming heart shapes and bouncing on trampolines, while fans anticipate stories from their hit series like *Pls Love*. Official posts thanked everyone, building hype for the intimate event despite minor weather worries.", "body_zh": "LenaMiu 抵台北出席粉丝见面会。\n\nLena 与 Miu 走下飞机，粉丝举牌拍照，笑容点亮机场，Gumber Bears 欢呼迎接。\n\n泰国 GL 明星 Lena Lorena Schuett 与 Miu Natsha Taechamongkalapiwat（组合 LenaMiu）10 月 22 日抵台，次日在南港 Legacy TERA 举办粉丝见面会。支持者在机场热情迎接，西门町与新光三越有广告牌，还有贴纸与幸运符。\n\n两人在室内游乐场比心、蹦床玩闹；粉丝期待她们分享《Pls Love》等热剧故事。官方发文致谢并预热亲密活动，仅有轻微天气顾虑。", "url": "https://x.com/i/trending/2113154981465342189", "category": "Entertainment", "topics": ["Concerts"], "updated_at": "2026-10-22T15:15:39.000Z"}, {"id": "2113014997437861976", "domain": "科学", "title_en": "Trump Signs Order for New NIH Women’s Health Division and White House Task Force", "title_zh": "特朗普签署行政令设立 NIH 女性健康新部门", "hook_en": "In the Oval Office, President Trump and First Lady Melania Trump held up the signed document as officials applauded, marking a fresh push for women's health research.", "hook_zh": "在玫瑰园，特朗普总统对政府竟无专门女性健康部门表示惊讶：「谁他妈会不设女性健康司？」", "summary_en": "On October 19, President Donald Trump signed an executive order creating a new Women’s Health Division at the National Institutes of Health and a White House Women’s Health Task Force, championed by First Lady Melania Trump. The initiative targets conditions like endometriosis, fibroids, infertility, maternal health, menopause, heart disease, Alzheimer’s, osteoporosis, and stroke, while boosting women's inclusion in clinical trials and considering sex as a biological variable in research. Co-chaired by HHS Secretary Robert F. Kennedy Jr. and White House Chief of Staff Susie Wiles, the task force held its first meeting right after the signing to coordinate across federal agencies. Melania Trump called it a new standard serving women from young girls to mature women.", "summary_zh": "10 月 19 日，唐纳德·特朗普总统与第一夫人梅拉尼娅·特朗普签署行政令，在国立卫生研究院设立新的女性健康司，并成立由卫生与公众服务部长罗伯特·F·肯尼迪 Jr. 与幕僚长苏茜·威尔斯共同主持的白宫工作组。倡议针对子宫内膜异位、更年期、孕产妇健康与自身免疫等病症，旨在把研究转化为全生命周期更好照护，同时撤销拜登时期部分相关安排。支持者称其为关键一步；批评者指出 NIH 自 1990 年起已有女性健康研究办公室，呼吁把更多资金聚焦既有机制。", "body_en": "Trump Signs Order for New NIH Women's Health Division.\n\nIn the Rose Garden, President Trump expressed surprise that the government lacked a dedicated women's health unit, asking, 'Who the hell wouldn’t have a woman’s health division?'\n\nOn October 19, President Donald Trump and First Lady Melania Trump signed an executive order creating a new Women’s Health Division at the National Institutes of Health and a White House task force co-chaired by HHS Secretary Robert F. Kennedy Jr.\n\nand Chief of Staff Susie Wiles. The initiative targets conditions like endometriosis, menopause, maternal health, and autoimmune diseases, aiming to translate research into better care across women's lives while rescinding prior Biden-era efforts. Supporters praised it as a vital step, though critics noted the existing NIH Office of Research on Women’s Health since 1990 and called for more funding focus there.", "body_zh": "特朗普签署行政令设立 NIH 女性健康新部门。\n\n在玫瑰园，特朗普总统对政府竟无专门女性健康部门表示惊讶：「谁他妈会不设女性健康司？」\n\n10 月 19 日，唐纳德·特朗普总统与第一夫人梅拉尼娅·特朗普签署行政令，在国立卫生研究院设立新的女性健康司，并成立由卫生与公众服务部长罗伯特·F·肯尼迪 Jr. 与幕僚长苏茜·威尔斯共同主持的白宫工作组。\n\n倡议针对子宫内膜异位、更年期、孕产妇健康与自身免疫等病症，旨在把研究转化为全生命周期更好照护，同时撤销拜登时期部分相关安排。支持者称其为关键一步；批评者指出 NIH 自 1990 年起已有女性健康研究办公室，呼吁把更多资金聚焦既有机制。", "url": "https://x.com/i/trending/2113014997437861976", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T18:53:58.000Z"}, {"id": "2112883739105620216", "domain": "科学", "title_en": "NASENI Launches Drone Training, Skills and Clean Energy Projects in Kaduna", "title_zh": "尼日利亚 NASENI 在卡杜纳启动无人机培训、技能与清洁能源项目", "hook_en": "In Kaduna, NASENI's team broke ground on a skills centre while handing out solar systems to 500 families, aiming to spark self-reliance one household at a time.", "hook_zh": "在卡杜纳，NASENI 团队为技能中心奠基，并向 500 户家庭发放太阳能系统，志在一户一户点燃自立。", "summary_en": "NASENI, led by CEO Khalil Halilu, kicked off key initiatives in Kaduna State, including a new Skills Development Centre in Rigachikun, solar home systems and clean cookstoves for 500 beneficiaries through the Sustainable Empowerment Programme, and a drone training facility at the Air Force Institute of Technology partnered with Caverton. The drone centre has already trained two cohorts, with women comprising at least 60 percent in some groups, reducing dependence on foreign technicians and opening technical jobs. These efforts, joined by Governor Uba Sani, highlight NASENI's push for home-grown tech like locally adapted drones for security and farming, plus 44 products from 20 factories tailored to Nigeria's needs.", "summary_zh": "由 CEO Khalil Halilu 率领的 NASENI 在卡杜纳州启动多项举措：Rigachikun 新技能发展中心、通过可持续赋能计划向 500 名受益人提供太阳能户用系统与清洁炉灶，以及与 Caverton 合作、设于空军理工学院的无人机培训设施。无人机中心已培训两批学员，部分班级女性占比至少 60%，减少对外籍技师依赖并开辟技术岗位。州长 Uba Sani 等到场；行动凸显 NASENI 推动本土适配无人机用于安全与农业，以及 20 家工厂 44 种贴合尼日利亚需求产品的努力。", "body_en": "NASENI Launches Drone Training, Skills and Clean Energy Projects in Kaduna.\n\nIn Kaduna, NASENI's team broke ground on a skills centre while handing out solar systems to 500 families, aiming to spark self-reliance one household at a time.\n\nNASENI, led by CEO Khalil Halilu, kicked off key initiatives in Kaduna State, including a new Skills Development Centre in Rigachikun, solar home systems and clean cookstoves for 500 beneficiaries through the Sustainable Empowerment Programme, and a drone training facility at the Air Force Institute of Technology partnered with Caverton.\n\nThe drone centre has already trained two cohorts, with women comprising at least 60 percent in some groups, reducing dependence on foreign technicians and opening technical jobs. These efforts, joined by Governor Uba Sani, highlight NASENI's push for home-grown tech like locally adapted drones for security and farming, plus 44 products from 20 factories tailored to Nigeria's needs.", "body_zh": "尼日利亚 NASENI 在卡杜纳启动无人机培训、技能与清洁能源项目。\n\n在卡杜纳，NASENI 团队为技能中心奠基，并向 500 户家庭发放太阳能系统，志在一户一户点燃自立。\n\n由 CEO Khalil Halilu 率领的 NASENI 在卡杜纳州启动多项举措：Rigachikun 新技能发展中心、通过可持续赋能计划向 500 名受益人提供太阳能户用系统与清洁炉灶，以及与 Caverton 合作、设于空军理工学院的无人机培训设施。\n\n无人机中心已培训两批学员，部分班级女性占比至少 60%，减少对外籍技师依赖并开辟技术岗位。州长 Uba Sani 等到场；行动凸显 NASENI 推动本土适配无人机用于安全与农业，以及 20 家工厂 44 种贴合尼日利亚需求产品的努力。", "url": "https://x.com/i/trending/2112883739105620216", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-21T21:18:12.000Z"}, {"id": "2112769667550888269", "domain": "科学", "title_en": "APA Faces Accreditation Scrutiny Over Activism in Psychology Conferences", "title_zh": "美国心理学会因会议政治化面临认证审查", "hook_en": "Psychologists gathered in New York for a major conference, but the panels leaned heavily into political themes like abolishing the family and queer anarchist psychoanalysis, with no conservative voices in sight.", "hook_zh": "纽约一场重要心理学会议大量讨论废除家庭、酷儿无政府精神分析等政治议题，几乎不见保守派声音。", "summary_en": "A Wall Street Journal opinion piece by Colin Wright and Andrew Hartz highlights criticism of the American Psychological Association for blending activism with science, spotlighting Division 39's recent conference where about 70 of 90 panels pushed left-wing topics and sessions like 'Feel the F— Fantasy' offered continuing education credits. A bipartisan board voted 7-4 last month to recommend suspending the APA's federal accreditation authority, amid concerns over antisemitism allegations and elected president Candice Hargons' focus on 'systemic intersectional oppression.' Similar issues appear at the American Academy of Child and Adolescent Psychiatry, which declined to discuss evidence on childhood gender transitions. Critics argue this erodes public trust in evidence-based care for vulnerable patients.", "summary_zh": "《华尔街日报》专栏作者科林·赖特与安德鲁·哈茨批评美国心理学会把行动主义与科学混为一谈，聚焦第 39 分会近期会议：约 90 场中有 70 场偏向左翼议题，如「Feel the F— Fantasy」等场次还提供继续教育学分。两党组成的委员会上月以 7-4 建议暂停该学会联邦认证权，同时存在反犹指控与当选主席 Candice Hargons 聚焦「系统性交叉压迫」等争议。美国儿童与青少年精神病学会亦拒谈儿童性别转变证据。批评者称这侵蚀公众对循证照护的信任。", "body_en": "APA Faces Accreditation Scrutiny Over Activism in Psychology Conferences.\n\nPsychologists gathered in New York for a major conference, but the panels leaned heavily into political themes like abolishing the family and queer anarchist psychoanalysis, with no conservative voices in sight.\n\nA Wall Street Journal opinion piece by Colin Wright and Andrew Hartz highlights criticism of the American Psychological Association for blending activism with science, spotlighting Division 39's recent conference where about 70 of 90 panels pushed left-wing topics and sessions like 'Feel the F— Fantasy' offered continuing education credits.\n\nA bipartisan board voted 7-4 last month to recommend suspending the APA's federal accreditation authority, amid concerns over antisemitism allegations and elected president Candice Hargons' focus on 'systemic intersectional oppression.' Similar issues appear at the American Academy of Child and Adolescent Psychiatry, which declined to discuss evidence on childhood gender transitions. Critics argue this erodes public trust in evidence-based care for vulnerable patients.", "body_zh": "美国心理学会因会议政治化面临认证审查。\n\n纽约一场重要心理学会议大量讨论废除家庭、酷儿无政府精神分析等政治议题，几乎不见保守派声音。\n\n《华尔街日报》专栏作者科林·赖特与安德鲁·哈茨批评美国心理学会把行动主义与科学混为一谈，聚焦第 39 分会近期会议：约 90 场中有 70 场偏向左翼议题，如「Feel the F— Fantasy」等场次还提供继续教育学分。两党组成的委员会上月以 7-4 建议暂停该学会联邦认证权，同时存在反犹指控与当选主席 Candice Hargons 聚焦「系统性交叉压迫」等争议。\n\n美国儿童与青少年精神病学会亦拒谈儿童性别转变证据。批评者称这侵蚀公众对循证照护的信任。", "url": "https://x.com/i/trending/2112769667550888269", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T14:50:00.000Z"}, {"id": "2112968032066920582", "domain": "科学", "title_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted", "title_zh": "回顾生物圈 2 号氧气危机与混乱任务", "hook_en": "Eight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.", "hook_zh": "八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。", "summary_en": "Biosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk. Pigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "summary_zh": "造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "body_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted.\n\nEight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.\n\nBiosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk.\n\nPigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "body_zh": "回顾生物圈 2 号氧气危机与混乱任务。\n\n八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。\n\n造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。\n\n猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "url": "https://x.com/i/trending/2112968032066920582", "category": "News", "topics": ["News", "Science"], "updated_at": "2026-10-21T18:10:40.000Z"}, {"id": "2112331788529840225", "domain": "科学", "title_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide", "title_zh": "特朗普削减气象卫星计划，引发专家分歧", "hook_en": "Experts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.", "hook_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。", "summary_en": "The Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion. A Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "summary_zh": "特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。 包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "body_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide.\n\nExperts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.\n\nThe Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion.\n\nA Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "body_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。\n\n特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。\n\n政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "url": "https://x.com/i/trending/2112331788529840225", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:06:32.000Z"}, {"id": "2113301040338801135", "domain": "科学", "title_en": "Air Force Tests Rocket Cargo Delivery with SpaceX Starfall Capsule", "title_zh": "美国空军用 SpaceX Starfall 舱测试火箭货运投送", "hook_en": "Imagine medical kits and survival gear hurtling back from space to land in the ocean, ready for rapid delivery anywhere on Earth.", "hook_zh": "想象医疗包与生存装备从太空坠入海面，随时可向地球任何地点快速投送。", "summary_en": "The U.S. Air Force Research Laboratory launched the Bandwagon-5 mission on October 20 from Cape Canaveral, using a SpaceX Starfall capsule to test rocket-powered cargo delivery. The flight carried agile cargo pods with emergency medical kits, survival gear, batteries, electronics, a satcom tracker, and a water desalinator, while sensors captured data on launch, spaceflight, and reentry stresses. This second flight of the 3.1-meter disk-shaped capsule, which can return up to 1,000 kg under parachutes, advances the Rocket Cargo program for quick resupply to remote or contested areas. Brig. Gen. Douglas P. Wickert called it a key step in partnering with industry to gather data and build war-winning technologies.", "summary_zh": "美国空军研究实验室 10 月 20 日从卡纳维拉尔角发射 Bandwagon-5 任务，用 SpaceX Starfall 返回舱测试火箭动力货运。飞行携带应急医疗包、生存装备、电池、电子设备、卫星通信追踪器与海水淡化器等敏捷货舱，传感器采集发射、在轨与再入应力数据。这是直径约 3.1 米、可伞降返回最多约 1000 公斤的碟形舱第二次飞行，推进「火箭货运」计划，以便向偏远或争议地区快速补给。准将 Douglas P. Wickert 称此为与产业合作采集数据、打造制胜技术的关键一步。", "body_en": "Air Force Tests Rocket Cargo Delivery with SpaceX Starfall Capsule.\n\nImagine medical kits and survival gear hurtling back from space to land in the ocean, ready for rapid delivery anywhere on Earth.\n\nThe U.S. Air Force Research Laboratory launched the Bandwagon-5 mission on October 20 from Cape Canaveral, using a SpaceX Starfall capsule to test rocket-powered cargo delivery. The flight carried agile cargo pods with emergency medical kits, survival gear, batteries, electronics, a satcom tracker, and a water desalinator, while sensors captured data on launch, spaceflight, and reentry stresses. This second flight of the 3.1-meter disk-shaped capsule, which can return up to 1,000 kg under parachutes, advances the Rocket Cargo program for quick resupply to remote or contested areas.\n\nBrig. Gen. Douglas P. Wickert called it a key step in partnering with industry to gather data and build war-winning technologies.", "body_zh": "美国空军用 SpaceX Starfall 舱测试火箭货运投送。\n\n想象医疗包与生存装备从太空坠入海面，随时可向地球任何地点快速投送。\n\n美国空军研究实验室 10 月 20 日从卡纳维拉尔角发射 Bandwagon-5 任务，用 SpaceX Starfall 返回舱测试火箭动力货运。飞行携带应急医疗包、生存装备、电池、电子设备、卫星通信追踪器与海水淡化器等敏捷货舱，传感器采集发射、在轨与再入应力数据。\n\n这是直径约 3.1 米、可伞降返回最多约 1000 公斤的碟形舱第二次飞行，推进「火箭货运」计划，以便向偏远或争议地区快速补给。准将 Douglas P. Wickert 称此为与产业合作采集数据、打造制胜技术的关键一步。", "url": "https://x.com/i/trending/2113301040338801135", "category": "News", "topics": ["Space"], "updated_at": "2026-10-22T16:13:22.000Z"}, {"id": "2112833225118625949", "domain": "科学", "title_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal", "title_zh": "尼日利亚官方辟谣美援协议「禁止药监检测」传言", "hook_en": "Panic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.", "hook_zh": "网传美国协议将阻止尼日利亚药监局检测免费疫苗与药品，恐慌蔓延；官方迅速澄清。", "summary_en": "Viral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof. Mojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "summary_zh": "病毒式信息称约 30 亿美元美国疟疾等援助禁止 NAFDAC 审查物资，引发不安全与主权丧失担忧，并称加纳已拒绝。NAFDAC 总干事 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留全部职权；美 FDA 已批产品因既有依赖获加速审查，但仍做安全检查，非美产品尤甚，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美援用于艾滋等健康项目，尼日利亚亦增支至约 30 亿美元迈向自立。", "body_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal.\n\nPanic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.\n\nViral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof.\n\nMojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "body_zh": "尼日利亚官方辟谣美援协议「禁止药监检测」传言。\n\n网传美国协议将阻止尼日利亚药监局检测免费疫苗与药品，恐慌蔓延；官方迅速澄清。\n\n病毒式信息称约 30 亿美元美国疟疾等援助禁止 NAFDAC 审查物资，引发不安全与主权丧失担忧，并称加纳已拒绝。\n\nNAFDAC 总干事 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留全部职权；美 FDA 已批产品因既有依赖获加速审查，但仍做安全检查，非美产品尤甚，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美援用于艾滋等健康项目，尼日利亚亦增支至约 30 亿美元迈向自立。", "url": "https://x.com/i/trending/2112833225118625949", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T11:29:22.000Z"}, {"id": "2113325561086886275", "domain": "科学", "title_en": "Calley Means Resigns from White House Health Role Amid Frustrations", "title_zh": "Calley Means 辞去白宫健康顾问职务", "hook_en": "Calley Means stepped away from his White House post with praise for key health wins, but frustration over stalled reforms against powerful food interests.", "hook_zh": "Calley Means 离开白宫职位，肯定关键健康成果，但对食品利益集团阻碍改革感到沮丧。", "summary_en": "As a senior adviser to HHS Secretary Robert F. Kennedy Jr. and a Make America Healthy Again leader, Means announced his resignation Thursday, citing achievements like updated Dietary Guidelines, psychedelic research reforms, SNAP soda restrictions, food dye removals, GRAS changes, and healthier government food buys. He grew disillusioned with delays on priorities such as defining ultraprocessed foods and improving school meals, amid reports of food company influence inside the administration. Kennedy thanked him for his vision on food reform and children's health, while the exit highlighted tensions over the pace of change, with food stocks rising in response.", "summary_zh": "作为 HHS 部长罗伯特·F·肯尼迪 Jr. 高级顾问与「让美国再次健康」推动者，Means 周四宣布辞职，列举膳食指南更新、致幻剂研究改革、SNAP 汽水限制、食品染料移除、GRAS 调整与政府采购更健康食品等成就。他对超加工食品定义与学校餐改善等优先事项拖延失望，并有食品公司影响政府内部的报道。肯尼迪感谢其对食品改革与儿童健康的愿景；离职凸显变革节奏张力，食品股随之上涨。", "body_en": "Calley Means Resigns from White House Health Role Amid Frustrations.\n\nCalley Means stepped away from his White House post with praise for key health wins, but frustration over stalled reforms against powerful food interests.\n\nAs a senior adviser to HHS Secretary Robert F. Kennedy Jr.\n\nand a Make America Healthy Again leader, Means announced his resignation Thursday, citing achievements like updated Dietary Guidelines, psychedelic research reforms, SNAP soda restrictions, food dye removals, GRAS changes, and healthier government food buys. He grew disillusioned with delays on priorities such as defining ultraprocessed foods and improving school meals, amid reports of food company influence inside the administration. Kennedy thanked him for his vision on food reform and children's health, while the exit highlighted tensions over the pace of change, with food stocks rising in response.", "body_zh": "Calley Means 辞去白宫健康顾问职务。\n\nCalley Means 离开白宫职位，肯定关键健康成果，但对食品利益集团阻碍改革感到沮丧。\n\n作为 HHS 部长罗伯特·F·肯尼迪 Jr. 高级顾问与「让美国再次健康」推动者，Means 周四宣布辞职，列举膳食指南更新、致幻剂研究改革、SNAP 汽水限制、食品染料移除、GRAS 调整与政府采购更健康食品等成就。\n\n他对超加工食品定义与学校餐改善等优先事项拖延失望，并有食品公司影响政府内部的报道。肯尼迪感谢其对食品改革与儿童健康的愿景；离职凸显变革节奏张力，食品股随之上涨。", "url": "https://x.com/i/trending/2113325561086886275", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-22T22:54:44.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Warming Limit Now Unavoidable Overshoot", "title_zh": "联合国报告：1.5°C 升温上限已不可避免被突破", "hook_en": "The UN has delivered sobering news: the world will exceed the 1.5°C Paris Agreement target in the coming years, no matter what.", "hook_zh": "联合国带来沉重消息：无论怎样，世界将在未来数年超过《巴黎协定》1.5°C 目标。", "summary_en": "The UN Environment Programme's Emissions Gap Report 2026 states that current policies point to up to 2.8°C warming by 2100, with even full national pledges leading to 2.6°C. The best path now limits peak warming to 1.7-1.8°C mid-century, returning to 1.5°C by 2100 through 18% emissions cuts by 2030, 45% by 2035, and 69% by 2040, plus carbon removal. UN Secretary-General António Guterres emphasized that every fraction of a degree counts amid record emissions, while U.S. withdrawal from Paris and rising emissions have worsened the outlook. Renewables offer hope as the cheapest new power source, urging leaders to scale successes before the next summit.", "summary_zh": "联合国环境规划署《2026 排放差距报告》称，现行政策指向本世纪末升温最高约 2.8°C，即便兑现全部国家承诺仍约 2.6°C。当前最佳路径是把峰值升温限在本世纪中叶约 1.7–1.8°C，再通过 2030 年减排 18%、2035 年 45%、2040 年 69% 并配合碳移除，到 2100 年回到 1.5°C。古特雷斯强调在排放创新高时每一小数点都重要；美国退出巴黎协定与排放上升恶化前景。可再生已成为最便宜新增电源，呼吁峰会前扩大成功经验。", "body_en": "UN Report: 1.5°C Warming Limit Now Unavoidable Overshoot.\n\nThe UN has delivered sobering news: the world will exceed the 1.5°C Paris Agreement target in the coming years, no matter what.\n\nThe UN Environment Programme's Emissions Gap Report 2026 states that current policies point to up to 2.8°C warming by 2100, with even full national pledges leading to 2.6°C. The best path now limits peak warming to 1.7-1.8°C mid-century, returning to 1.5°C by 2100 through 18% emissions cuts by 2030, 45% by 2035, and 69% by 2040, plus carbon removal.\n\nUN Secretary-General António Guterres emphasized that every fraction of a degree counts amid record emissions, while U.S. withdrawal from Paris and rising emissions have worsened the outlook. Renewables offer hope as the cheapest new power source, urging leaders to scale successes before the next summit.", "body_zh": "联合国报告：1.5°C 升温上限已不可避免被突破。\n\n联合国带来沉重消息：无论怎样，世界将在未来数年超过《巴黎协定》1.5°C 目标。\n\n联合国环境规划署《2026 排放差距报告》称，现行政策指向本世纪末升温最高约 2.8°C，即便兑现全部国家承诺仍约 2.6°C。当前最佳路径是把峰值升温限在本世纪中叶约 1.7–1.8°C，再通过 2030 年减排 18%、2035 年 45%、2040 年 69% 并配合碳移除，到 2100 年回到 1.5°C。\n\n古特雷斯强调在排放创新高时每一小数点都重要；美国退出巴黎协定与排放上升恶化前景。可再生已成为最便宜新增电源，呼吁峰会前扩大成功经验。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["News"], "updated_at": "2026-10-22T16:13:27.000Z"}, {"id": "2113231352904683817", "domain": "科学", "title_en": "Hugging Face Launches Carbon-X to Chat with DNA in Plain English", "title_zh": "Hugging Face 发布 Carbon-X：用自然语言「对话」DNA", "hook_en": "Imagine asking an AI in everyday words what a DNA mutation might do—and getting a clear answer. Hugging Face's new Carbon-X makes that possible for researchers everywhere.", "hook_zh": "用日常语言问 AI 某段 DNA 突变可能做什么——并得到清楚回答。Hugging Face 的 Carbon-X 让各地研究者做到这一点。", "summary_en": "Carbon-X is a 14-billion-parameter open-source AI model built on Qwen3-14B and trained on 300 billion tokens of DNA, English, and biology data. It excels on benchmarks for DNA understanding and mutation prediction, scoring 66.7%—better than other open models and nearly matching top closed systems at a fraction of the cost. CEO Clément Delangue released it under Apache 2.0 to counter access limits by frontier labs, allowing local runs on a single GPU or laptop while keeping sensitive data private. The tool aids drug design and gene therapies as a research starting point, though outputs need lab validation before medical use.", "summary_zh": "Carbon-X 是基于 Qwen3-14B、在 3000 亿 DNA/英语/生物学 token 上训练的 140 亿参数开源模型。它在 DNA 理解与突变预测基准上得分 66.7%，优于其他开源模型，接近顶尖闭源系统且成本低得多。CEO Clément Delangue 以 Apache 2.0 发布，以对抗前沿实验室的访问限制，可在单卡或笔记本本地运行并保护敏感数据。工具可用于药物设计与基因治疗研究起点，但产出须经实验室验证方可医用。", "body_en": "Hugging Face Launches Carbon-X to Chat with DNA in Plain English.\n\nImagine asking an AI in everyday words what a DNA mutation might do—and getting a clear answer. Hugging Face's new Carbon-X makes that possible for researchers everywhere.\n\nCarbon-X is a 14-billion-parameter open-source AI model built on Qwen3-14B and trained on 300 billion tokens of DNA, English, and biology data. It excels on benchmarks for DNA understanding and mutation prediction, scoring 66.7%—better than other open models and nearly matching top closed systems at a fraction of the cost.\n\nCEO Clément Delangue released it under Apache 2.0 to counter access limits by frontier labs, allowing local runs on a single GPU or laptop while keeping sensitive data private. The tool aids drug design and gene therapies as a research starting point, though outputs need lab validation before medical use.", "body_zh": "Hugging Face 发布 Carbon-X：用自然语言「对话」DNA。\n\n用日常语言问 AI 某段 DNA 突变可能做什么——并得到清楚回答。Hugging Face 的 Carbon-X 让各地研究者做到这一点。\n\nCarbon-X 是基于 Qwen3-14B、在 3000 亿 DNA/英语/生物学 token 上训练的 140 亿参数开源模型。它在 DNA 理解与突变预测基准上得分 66.7%，优于其他开源模型，接近顶尖闭源系统且成本低得多。\n\nCEO Clément Delangue 以 Apache 2.0 发布，以对抗前沿实验室的访问限制，可在单卡或笔记本本地运行并保护敏感数据。工具可用于药物设计与基因治疗研究起点，但产出须经实验室验证方可医用。", "url": "https://x.com/i/trending/2113231352904683817", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-22T18:53:51.000Z"}, {"id": "2113277137071567258", "domain": "科学", "title_en": "Global Coral Reefs Face Collapse Risk, Great Barrier Reef Shows Strong Recovery", "title_zh": "全球珊瑚礁面临崩溃风险，大堡礁却现强劲恢复", "hook_en": "While a new global report warns most shallow-water coral reefs could collapse by 2075, recent checks reveal Australia's Great Barrier Reef with some of its highest coral cover ever.", "hook_zh": "新全球报告警告多数浅水珊瑚礁或在 2075 年前崩溃，而近期调查显示澳大利亚大堡礁珊瑚覆盖率处于监测以来高位。", "summary_en": "The International Union for Conservation of Nature assessed 96% of shallow-water coral reefs as critically endangered, mainly due to ocean warming from heat stress, projecting high collapse risks by 2075 even under moderate emissions. Yet Australian Institute of Marine Science data from 2025-26 shows the Great Barrier Reef's northern and central regions at 35.1% and 31.6% hard coral cover—among the top five years since monitoring started, despite past bleaching. The report notes reefs remain mostly intact today, with recovery possible through emissions cuts and local protections like curbing overfishing and pollution.", "summary_zh": "世界自然保护联盟评估约 96% 浅水珊瑚礁为极危，主因热应激导致的海洋升温，即便中等排放情景下 2075 年前崩溃风险仍高。但澳大利亚海洋科学研究所 2025–26 年数据显示，大堡礁北部与中部硬珊瑚覆盖率达 35.1% 与 31.6%——为监测开始以来最好的五个年份之一，尽管曾有白化。报告称礁体今日大体仍存，通过减排与限制过度捕捞、污染等本地保护仍可恢复。", "body_en": "Global Coral Reefs Face Collapse Risk, Great Barrier Reef Shows Strong Recovery.\n\nWhile a new global report warns most shallow-water coral reefs could collapse by 2075, recent checks reveal Australia's Great Barrier Reef with some of its highest coral cover ever.\n\nThe International Union for Conservation of Nature assessed 96% of shallow-water coral reefs as critically endangered, mainly due to ocean warming from heat stress, projecting high collapse risks by 2075 even under moderate emissions.\n\nYet Australian Institute of Marine Science data from 2025-26 shows the Great Barrier Reef's northern and central regions at 35.1% and 31.6% hard coral cover—among the top five years since monitoring started, despite past bleaching. The report notes reefs remain mostly intact today, with recovery possible through emissions cuts and local protections like curbing overfishing and pollution.", "body_zh": "全球珊瑚礁面临崩溃风险，大堡礁却现强劲恢复。\n\n新全球报告警告多数浅水珊瑚礁或在 2075 年前崩溃，而近期调查显示澳大利亚大堡礁珊瑚覆盖率处于监测以来高位。\n\n世界自然保护联盟评估约 96% 浅水珊瑚礁为极危，主因热应激导致的海洋升温，即便中等排放情景下 2075 年前崩溃风险仍高。\n\n但澳大利亚海洋科学研究所 2025–26 年数据显示，大堡礁北部与中部硬珊瑚覆盖率达 35.1% 与 31.6%——为监测开始以来最好的五个年份之一，尽管曾有白化。报告称礁体今日大体仍存，通过减排与限制过度捕捞、污染等本地保护仍可恢复。", "url": "https://x.com/i/trending/2113277137071567258", "category": "News", "topics": ["Nature & Outdoors"], "updated_at": "2026-10-22T17:27:07.000Z"}, {"id": "2112952170131968189", "domain": "科学", "title_en": "Neuroscientists Argue AI Lacks Path to Consciousness", "title_zh": "神经科学家论证：现有路径下 AI 难有意识", "hook_en": "Imagine tasting ice cream or watching a sunset—those vivid feelings vanish in dreamless sleep. A new Nature commentary asks if silicon-based AI can ever truly feel that way.", "hook_zh": "想象冰淇淋味道或日落——这些鲜活感受在无梦睡眠中消失。《自然》新评论追问：硅基 AI 能否真正「感到」这些？", "summary_en": "Neuroscientists Anil Seth and Giulio Tononi, with philosopher Ned Block, explain in Nature why current AI like large language models isn't conscious and likely won't be on existing paths. They highlight three points: intelligence alone doesn't create experience, biology's living processes matter in ways chips don't match, and brain-like causal structures are missing in AI designs. The piece draws praise from figures like Steven Pinker for its clarity, while critics like François Fleuret question if biology is truly essential or just an unproven assumption, fueling ongoing philosophy of mind debates.", "summary_zh": "神经科学家 Anil Seth、Giulio Tononi 与哲学家 Ned Block 在《自然》解释，为何当前大语言模型等 AI 无意识，且在现有路径上很可能仍无。他们强调三点：智力本身不产生体验；生物学生命过程以芯片难以匹配的方式重要；AI 设计缺少脑般因果结构。史蒂文·平克等赞其清晰；批评者如 François Fleuret 质疑生物学是否真正必要，或只是未证假设，延续心灵哲学辩论。", "body_en": "Neuroscientists Argue AI Lacks Path to Consciousness.\n\nImagine tasting ice cream or watching a sunset—those vivid feelings vanish in dreamless sleep. A new Nature commentary asks if silicon-based AI can ever truly feel that way.\n\nNeuroscientists Anil Seth and Giulio Tononi, with philosopher Ned Block, explain in Nature why current AI like large language models isn't conscious and likely won't be on existing paths.\n\nThey highlight three points: intelligence alone doesn't create experience, biology's living processes matter in ways chips don't match, and brain-like causal structures are missing in AI designs. The piece draws praise from figures like Steven Pinker for its clarity, while critics like François Fleuret question if biology is truly essential or just an unproven assumption, fueling ongoing philosophy of mind debates.", "body_zh": "神经科学家论证：现有路径下 AI 难有意识。\n\n想象冰淇淋味道或日落——这些鲜活感受在无梦睡眠中消失。《自然》新评论追问：硅基 AI 能否真正「感到」这些？\n\n神经科学家 Anil Seth、Giulio Tononi 与哲学家 Ned Block 在《自然》解释，为何当前大语言模型等 AI 无意识，且在现有路径上很可能仍无。\n\n他们强调三点：智力本身不产生体验；生物学生命过程以芯片难以匹配的方式重要；AI 设计缺少脑般因果结构。史蒂文·平克等赞其清晰；批评者如 François Fleuret 质疑生物学是否真正必要，或只是未证假设，延续心灵哲学辩论。", "url": "https://x.com/i/trending/2112952170131968189", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T20:40:15.000Z"}, {"id": "2113360225780863387", "domain": "科学", "title_en": "Microsoft AI Outperforms Doctors on Complex Diagnoses with Lower Costs", "title_zh": "微软 AI 复杂诊断准确率超医生且成本更低", "hook_en": "Imagine an AI system diagnosing tough medical cases twice as accurately as doctors, while ordering fewer tests and saving money. That's what new research shows from Microsoft.", "hook_zh": "AI 系统在棘手病例上诊断准确率约为医生两倍，还开更少检查、更省钱——微软新研究如此显示。", "summary_en": "Microsoft's AI Diagnostic Orchestrator hit 83% accuracy on over 300 complex New England Journal of Medicine cases, far surpassing the 36% from physicians using references. It also excelled on emergency department scenarios, reaching diagnoses 1.7 times more accurately than doctors at reduced costs with fewer tests. The system coordinates multiple AI agents like a specialist panel, iteratively questioning, testing, and debating. On the same day, Ant Group open-sourced Ling-3.0-flash-Sante, a powerful healthcare AI model topping benchmarks in medical reasoning and multi-agent tasks.", "summary_zh": "微软 AI 诊断编排器在逾 300 个《新英格兰医学杂志》复杂病例上准确率达 83%，远超参考条件下医生的 36%。在急诊场景亦表现突出，诊断准确约为医生 1.7 倍，成本更低、检查更少。系统如专家小组协调多个 AI 智能体，迭代提问、检验与辩论。同日蚂蚁集团开源 Ling-3.0-flash-Sante，在医疗推理与多智能体任务基准领先。", "body_en": "Microsoft AI Outperforms Doctors on Complex Diagnoses with Lower Costs.\n\nImagine an AI system diagnosing tough medical cases twice as accurately as doctors, while ordering fewer tests and saving money. That's what new research shows from Microsoft.\n\nMicrosoft's AI Diagnostic Orchestrator hit 83% accuracy on over 300 complex New England Journal of Medicine cases, far surpassing the 36% from physicians using references. It also excelled on emergency department scenarios, reaching diagnoses 1.7 times more accurately than doctors at reduced costs with fewer tests.\n\nThe system coordinates multiple AI agents like a specialist panel, iteratively questioning, testing, and debating. On the same day, Ant Group open-sourced Ling-3.0-flash-Sante, a powerful healthcare AI model topping benchmarks in medical reasoning and multi-agent tasks.", "body_zh": "微软 AI 复杂诊断准确率超医生且成本更低。\n\nAI 系统在棘手病例上诊断准确率约为医生两倍，还开更少检查、更省钱——微软新研究如此显示。\n\n微软 AI 诊断编排器在逾 300 个《新英格兰医学杂志》复杂病例上准确率达 83%，远超参考条件下医生的 36%。在急诊场景亦表现突出，诊断准确约为医生 1.7 倍，成本更低、检查更少。\n\n系统如专家小组协调多个 AI 智能体，迭代提问、检验与辩论。同日蚂蚁集团开源 Ling-3.0-flash-Sante，在医疗推理与多智能体任务基准领先。", "url": "https://x.com/i/trending/2113360225780863387", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-22T22:54:47.000Z"}]};
